// ══════════════════════════════════════════════════════════════════
//  AdvSoft Layout Service — Odoo Enterprise Presentation Layer
//  Manages: Theme, Layout Mode, Device Detection, Density, Brand
// ══════════════════════════════════════════════════════════════════
(function () {
    const STORAGE_KEY = 'AdvSoft_layout';

    const BRAND_COLORS = [
        { id: 'purple', label: 'Purple', color: '#714B67' },
        { id: 'blue',   label: 'Blue',   color: '#3B82F6' },
        { id: 'indigo', label: 'Indigo', color: '#6366F1' },
        { id: 'green',  label: 'Green',  color: '#059669' },
        { id: 'teal',   label: 'Teal',   color: '#0D9488' },
        { id: 'red',    label: 'Red',    color: '#DC2626' },
        { id: 'amber',  label: 'Amber',  color: '#D97706' },
        { id: 'slate',  label: 'Slate',  color: '#475569' },
    ];

    // ── Defaults ─────────────────────────────────────
    const DEFAULTS = {
        theme: 'light',          // light | dark | auto
        brandColor: 'purple',    // id from BRAND_COLORS
        density: 'default',      // compact | default | comfortable
        settingsOpen: false,
        mobileMenuOpen: false,
    };

    // ── Load persisted preferences ───────────────────
    function loadPrefs() {
        try {
            const raw = localStorage.getItem(STORAGE_KEY);
            return raw ? { ...DEFAULTS, ...JSON.parse(raw) } : { ...DEFAULTS };
        } catch (e) {
            return { ...DEFAULTS };
        }
    }

    function savePrefs(prefs) {
        try {
            localStorage.setItem(STORAGE_KEY, JSON.stringify({
                theme: prefs.theme,
                brandColor: prefs.brandColor,
                density: prefs.density,
            }));
        } catch (e) { /* quota exceeded – ignore */ }
    }

    // ── Device detection ─────────────────────────────
    function detectDevice() {
        const w = window.innerWidth;
        if (w <= 768) return 'mobile';
        if (w <= 1024) return 'tablet';
        return 'desktop';
    }

    // ── Apply theme to DOM ───────────────────────────
    function applyTheme(theme) {
        document.documentElement.setAttribute('data-theme', theme);
    }

    function applyBrandColor(brandId) {
        const brand = BRAND_COLORS.find(b => b.id === brandId) || BRAND_COLORS[0];
        const r = document.documentElement;
        r.style.setProperty('--ls-primary', brand.color);
        r.style.setProperty('--ls-navbar-bg', brand.color);
        // Generate lighter/darker variants
        r.style.setProperty('--ls-primary-light', adjustBrightness(brand.color, 20));
        r.style.setProperty('--ls-primary-dark', adjustBrightness(brand.color, -15));
    }

    function applyDensity(density) {
        document.documentElement.setAttribute('data-density', density);
    }

    // ── Color utility ────────────────────────────────
    function adjustBrightness(hex, percent) {
        hex = hex.replace('#', '');
        let r = parseInt(hex.substr(0, 2), 16);
        let g = parseInt(hex.substr(2, 2), 16);
        let b = parseInt(hex.substr(4, 2), 16);
        r = Math.min(255, Math.max(0, r + Math.round(r * percent / 100)));
        g = Math.min(255, Math.max(0, g + Math.round(g * percent / 100)));
        b = Math.min(255, Math.max(0, b + Math.round(b * percent / 100)));
        return '#' + [r, g, b].map(v => v.toString(16).padStart(2, '0')).join('');
    }

    // ── LayoutService Singleton ──────────────────────
    class LayoutService {
        constructor() {
            this.prefs = loadPrefs();
            this.device = detectDevice();
            this._listeners = [];

            // Apply on load
            applyTheme(this.prefs.theme);
            applyBrandColor(this.prefs.brandColor);
            applyDensity(this.prefs.density);

            // Respond to window resize
            let resizeTimer;
            window.addEventListener('resize', () => {
                clearTimeout(resizeTimer);
                resizeTimer = setTimeout(() => {
                    const newDevice = detectDevice();
                    if (newDevice !== this.device) {
                        this.device = newDevice;
                        this._notify();
                    }
                }, 150);
            });

            // Respond to system theme change
            if (window.matchMedia) {
                window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
                    if (this.prefs.theme === 'auto') {
                        this._notify();
                    }
                });
            }
        }

        // ── Getters ──────────────────────────────────
        get theme() { return this.prefs.theme; }
        get brandColor() { return this.prefs.brandColor; }
        get density() { return this.prefs.density; }
        get isMobile() { return this.device === 'mobile'; }
        get isTablet() { return this.device === 'tablet'; }
        get isDesktop() { return this.device === 'desktop'; }
        get settingsOpen() { return this.prefs.settingsOpen; }
        get mobileMenuOpen() { return this.prefs.mobileMenuOpen; }
        get brandColors() { return BRAND_COLORS; }

        get effectiveTheme() {
            if (this.prefs.theme !== 'auto') return this.prefs.theme;
            return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches
                ? 'dark' : 'light';
        }

        // ── Setters ──────────────────────────────────
        setTheme(theme) {
            this.prefs.theme = theme;
            applyTheme(theme);
            savePrefs(this.prefs);
            this._notify();
        }

        setBrandColor(brandId) {
            this.prefs.brandColor = brandId;
            applyBrandColor(brandId);
            savePrefs(this.prefs);
            this._notify();
        }

        setDensity(density) {
            this.prefs.density = density;
            applyDensity(density);
            savePrefs(this.prefs);
            this._notify();
        }

        toggleSettings() {
            this.prefs.settingsOpen = !this.prefs.settingsOpen;
            if (this.prefs.settingsOpen) this.prefs.mobileMenuOpen = false;
            this._notify();
        }

        closeSettings() {
            this.prefs.settingsOpen = false;
            this._notify();
        }

        toggleMobileMenu() {
            this.prefs.mobileMenuOpen = !this.prefs.mobileMenuOpen;
            if (this.prefs.mobileMenuOpen) this.prefs.settingsOpen = false;
            this._notify();
        }

        closeMobileMenu() {
            this.prefs.mobileMenuOpen = false;
            this._notify();
        }

        // ── Observer pattern ─────────────────────────
        onChange(fn) {
            this._listeners.push(fn);
            return () => {
                this._listeners = this._listeners.filter(f => f !== fn);
            };
        }

        _notify() {
            for (const fn of this._listeners) {
                try { fn(this); } catch (e) { console.error('[LayoutService]', e); }
            }
        }

        // ── Get state snapshot for Owl ────────────────
        toState() {
            return {
                theme: this.prefs.theme,
                effectiveTheme: this.effectiveTheme,
                brandColor: this.prefs.brandColor,
                density: this.prefs.density,
                device: this.device,
                isMobile: this.isMobile,
                isTablet: this.isTablet,
                isDesktop: this.isDesktop,
                settingsOpen: this.prefs.settingsOpen,
                mobileMenuOpen: this.prefs.mobileMenuOpen,
                brandColors: BRAND_COLORS,
            };
        }
    }

    // Create singleton and expose globally
    window.AdvSoftLayout = new LayoutService();
    window.AdvsoftLayout = window.AdvSoftLayout;
    window.LarasoftLayout = window.AdvSoftLayout;

})();


/* --- [FILE: js/core/owl-templates.js] --- */
// Owl App - Part 1: Templates (Fully Dynamic — Odoo <tree> Architecture)
(function(){
const { xml } = owl;

window.TEMPLATES = window.TEMPLATES || {};

// Helper functions for dynamic templates
window.listHelpers = {
    renderListCell: (fieldDef, value) => {
        if (!window.FieldWidgets) return String(value ?? '');
        return window.FieldWidgets.renderList(fieldDef, value);
    },
    getFieldLabel: (viewDef, fieldName, fields) => {
        // Try column defs first, then field_defs, then format name
        if (viewDef?.columns) {
            const col = viewDef.columns.find(c => c.name === fieldName);
            if (col?.string) return col.string;
        }
        const fromView = (viewDef?.field_defs || {})[fieldName]?.string;
        if (fromView) return fromView;
        const fromFields = (fields || {})[fieldName]?.string;
        if (fromFields) return fromFields;
        return fieldName.replace(/_/g, ' ').replace(/\bid\b/g, '').trim().replace(/^\w/, c => c.toUpperCase()) || fieldName;
    }
};

window.TEMPLATES.App = xml`
<div class="ls-app">
    <div class="ls-control-panel">
        <div class="ls-cp-top">
            <div class="ls-breadcrumb">
                <span class="ls-breadcrumb-item" t-esc="props.actionTitle || 'Records'"/>
            </div>
            
            <div class="ls-searchbar-row">
                <div class="ls-searchbar" t-on-click="focusSearch" t-ref="searchbar">
                    <span class="ls-searchbar-icon"><t t-out="icons.search"/></span>
                    <t t-foreach="state.facets" t-as="facet" t-key="facet.id">
                        <span t-att-class="'ls-facet ls-facet-' + facet.type + (facet.negated ? ' ls-facet-negated' : '')">
                            <span class="ls-facet-label" t-esc="facet.label"/>
                            <t t-if="facet.type === 'filter' or facet.type === 'search'">
                                <button class="ls-facet-negate" t-on-click.stop="() => this.toggleFacetNegate(facet.id)"
                                        t-att-title="facet.negated ? 'Remove negation' : 'Exclude this filter'">!</button>
                            </t>
                            <span class="ls-facet-value" t-esc="facet.display"/>
                            <button class="ls-facet-close" t-on-click.stop="() => this.removeFacet(facet.id)">✕</button>
                        </span>
                    </t>
                    <input class="ls-search-input" t-ref="searchInput" placeholder="Search..."
                        t-on-keydown="onSearchKeydown" t-on-input="onSearchInput" t-on-focus="onSearchFocus"/>

                    <t t-if="state.showAutocomplete and state.searchQuery.length > 0">
                        <div class="ls-autocomplete">
                            <div class="ls-autocomplete-section">
                                <div class="ls-autocomplete-title">Search for: <b t-esc="state.searchQuery"/></div>
                                <div class="ls-autocomplete-item" t-on-click="applyTextSearch">in <b>All Fields</b></div>
                            </div>
                            <t t-foreach="autocompleteFields" t-as="af" t-key="af.field">
                                <div class="ls-autocomplete-section">
                                    <div class="ls-autocomplete-title" t-esc="af.label"/>
                                    <div class="ls-autocomplete-item" t-on-click="() => this.applyFieldSearch(af.field, af.operator)">
                                        <b t-esc="state.searchQuery"/>
                                    </div>
                                </div>
                            </t>
                        </div>
                    </t>

                    <t t-if="state.showSearchPanel">
                        <div class="ls-search-dropdown" t-on-click.stop="">
                            <div class="ls-search-section">
                                <div class="ls-search-section-title filters-title">
                                    <t t-out="icons.filter"/> Filters
                                </div>
                                <t t-foreach="filterItems" t-as="fi" t-key="fi.id">
                                    <div t-att-class="'ls-search-item' + (isFilterActive(fi.id) ? ' active' : '')"
                                         t-on-click="() => this.toggleFilter(fi)">
                                        <span class="ls-search-item-check"/>
                                        <span t-esc="fi.label"/>
                                    </div>
                                </t>
                                <div class="ls-search-separator"/>
                                <div class="ls-search-item" t-on-click="toggleCustomFilter" style="color:var(--ls-primary);font-weight:500;">
                                    Custom Filter...
                                </div>
                                <t t-if="state.showCustomFilter">
                                    <div class="ls-custom-filter-row">
                                        <select t-ref="cfField">
                                            <t t-foreach="customFilterFields" t-as="cf" t-key="cf.field">
                                                <option t-att-value="cf.field" t-esc="cf.label"/>
                                            </t>
                                        </select>
                                        <select t-ref="cfOp">
                                            <option value="ilike">contains</option>
                                            <option value="=">is equal to</option>
                                            <option value="!=">is not equal to</option>
                                            <option value="gt">greater than</option>
                                            <option value="lt">less than</option>
                                            <option value="is_set">is set</option>
                                            <option value="is_not_set">is not set</option>
                                        </select>
                                        <input t-ref="cfVal" placeholder="Value"/>
                                        <button class="ls-btn ls-btn-sm ls-btn-primary" t-on-click="applyCustomFilter">Apply</button>
                                    </div>
                                </t>
                            </div>

                            <div class="ls-search-section">
                                <div class="ls-search-section-title groupby-title">
                                    <t t-out="icons.group"/> Group By
                                </div>
                                <t t-foreach="groupByItems" t-as="gi" t-key="gi.field">
                                    <div t-att-class="'ls-search-item' + (isGroupByActive(gi.field) ? ' active' : '')"
                                         t-on-click="() => this.toggleGroupBy(gi.field)">
                                        <span class="ls-search-item-check"/>
                                        <span t-esc="gi.label"/>
                                    </div>
                                </t>
                            </div>

                            <div class="ls-search-section">
                                <div class="ls-search-section-title favorites-title">
                                    <t t-out="icons.star"/> Favorites
                                </div>
                                <t t-foreach="state.savedFilters" t-as="sf" t-key="sf.id">
                                    <div class="ls-search-item" t-on-click="() => this.applySavedFilter(sf)" style="justify-content:space-between;">
                                        <span t-esc="sf.name"/>
                                        <button class="ls-btn-link" style="font-size:11px;color:var(--ls-danger);padding:0;"
                                                t-on-click.stop="() => this.deleteSavedFilter(sf.id)">✕</button>
                                    </div>
                                </t>
                                <div class="ls-search-separator"/>
                                <div class="ls-search-item" t-on-click="toggleSaveFav" style="color:var(--ls-primary);font-weight:500;">
                                    Save current search
                                </div>
                                <t t-if="state.showSaveFav">
                                    <div class="ls-save-fav">
                                        <input type="text" t-ref="favName" placeholder="Filter name..."/>
                                        <label><input type="checkbox" t-ref="favDefault"/> Use by default</label>
                                        <label><input type="checkbox" t-ref="favShared"/> Share with all users</label>
                                        <div class="ls-save-fav-actions">
                                            <button class="ls-btn ls-btn-sm ls-btn-primary" t-on-click="saveFavorite">Save</button>
                                        </div>
                                    </div>
                                </t>
                            </div>
                        </div>
                    </t>
                </div>
                <button class="ls-search-panel-toggle" t-on-click.stop="toggleSearchPanel">
                    <t t-out="icons.chevDown"/>
                </button>
            </div>
        </div>

        <div class="ls-cp-bottom">
            <div class="ls-cp-action-buttons">
                <t t-if="listEditable">
                    <button class="ls-btn ls-btn-primary" t-on-click="onNewInline">New</button>
                </t>
                <t t-else="">
                    <button class="ls-btn ls-btn-primary" t-on-click="onNewTask">New</button>
                </t>
                <div class="ls-print-menu" style="position:relative; display:inline-block;" t-if="state.printActions and state.printActions.length > 0">
                    <button class="ls-btn" t-on-click="togglePrintMenu" title="Print Reports">
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right:4px; vertical-align:middle;">
                            <polyline points="6 9 6 2 18 2 18 9"></polyline>
                            <path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path>
                            <rect x="6" y="14" width="12" height="8"></rect>
                        </svg> Print
                        <span class="ls-submenu-caret" style="margin-left:4px;">▾</span>
                    </button>
                    <div class="ls-submenu-dropdown" t-if="state.showPrintMenu" style="position:absolute; top:100%; left:0; z-index:1000; display:flex; flex-direction:column; min-width:180px; text-align:left;">
                        <t t-foreach="state.printActions" t-as="action" t-key="action.id">
                            <div class="ls-submenu-dropdown-item" t-on-click="() => this.printReport(action.id)">
                                <span t-esc="action.name"/>
                            </div>
                        </t>
                    </div>
                </div>

                <!-- Header buttons (multi-record actions) — shown when records selected -->
                <t t-if="state.selectedIds.length > 0 and headerButtons.length > 0">
                    <t t-foreach="headerButtons" t-as="hb" t-key="hb.name">
                        <button t-att-class="'ls-btn ' + (hb.class || 'ls-btn-secondary')"
                                t-on-click="() => this.onHeaderButton(hb)">
                            <t t-if="hb.icon" t-out="window.lucideIcon ? window.lucideIcon(hb.icon, 14) : ''"/>
                            <span t-esc="hb.string"/>
                        </button>
                    </t>
                </t>
            </div>
            <div class="ls-cp-pager-switchers">
                <div class="ls-pager" t-if="!state.groupBy">
                    <span t-esc="pagerText"/>
                    <div class="ls-pager-nav">
                        <button t-on-click="prevPage" t-att-disabled="state.offset === 0">‹</button>
                        <button t-on-click="nextPage" t-att-disabled="state.offset + state.limit >= state.totalCount">›</button>
                    </div>
                </div>

                <div class="ls-view-switcher" t-if="props.viewModes and props.viewModes.length > 1">
                    <t t-foreach="props.viewModes" t-as="vm" t-key="vm.type">
                        <button t-att-class="'ls-btn-icon' + (props.activeViewType === vm.type ? ' active' : '')"
                                t-on-click="() => props.onSwitchView(vm.type)"
                                t-att-title="vm.label">
                            <t t-out="vm.icon"/>
                        </button>
                    </t>
                </div>
            </div>
        </div>

        <!-- Multi-edit banner -->
        <t t-if="multiEditActive">
            <div class="ls-multi-edit-banner">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/>
                    <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/>
                </svg>
                <span>Multi-Edit: <b t-esc="state.selectedIds.length"/> records selected — changes will apply to all</span>
                <button class="ls-btn ls-btn-sm" t-on-click="clearSelection">Cancel</button>
            </div>
        </t>
    </div>

    <div class="ls-list-content-area">
        <!-- SearchPanel Sidebar (optional left sidebar) -->
        <t t-if="searchPanelSections.length > 0 and state.showSearchPanel !== 'closed'">
            <div class="ls-search-panel-sidebar">
                <t t-foreach="searchPanelSections" t-as="section" t-key="section.field">
                    <div class="ls-sp-section">
                        <div class="ls-sp-section-header">
                            <span t-esc="section.label"/>
                        </div>
                        <!-- Category type (radio - Many2one) -->
                        <t t-if="section.select === 'one' or section.type === 'many2one'">
                            <div t-att-class="'ls-sp-item' + (!state.searchPanelValues[section.field] ? ' active' : '')"
                                 t-on-click="() => this.setSearchPanelCategory(section.field, null)">
                                <span class="ls-sp-item-label">All</span>
                                <span class="ls-sp-item-count" t-if="section._totalCount" t-esc="section._totalCount"/>
                            </div>
                            <t t-foreach="section._values || []" t-as="val" t-key="val.id">
                                <div t-att-class="'ls-sp-item' + (state.searchPanelValues[section.field] == val.id ? ' active' : '')"
                                     t-on-click="() => this.setSearchPanelCategory(section.field, val.id)">
                                    <span class="ls-sp-item-label" t-esc="val.name"/>
                                    <span class="ls-sp-item-count" t-if="val.__count !== undefined" t-esc="val.__count"/>
                                </div>
                            </t>
                        </t>
                        <!-- Filter type (checkbox - Many2many) -->
                        <t t-if="section.select === 'multi' or section.type === 'many2many' or section.type === 'selection'">
                            <t t-foreach="section._values || []" t-as="val" t-key="val.id">
                                <label class="ls-sp-filter-item">
                                    <input type="checkbox"
                                           t-att-checked="(state.searchPanelFilters[section.field] || []).includes(val.id)"
                                           t-on-change="() => this.toggleSearchPanelFilter(section.field, val.id)"/>
                                    <span t-esc="val.name"/>
                                    <span class="ls-sp-item-count" t-if="val.__count !== undefined" t-esc="val.__count"/>
                                </label>
                            </t>
                        </t>
                    </div>
                </t>
            </div>
        </t>

        <div class="ls-list-main">
        <div class="ls-list-wrapper" t-ref="listWrapper">
        <t t-if="state.loading">
            <div class="ls-loading"><div class="ls-spinner"/> Loading...</div>
        </t>
        <t t-elif="state.records.length === 0 and !state.groupBy and !state.editingNew">
            <div class="ls-empty">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg>
                <div class="ls-empty-title">No records found</div>
                <div class="ls-empty-sub">Try adjusting your search or filters</div>
            </div>
        </t>
        <t t-else="">
            <table class="ls-list-table">
                <thead>
                    <tr>
                        <th class="col-checkbox"><div class="ls-checkbox" t-att-class="{'checked': allSelected}" t-on-click="toggleSelectAll"/></th>
                        <t t-foreach="visibleColumns" t-as="col" t-key="col.name">
                            <th t-att-class="col.sortable ? 'sortable' : ''"
                                t-att-style="(state.colWidths and state.colWidths[col.name] ? 'width:' + state.colWidths[col.name] + 'px;' : (col.width ? 'width:' + col.width + ';' : '')) + 'position:relative;'"
                                t-on-click="() => col.sortable ? this.setOrder(col.name) : null">
                                <span t-esc="col.string"/>
                                <span class="sort-icon" t-if="state.orderBy.startsWith(col.name)" t-esc="state.orderBy.endsWith('asc') ? '▲' : '▼'"/>
                                <div class="ls-resize-handle" t-on-click.stop="" t-on-mousedown.stop="(ev) => this.onResizeStart(ev, col.name)"></div>
                            </th>
                        </t>
                        <th class="col-optional" t-if="optionalColumns.length > 0" style="width:40px; text-align:center; padding: 0;">
                            <div class="ls-optional-toggle" style="position:relative; width: 100%; height: 100%; display: flex; justify-content: center; align-items: center;">
                                <button style="background:none; border:none; cursor:pointer; color:inherit; display:flex; align-items:center; justify-content:center; padding: 4px;" t-on-click.stop="toggleOptionalMenu" title="Optional Columns">
                                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                        <path d="M12 3v18M3 12h18"/>
                                    </svg>
                                </button>
                                <div class="ls-optional-dropdown" t-if="state.showOptionalMenu" style="right: 0; left: auto; top: 100%; text-align: left; font-weight: normal; color: var(--ls-text);">
                                    <div class="ls-optional-title">Optional Columns</div>
                                    <t t-foreach="optionalColumns" t-as="oc" t-key="oc.name">
                                        <label class="ls-optional-item">
                                            <input type="checkbox" t-att-checked="isColumnVisible(oc.name)"
                                                   t-on-change="() => this.toggleColumn(oc.name)"/>
                                            <span t-esc="oc.string"/>
                                        </label>
                                    </t>
                                </div>
                            </div>
                        </th>
                    </tr>
                </thead>
                <tbody>
                    <!-- Multi-edit row (shown at top when multi-editing) -->
                    <t t-if="state.editingId === '__multi__'">
                        <tr class="ls-inline-edit-row ls-multi-edit-row">
                            <td><div class="ls-checkbox checked"/></td>
                            <t t-foreach="visibleColumns" t-as="col" t-key="'multi_' + col.name">
                                <td t-out="renderInlineEditCell(col, state.editingValues)"/>
                            </t>
                            <td t-if="optionalColumns.length > 0"></td>
                        </tr>
                    </t>

                    <!-- Inline new row at TOP -->
                    <t t-if="state.editingNew and listEditablePosition === 'top'">
                        <tr class="ls-inline-edit-row ls-new-row">
                            <td><div class="ls-checkbox"/></td>
                            <t t-foreach="visibleColumns" t-as="col" t-key="'new_' + col.name">
                                <td t-out="renderInlineEditCell(col, state.editingNewValues)"/>
                            </t>
                            <td t-if="optionalColumns.length > 0"></td>
                        </tr>
                    </t>

                    <!-- Multi-level Group-by nested tree mode -->
                    <t t-if="state.groupBy and state.groupNodes.length > 0">
                        <t t-foreach="flatGroupNodes" t-as="node" t-key="node.key">
                            <!-- Group header row -->
                            <tr t-att-class="'ls-group-header ls-group-depth-' + node.depth"
                                t-on-click="() => this.toggleGroup(node.key)">
                                <td/>
                                <td t-att-colspan="visibleColumns.length + (optionalColumns.length > 0 ? 1 : 0)">
                                    <div class="ls-group-header-content" t-att-style="'padding-left:' + (node.depth * 20) + 'px'">
                                        <span t-att-class="'ls-group-toggle' + (node.expanded ? '' : ' collapsed')">
                                            <svg viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.17l3.71-3.94a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z"/></svg>
                                        </span>
                                        <span class="ls-group-name" t-esc="node.group.name"/>
                                        <span class="ls-group-badge" t-esc="node.group.__count"/>
                                        <!-- Aggregation measures -->
                                        <t t-if="node.group.__aggregates and Object.keys(node.group.__aggregates).length > 0">
                                            <span class="ls-group-aggregates">
                                                <t t-foreach="Object.entries(node.group.__aggregates)" t-as="agg" t-key="agg[0]">
                                                    <span class="ls-group-agg-item">
                                                        <span class="ls-group-agg-label" t-esc="getAggregateLabel(agg[0]) + ': '"/>
                                                        <span class="ls-group-agg-value" t-esc="formatGroupAggregate(agg[0], agg[1])"/>
                                                    </span>
                                                </t>
                                            </span>
                                        </t>
                                    </div>
                                </td>
                            </tr>
                            <!-- Leaf records (only when deepest level expanded) -->
                            <t t-if="node.expanded and isLeafGroup(node.key)">
                                <t t-foreach="getGroupRecords(node.key)" t-as="rec" t-key="rec.id">
                                    <tr t-att-class="getRowClasses(rec)"
                                        t-on-click="() => this.onRowClick(rec)" style="cursor:pointer;">
                                        <td>
                                            <div class="ls-group-record-indent" t-att-style="'padding-left:' + ((node.depth + 1) * 20) + 'px'">
                                                <div t-att-class="'ls-checkbox' + (isSelected(rec.id) ? ' checked' : '')" t-on-click.stop="() => this.toggleSelect(rec.id)"/>
                                            </div>
                                        </td>
                                        <t t-foreach="visibleColumns" t-as="col" t-key="col.name + '_' + rec.id">
                                            <td t-out="renderCellContent(rec, col)"/>
                                        </t>
                                        <td t-if="optionalColumns.length > 0"></td>
                                    </tr>
                                </t>
                            </t>
                        </t>
                    </t>

                    <!-- Normal (non-grouped) mode -->
                    <t t-else="">
                        <t t-foreach="state.records" t-as="rec" t-key="rec.id">
                            <tr t-att-class="getRowClasses(rec)"
                                t-on-click="() => this.onRowClick(rec)" style="cursor:pointer;"
                                t-on-dblclick="() => this.onRowDblClick(rec)">
                                <td><div t-att-class="'ls-checkbox' + (isSelected(rec.id) ? ' checked' : '')" t-on-click.stop="() => this.toggleSelect(rec.id)"/></td>
                                <t t-foreach="visibleColumns" t-as="col" t-key="col.name + '_' + rec.id">
                                    <t t-if="state.editingId === rec.id">
                                        <td t-out="renderInlineEditCell(col, state.editingValues, rec.id)"/>
                                    </t>
                                    <t t-else="">
                                        <td t-out="renderCellContent(rec, col)"/>
                                    </t>
                                </t>
                                <td t-if="optionalColumns.length > 0"></td>
                            </tr>
                        </t>
                    </t>

                    <!-- Inline new row at BOTTOM -->
                    <t t-if="state.editingNew and listEditablePosition === 'bottom'">
                        <tr class="ls-inline-edit-row ls-new-row">
                            <td><div class="ls-checkbox"/></td>
                            <t t-foreach="visibleColumns" t-as="col" t-key="'new_' + col.name">
                                <td t-out="renderInlineEditCell(col, state.editingNewValues)"/>
                            </t>
                            <td t-if="optionalColumns.length > 0"></td>
                        </tr>
                    </t>
                </tbody>
            </table>
        </t>
    </div>

    <!-- Footer with aggregation -->
    <div class="ls-footer">
        <span t-esc="state.totalCount + ' record(s)'"/>
        <div class="ls-footer-agg" t-if="Object.keys(state.aggregates).length > 0">
            <t t-foreach="aggregateColumns" t-as="ac" t-key="ac.name">
                <div class="ls-footer-agg-item">
                    <span class="ls-footer-agg-label" t-esc="ac.aggregation_label + ':'"/>
                    <span class="ls-footer-agg-value" t-esc="formatAggregate(ac)"/>
                </div>
            </t>
        </div>
    </div>
    </div><!-- /ls-list-main (right panel) -->
    </div><!-- /ls-list-content-area -->

    <!-- Inline edit save bar -->
    <t t-if="state.editingNew or state.editingId">
        <div class="ls-inline-edit-bar">
            <span t-if="state.editingNew">Adding new record...</span>
            <span t-elif="state.editingId">Editing record...</span>
            <button class="ls-btn ls-btn-primary ls-btn-sm" t-on-click="saveInlineEdit">Save</button>
            <button class="ls-btn ls-btn-sm" t-on-click="cancelInlineEdit">Discard</button>
        </div>
    </t>

    <!-- Selection bar with header actions -->
    <t t-if="state.selectedIds.length > 0 and !state.editingNew and !state.editingId">
        <div class="ls-selection-bar">
            <span t-esc="state.selectedIds.length + ' selected'"/>
            <t t-foreach="headerButtons" t-as="hb" t-key="'sel_' + hb.name">
                <button class="ls-btn" t-on-click="() => this.onHeaderButton(hb)">
                    <t t-if="hb.icon" t-out="window.lucideIcon ? window.lucideIcon(hb.icon, 14) : ''"/>
                    <span t-esc="hb.string"/>
                </button>
            </t>
            <button class="ls-btn" t-on-click="deleteSelected">Delete</button>
            <button class="ls-btn" t-on-click="clearSelection">Deselect</button>
        </div>
    </t>
</div>
`;
})();


/* --- [FILE: js/core/owl-root-tpl.js] --- */
// WebClient Root Template — Odoo-style menu system + View Switcher
(function () {
    const { xml } = owl;

    // ── AppSwitcher (Home screen with app grid & search) ───
    window.TEMPLATES.AppSwitcher = xml`
<div class="ls-app-switcher">
    <!-- Sleek Odoo Enterprise Search Bar -->
    <div class="ls-app-search-wrap">
        <div class="ls-app-search-box">
            <span class="ls-app-search-icon">
                <t t-out="window.lucideIcon('search', 18)"/>
            </span>
            <input type="text"
                   class="ls-app-search-input"
                   placeholder="Search applications and menus... (Press / to focus)"
                   t-model="state.searchQuery"
                   t-ref="searchInput"
                   autocomplete="off"
                   spellcheck="false"/>
            <t t-if="state.searchQuery">
                <button type="button" class="ls-app-search-clear" t-on-click="clearSearch" title="Clear">
                    <t t-out="window.lucideIcon('x', 14)"/>
                </button>
            </t>
            <t t-else="">
                <span class="ls-app-search-kbd">/</span>
            </t>
        </div>
    </div>

    <!-- App Grid -->
    <div class="ls-app-grid" t-if="filteredApps.length > 0">
        <t t-foreach="filteredApps" t-as="app" t-key="app.id">
            <t t-set="vis" t-value="this.getAppVisuals(app)"/>
            <div class="ls-app-card"
                 t-on-click="() => this.onAppClick(app)"
                 t-att-style="'--app-glow:' + vis.glow + '; animation-delay:' + (app_index * 40) + 'ms;'">
                <div class="ls-app-card-icon" t-att-style="'background:' + vis.gradient + '; box-shadow: 0 10px 25px -4px ' + vis.glow + ', inset 0 1px 1px rgba(255,255,255,0.4);'">
                    <span class="ls-app-icon-shine"></span>
                    <t t-out="window.lucideIcon(vis.icon || app.web_icon || 'box', 36)"/>
                </div>
                <div class="ls-app-card-name" t-esc="app.name"/>
            </div>
        </t>
    </div>

    <!-- Deep Menu Search Results (if searching) -->
    <t t-if="state.searchQuery and matchingMenuItems.length > 0">
        <div class="ls-app-menu-results">
            <div class="ls-app-menu-results-header">Menu Items</div>
            <div class="ls-app-menu-results-list">
                <t t-foreach="matchingMenuItems" t-as="item" t-key="item.id">
                    <div class="ls-app-menu-result-item" t-on-click="() => this.onMenuItemClick(item)">
                        <div class="ls-app-menu-result-icon">
                            <t t-out="window.lucideIcon(item.icon || 'chevron-right', 16)"/>
                        </div>
                        <div class="ls-app-menu-result-info">
                            <span class="ls-app-menu-result-title" t-esc="item.name"/>
                            <span class="ls-app-menu-result-path" t-esc="item.fullPath"/>
                        </div>
                        <span class="ls-app-menu-result-arrow">→</span>
                    </div>
                </t>
            </div>
        </div>
    </t>

    <!-- Empty search message -->
    <t t-if="state.searchQuery and filteredApps.length === 0 and matchingMenuItems.length === 0">
        <div class="ls-app-empty-state">
            <div class="ls-app-empty-icon">🔍</div>
            <div class="ls-app-empty-title">No applications or menus found</div>
            <div class="ls-app-empty-sub">Try searching with a different keyword</div>
        </div>
    </t>
</div>
`;

    // ── NavBar (Top navigation) ──────────────────────────
    window.TEMPLATES.NavBar = xml`
<nav t-att-class="'ls-navbar' + (props.isHome ? ' ls-navbar-home' : '')">
    <button class="ls-hamburger" t-on-click="() => window.AdvSoftLayout.toggleMobileMenu()">
        <t t-out="window.lucideIcon('menu', 20)"/>
    </button>
    
    <!-- 9-Dots Waffle Icon (Odoo Enterprise signature app switcher) -->
    <button class="ls-waffle-btn" t-on-click="props.onHome" title="Applications (Home)">
        <svg width="18" height="18" viewBox="0 0 18 18" fill="currentColor">
            <rect x="1" y="1" width="4" height="4" rx="1"/>
            <rect x="7" y="1" width="4" height="4" rx="1"/>
            <rect x="13" y="1" width="4" height="4" rx="1"/>
            <rect x="1" y="7" width="4" height="4" rx="1"/>
            <rect x="7" y="7" width="4" height="4" rx="1"/>
            <rect x="13" y="7" width="4" height="4" rx="1"/>
            <rect x="1" y="13" width="4" height="4" rx="1"/>
            <rect x="7" y="13" width="4" height="4" rx="1"/>
            <rect x="13" y="13" width="4" height="4" rx="1"/>
        </svg>
    </button>

    <div class="ls-navbar-brand" t-on-click="props.onHome" style="cursor:pointer;" title="Applications (Home)">
        <span class="ls-brand-logo">
            <t t-out="window.lucideIcon('box', 20)"/>
        </span>
        <span class="ls-brand-name">AdvSoft</span>
    </div>

    <!-- App Switcher Top Links -->
    <div class="ls-navbar-menu" t-if="!props.isHome">
        <t t-foreach="props.apps" t-as="app" t-key="app.id">
            <a href="#" t-att-class="'ls-nav-app' + (props.activeAppId === app.id ? ' active' : '')"
               t-on-click.prevent="() => this.onAppClick(app)"
               t-esc="app.name"/>
        </t>
    </div>

    <div class="ls-navbar-right">
        <button class="ls-theme-toggle" t-on-click="toggleTheme" title="Toggle Light/Dark Theme">
            <t t-out="window.lucideIcon(effectiveTheme === 'dark' ? 'sun' : 'moon', 16)"/>
        </button>
        <button class="ls-theme-toggle" t-on-click="toggleSettings" title="Settings &amp; Preferences">
            <t t-out="window.lucideIcon('settings', 16)"/>
        </button>
        <t t-set="u" t-value="window.AdvSoftUser || {}"/>
        <div class="ls-user-chip" t-if="u.uid" title="User Profile">
            <a href="#" class="ls-user-chip-btn" t-on-click.prevent="() => this.onProfileClick()" title="My Profile">
                <div class="ls-avatar">
                    <t t-esc="(u.name || u.login || '?').charAt(0).toUpperCase()"/>
                </div>
                <div class="ls-user-chip-info">
                    <span class="ls-user-chip-name" t-esc="u.name || u.login"/>
                    <span class="ls-user-chip-company" t-esc="u.company || 'My Company'"/>
                </div>
            </a>
            <a href="/logout" class="ls-user-chip-logout" title="Logout">
                <t t-out="window.lucideIcon('log-out', 13)"/>
            </a>
        </div>
    </div>
</nav>
`;

    // ── SubMenu (Level 2-3 menu items) ───────────────────
    window.TEMPLATES.SubMenu = xml`
<div class="ls-submenu-bar" t-if="props.items and props.items.length">
    <t t-foreach="props.items" t-as="item" t-key="item.id">
        <div t-att-class="'ls-submenu-item' + (props.activeMenuId === item.id ? ' active' : '') + (state.openDropdown === item.id ? ' open' : '')">
            <t t-if="item.children and item.children.length">
                <button type="button" class="ls-submenu-label ls-submenu-dropdown-toggle"
                        t-on-click="(ev) => this.toggleDropdown(item.id, ev)">
                    <t t-if="item.icon and window.lucideIcon">
                        <span class="ls-submenu-icon" t-out="window.lucideIcon(item.icon, 14)"/>
                    </t>
                    <span t-esc="item.name"/>
                    <span class="ls-submenu-caret">▾</span>
                </button>
                <div class="ls-submenu-dropdown" t-if="state.openDropdown === item.id">
                    <t t-foreach="item.children" t-as="child" t-key="child.id">
                        <div t-att-class="'ls-submenu-dropdown-item' + (props.activeMenuId === child.id ? ' active' : '')"
                             t-on-click="() => this.onMenuClick(child)">
                            <t t-if="child.icon and window.lucideIcon">
                                <span class="ls-submenu-dropdown-icon" t-out="window.lucideIcon(child.icon, 14)"/>
                            </t>
                            <span t-esc="child.name"/>
                        </div>
                    </t>
                </div>
            </t>
            <t t-else="">
                <button type="button" class="ls-submenu-label"
                        t-on-click="() => this.onMenuClick(item)">
                    <t t-if="item.icon and window.lucideIcon">
                        <span class="ls-submenu-icon" t-out="window.lucideIcon(item.icon, 14)"/>
                    </t>
                    <span t-esc="item.name"/>
                </button>
            </t>
        </div>
    </t>
</div>
`;

    // ── Breadcrumb ───────────────────────────────────────
    window.TEMPLATES.Breadcrumb = xml`
<div class="ls-breadcrumb" t-if="props.items and props.items.length">
    <t t-foreach="props.items" t-as="bc" t-key="bc.id">
        <t t-if="!bc_last">
            <span class="ls-breadcrumb-item ls-breadcrumb-link" t-on-click="() => this.onBcClick(bc)" t-esc="bc.name"/>
            <span class="ls-breadcrumb-sep">/</span>
        </t>
        <t t-else="">
            <span class="ls-breadcrumb-item" t-esc="bc.name"/>
        </t>
    </t>
</div>
`;

    // ── WebClient (Root) ─────────────────────────────────
    window.TEMPLATES.Root = xml`
<div class="ls-webclient">
    <t t-if="!state.clientError">
        <NavBar apps="state.apps" activeAppId="state.activeAppId"
                onAppClick.bind="onAppClick" onHome.bind="goHome"
                onOpenProfile.bind="openProfile"
                isHome="state.currentView === 'home'"/>

    <t t-if="state.currentView === 'home'">
        <AppSwitcher apps="state.apps" onAppClick.bind="onAppClick" onMenuClick.bind="onMenuClick"/>
    </t>

    <t t-if="state.currentView !== 'home'">
        <SubMenu items="currentSubMenus" activeMenuId="state.activeMenuId"
                 onMenuClick.bind="onMenuClick"/>
    </t>

    <t t-if="state.currentView === 'action'">
        <div class="ls-action-manager">
            <t t-if="state.actionView === 'list'">
                <ListView
                    t-key="state.currentModel + '_' + (state.currentAction ? state.currentAction.id : '')"
                    onOpenRecord.bind="openRecord"
                    model="state.currentModel"
                    stages="state.stages"
                    projects="state.projects"
                    tags="state.tags"
                    searchViewDef="state.searchViewDef"
                    listViewDef="state.listViewDef"
                    actionTitle="state.actionTitle"
                    actionDomain="state.actionDomain"
                    actionContext="state.actionContext"
                    viewModes="availableViewModes"
                    activeViewType="state.actionView"
                    onSwitchView.bind="switchView"/>
            </t>
            <t t-if="state.actionView === 'form'">
                <FormView
                    t-key="state.currentModel + '_' + state.formRecordId"
                    recordId="state.formRecordId"
                    recordIndex="state.formIndex"
                    totalRecords="state.formTotal"
                    model="state.currentModel"
                    stages="state.stages"
                    projects="state.projects"
                    tags="state.tags"
                    formViewDef="state.formViewDef"
                    actionTitle="state.actionTitle"
                    actionContext="state.actionContext"
                    onBack.bind="backToList"
                    onNavigate.bind="navigateRecord"
                    onSaved.bind="recordSaved"/>
            </t>
            <t t-if="state.actionView === 'kanban'">
                <KanbanView
                    t-key="'kanban_' + state.currentModel + '_' + (state.currentAction ? state.currentAction.id : '')"
                    model="state.currentModel"
                    kanbanViewDef="state.kanbanViewDef"
                    actionTitle="state.actionTitle"
                    actionDomain="state.actionDomain"
                    actionContext="state.actionContext"
                    onOpenRecord.bind="openRecord"
                    viewModes="availableViewModes"
                    activeViewType="state.actionView"
                    onSwitchView.bind="switchView"/>
            </t>
            <t t-if="state.actionView === 'calendar'">
                <CalendarView
                    t-key="'cal_' + state.currentModel + '_' + (state.currentAction ? state.currentAction.id : '')"
                    model="state.currentModel"
                    calendarViewDef="state.calendarViewDef"
                    actionTitle="state.actionTitle"
                    actionDomain="state.actionDomain"
                    actionContext="state.actionContext"
                    onOpenRecord.bind="openRecord"
                    viewModes="availableViewModes"
                    activeViewType="state.actionView"
                    onSwitchView.bind="switchView"/>
            </t>
            <t t-if="state.actionView === 'graph'">
                <GraphView
                    t-key="'graph_' + state.currentModel + '_' + (state.currentAction ? state.currentAction.id : '')"
                    model="state.currentModel"
                    graphViewDef="state.graphViewDef"
                    actionTitle="state.actionTitle"
                    actionDomain="state.actionDomain"
                    actionContext="state.actionContext"
                    viewModes="availableViewModes"
                    activeViewType="state.actionView"
                    onSwitchView.bind="switchView"/>
            </t>
            <t t-if="state.actionView === 'pivot'">
                <PivotView
                    t-key="'pivot_' + state.currentModel + '_' + (state.currentAction ? state.currentAction.id : '')"
                    model="state.currentModel"
                    pivotViewDef="state.pivotViewDef"
                    actionTitle="state.actionTitle"
                    actionDomain="state.actionDomain"
                    actionContext="state.actionContext"
                    viewModes="availableViewModes"
                    activeViewType="state.actionView"
                    onSwitchView.bind="switchView"/>
            </t>
            <t t-if="state.actionView === 'spreadsheet'">
                <SpreadsheetView
                    t-key="'spreadsheet_' + state.currentModel + '_' + (state.currentAction ? state.currentAction.id : '')"
                    model="state.currentModel"
                    spreadsheetViewDef="state.spreadsheetViewDef"
                    actionTitle="state.actionTitle"
                    actionDomain="state.actionDomain"
                    actionContext="state.actionContext"
                    viewModes="availableViewModes"
                    activeViewType="state.actionView"
                    onSwitchView.bind="switchView"/>
            </t>
        </div>
    </t>

    <!-- Dynamic Custom SPA Pages -->
    <t t-if="isCustomView">
        <t t-component="customComponent"/>
    </t>
    
    <!-- Mobile Overlay Menu -->
    <div t-att-class="'ls-mobile-menu-overlay' + (state.layout.mobileMenuOpen ? ' open' : '')" t-on-click="() => window.AdvSoftLayout.closeMobileMenu()">
        <div class="ls-mobile-menu-panel" t-on-click.stop="() => {}">
            <div class="ls-mobile-menu-header">
                <h3>Menu</h3>
                <button class="ls-mobile-menu-close" t-on-click="() => window.AdvSoftLayout.closeMobileMenu()">
                    <t t-out="window.lucideIcon('x', 18)"/>
                </button>
            </div>
            <div class="ls-mobile-menu-apps">
                <t t-foreach="state.apps" t-as="app" t-key="app.id">
                    <div t-att-class="'ls-mobile-menu-app' + (state.activeAppId === app.id ? ' active' : '')"
                         t-on-click="() => { this.onAppClick(app); window.AdvSoftLayout.closeMobileMenu(); }">
                        <div class="ls-mobile-menu-app-icon" t-att-style="'background:' + (app.web_icon_color || '#7C3AED')">
                            <t t-out="window.lucideIcon(app.web_icon || app.icon || 'box', 18)"/>
                        </div>
                        <t t-esc="app.name"/>
                    </div>
                </t>
            </div>
        </div>
    </div>

    <!-- Settings Panel -->
    <div t-att-class="'ls-settings-panel' + (state.layout.settingsOpen ? ' open' : '')">
        <div class="ls-settings-header">
            <h3>Settings</h3>
            <button class="ls-mobile-menu-close" t-on-click="() => this.closeSettings()">
                <t t-out="window.lucideIcon('x', 16)"/>
            </button>
        </div>

        <div class="ls-settings-section">
            <div class="ls-settings-section-title">Theme</div>
            <div class="ls-theme-cards">
                <div t-att-class="'ls-theme-card' + (state.layout.theme === 'light' ? ' active' : '')" t-on-click="() => this.setTheme('light')">
                    <div class="ls-theme-card-preview light"></div>
                    Light
                </div>
                <div t-att-class="'ls-theme-card' + (state.layout.theme === 'dark' ? ' active' : '')" t-on-click="() => this.setTheme('dark')">
                    <div class="ls-theme-card-preview dark"></div>
                    Dark
                </div>
                <div t-att-class="'ls-theme-card' + (state.layout.theme === 'auto' ? ' active' : '')" t-on-click="() => this.setTheme('auto')">
                    <div class="ls-theme-card-preview auto"></div>
                    Auto
                </div>
            </div>
        </div>

        <div class="ls-settings-section">
            <div class="ls-settings-section-title">Brand Color</div>
            <div class="ls-brand-colors">
                <t t-foreach="state.layout.brandColors" t-as="bc" t-key="bc.id">
                    <div t-att-class="'ls-brand-swatch' + (state.layout.brandColor === bc.id ? ' active' : '')"
                         t-att-style="'background:' + bc.color" t-att-title="bc.label"
                         t-on-click="() => window.AdvSoftLayout.setBrandColor(bc.id)"></div>
                </t>
            </div>
        </div>

        <div class="ls-settings-section">
            <div class="ls-settings-section-title">Density</div>
            <div class="ls-density-options">
                <div t-att-class="'ls-density-btn' + (state.layout.density === 'compact' ? ' active' : '')" t-on-click="() => window.AdvSoftLayout.setDensity('compact')">Compact</div>
                <div t-att-class="'ls-density-btn' + (state.layout.density === 'default' ? ' active' : '')" t-on-click="() => window.AdvSoftLayout.setDensity('default')">Default</div>
                <div t-att-class="'ls-density-btn' + (state.layout.density === 'comfortable' ? ' active' : '')" t-on-click="() => window.AdvSoftLayout.setDensity('comfortable')">Comfort</div>
            </div>
        </div>

        <div class="ls-settings-section">
            <div class="ls-settings-section-title">Device</div>
            <div style="font-size:12px; color:var(--ls-text-secondary); display:flex; gap:6px; align-items:center;">
                <t t-out="window.lucideIcon(state.layout.isMobile ? 'smartphone' : (state.layout.isTablet ? 'tablet' : 'monitor'), 16)"/>
                <t t-esc="state.layout.device"/>
                <span style="opacity:0.5;">(<t t-esc="window.innerWidth"/>px)</span>
            </div>
        </div>
    </div>

    </t>

    <!-- Global Error Dialog -->
    <t t-if="state.clientError">
        <div class="ls-modal-backdrop" style="display:flex; justify-content:center; align-items:center; position:fixed; top:0; left:0; width:100vw; height:100vh; background:rgba(0,0,0,0.5); z-index:9999;">
            <div class="ls-modal-dialog" style="background:var(--ls-bg); border-radius:8px; box-shadow:0 20px 25px -5px rgba(0,0,0,0.1); max-width: 600px; width: 100%; animation: slideDown 0.2s ease-out; display:flex; flex-direction:column; overflow:hidden;">
                <div class="ls-modal-header" style="background: #fee2e2; color: #991b1b; border-bottom: 1px solid #f87171; padding: 16px; display:flex; justify-content:space-between; align-items:center;">
                    <h3 style="display:flex; align-items:center; gap:8px; margin:0; font-size:1.125rem;">
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>
                        <t t-if="state.clientError.serverError">Server Error</t>
                        <t t-else="">AdvSoft Client Error</t>
                    </h3>
                    <button class="ls-modal-close" t-on-click="clearError" style="color: #991b1b; background:none; border:none; font-size:1.25rem; cursor:pointer; padding:0; line-height:1;">✕</button>
                </div>
                <div class="ls-modal-body" style="padding: 16px; max-height: 70vh; overflow-y: auto;">
                    <p style="font-weight:600; margin:0 0 8px 0;">
                        <t t-if="state.clientError.serverError">The server encountered an internal error and was unable to complete your request.</t>
                        <t t-else="">An unexpected error occurred in the frontend interface.</t>
                    </p>
                    <p t-if="state.clientError.message" style="color:#b91c1c; font-family:monospace; margin:0 0 12px 0; font-size:13px; word-break:break-all;" t-esc="state.clientError.message"></p>

                    <!-- Frontend Stack Trace -->
                    <details style="background:var(--ls-bg-muted); border-radius:6px; border:1px solid var(--ls-border); padding:12px;" t-if="!state.clientError.serverError and (state.clientError.stack || state.clientError.cause)">
                        <summary style="font-size:12px; font-weight:600; cursor:pointer; color:var(--ls-text-secondary); user-select:none;">View Stack Trace</summary>
                        <pre style="margin:8px 0 0 0; font-size:11px; color:var(--ls-text); white-space:pre-wrap; word-break:break-all; max-height:250px; overflow-y:auto; font-family:monospace;" t-esc="state.clientError.stack + (state.clientError.cause ? '\n\nCaused by:\n' + (state.clientError.cause.stack || state.clientError.cause.message || state.clientError.cause) : '')"></pre>
                    </details>
                    
                    <!-- Backend Server Stack Trace -->
                    <details style="background:var(--ls-bg-muted); border-radius:6px; border:1px solid var(--ls-border); padding:12px;" t-if="state.clientError.serverError and state.clientError.serverError.trace">
                        <summary style="font-size:12px; font-weight:600; cursor:pointer; color:var(--ls-text-secondary); user-select:none;">View Server Traceback (<t t-esc="state.clientError.serverError.exception"/>)</summary>
                        <div style="margin-top:12px; font-family:monospace; font-size:11px; color:var(--ls-text); overflow-y:auto; max-height:400px; padding-right:8px;">
                            <div style="font-weight:bold; color:#b91c1c; margin-bottom:12px; padding-bottom:8px; border-bottom:1px solid var(--ls-border);">
                                <div>File: <t t-esc="state.clientError.serverError.file"/></div>
                                <div>Line: <t t-esc="state.clientError.serverError.line"/></div>
                            </div>
                            <t t-foreach="state.clientError.serverError.trace" t-as="tr" t-key="tr_index">
                                <div style="margin-bottom:8px; padding-bottom:8px; border-bottom:1px dashed rgba(150,150,150,0.2);">
                                    <div style="margin-bottom:4px;">
                                        <span style="color:#0284c7; font-weight:bold;" t-if="tr.class" t-esc="tr.class + (tr.type || '::')"></span>
                                        <span style="color:#059669; font-weight:bold;" t-esc="tr.function + '()'"></span>
                                    </div>
                                    <div style="color:#6b7280; font-size:10px; margin-left:8px;" t-if="tr.file">
                                        ↳ <t t-esc="tr.file"/>:<t t-esc="tr.line"/>
                                    </div>
                                </div>
                            </t>
                        </div>
                    </details>
                </div>
                <div class="ls-modal-footer" style="padding: 12px 16px; background:var(--ls-bg-soft); border-top:1px solid var(--ls-border); display:flex; justify-content:flex-end; gap:8px;">
                    <button class="ls-btn" t-on-click="reloadPage" style="padding:8px 16px; background:var(--ls-bg); border:1px solid var(--ls-border); border-radius:6px; cursor:pointer; font-weight:500; color:var(--ls-text);">Reload Page</button>
                    <button class="ls-btn ls-btn-primary" t-on-click="clearError" style="padding:8px 16px; background:var(--ls-primary); color:#fff; border:none; border-radius:6px; cursor:pointer; font-weight:500;">Dismiss</button>
                </div>
            </div>
        </div>
    </t>
</div>
`;
})();


/* --- [FILE: js/widgets/fields/owl-field-widgets.js] --- */
// ══════════════════════════════════════════════════════════
//  Field Widget Registry — Odoo-style configurable rendering
//  Each widget is a render function: (fieldDef, value, onChange, record) => HTML string
// ══════════════════════════════════════════════════════════
(function () {
const m = owl.markup;

const W = {};  // Widget registry

// ── Helper ───────────────────────────────────────────
function esc(v) { return v == null ? '' : String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

// Render a required indicator (red *) before/after a label
function reqMark(f) { return f.required ? '<span class="ls-req-mark" style="color:#ef4444;margin-left:2px">*</span>' : ''; }

// Render help tooltip (? icon next to label)
function helpMark(f) {
    if (!f.help) return '';
    return `<span class="ls-help-mark" title="${esc(f.help)}" style="cursor:help;color:#9ca3af;margin-left:4px;font-size:11px;">?</span>`;
}

// ════════════════════════════════════════════════════
//  CHAR WIDGETS
// ════════════════════════════════════════════════════
W.char = (f) => `<input class="ls-field-input" data-field="${f.name}" value="${esc(f._val)}" placeholder="${esc(f.placeholder||'')}" ${f.required ? 'required aria-required="true"' : ''}/>`;

W.email = (f) => f._readonly
    ? `<a href="mailto:${esc(f._val)}" class="ls-field-link">${esc(f._val)}</a>`
    : `<input class="ls-field-input" type="email" data-field="${f.name}" value="${esc(f._val)}" placeholder="e.g. user@example.com"/>`;

W.url = (f) => f._readonly
    ? `<a href="${esc(f._val)}" target="_blank" class="ls-field-link">${esc(f._val)}</a>`
    : `<input class="ls-field-input" type="url" data-field="${f.name}" value="${esc(f._val)}" placeholder="https://..."/>`;

W.phone = (f) => f._readonly
    ? `<a href="tel:${esc(f._val)}" class="ls-field-link">📞 ${esc(f._val)}</a>`
    : `<input class="ls-field-input" type="tel" data-field="${f.name}" value="${esc(f._val)}" placeholder="+62..."/>`;

W.copy_clipboard = (f) => `<div class="ls-clipboard-widget">
    <input class="ls-field-input" data-field="${f.name}" value="${esc(f._val)}" readonly/>
    <button class="ls-btn-icon ls-copy-btn" data-copy="${esc(f._val)}" title="Copy">📋</button></div>`;

W.CopyClipboardChar = W.copy_clipboard;

W.char_emojis = (f) => `<div class="ls-char-emojis-widget">
    <input class="ls-field-input" data-field="${f.name}" value="${esc(f._val)}" placeholder="${esc(f.placeholder||'')}"/>
    <button class="ls-emoji-btn" title="Emoji">😀</button></div>`;

// ════════════════════════════════════════════════════
//  TEXT / HTML WIDGETS
// ════════════════════════════════════════════════════
W.text = (f) => `<textarea class="ls-field-textarea" data-field="${f.name}" rows="4" placeholder="${esc(f.placeholder||'')}" ${f.required ? 'required aria-required="true"' : ''}>${esc(f._val)}</textarea>`;

// RTE-powered HTML widget: returns a mountable div that the form binder
// will later turn into a fully-configured AdvSoftRTE instance.
W.html = (f) => {
    // Build the config that will be passed to AdvSoftRTE
    const htmlCfg = f.html || {};
    const containerId = 'ls-rte-' + (f.name || 'field').replace(/[^a-z0-9_]/gi, '_');
    // We embed the config as a data attribute so the form binder can read it
    // after the DOM is inserted. The form binder will look for elements with
    // [data-rte] and call AdvSoftRTE.create().
    return `<div id="${containerId}" class="ls-html-widget-mount" data-field="${esc(f.name)}" data-rte="1" data-rte-model="${esc(f._model||'')}" data-rte-field="${esc(f.name)}" data-rte-config='${esc(JSON.stringify(htmlCfg))}' data-rte-value='${esc(JSON.stringify(f._val || ""))}'></div>`;
};

// ════════════════════════════════════════════════════
//  NUMERIC WIDGETS
// ════════════════════════════════════════════════════
W.integer = (f) => `<input class="ls-field-input" type="number" step="1" data-field="${f.name}" value="${f._val ?? 0}" ${f.required ? 'required aria-required="true"' : ''}/>`;

W.float = (f) => {
    const step = f.digits ? Math.pow(10, -(f.digits[1]||2)) : 0.01;
    return `<input class="ls-field-input" type="number" step="${step}" data-field="${f.name}" value="${f._val ?? 0}" ${f.required ? 'required aria-required="true"' : ''}/>`;
};

W.monetary = (f) => {
    const sym = f.currency_symbol || '$';
    const step = f.digits ? Math.pow(10, -(f.digits[1]||2)) : 0.01;
    return `<div class="ls-monetary-widget">
    <span class="ls-currency-symbol">${esc(sym)}</span>
    <input class="ls-field-input ls-monetary-input" type="number" step="${step}" data-field="${f.name}" value="${f._val ?? 0}"/>
</div>`;
};

W.percentage = (f) => `<div class="ls-percentage-widget">
    <input class="ls-field-input" type="number" step="1" min="0" max="100" style="width:80px" data-field="${f.name}" value="${f._val ?? 0}"/>
    <span class="ls-pct-sign">%</span></div>`;

W.progressbar = (f) => {
    const p = Number(f._val) || 0;
    const w = Math.min(p, 100);
    const bg = p >= 100 ? 'var(--ls-success,#10b981)' : p >= 50 ? 'var(--ls-warning,#f59e0b)' : 'var(--ls-info,#3b82f6)';
    return `<div class="ls-progressbar-widget">
        <input class="ls-field-input" type="number" step="5" min="0" max="100" style="width:70px" data-field="${f.name}" value="${p}"/>
        <span style="font-size:12px;color:#6b7280">%</span>
        <div class="ls-progress-bar" style="flex:1"><div class="ls-progress-track"><div class="ls-progress-fill" style="width:${w}%;background:${bg}"></div></div></div>
    </div>`;
};

W.float_time = (f) => {
    const v = Number(f._val) || 0;
    const h = Math.floor(v); const m = Math.round((v - h) * 60);
    return `<div class="ls-float-time-widget">
        <input class="ls-field-input" type="number" step="0.25" data-field="${f.name}" value="${v}" style="width:80px"/>
        <span class="ls-time-display">${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}</span></div>`;
};

W.handle = (f) => `<span class="ls-handle-widget" title="Drag to reorder">☰</span>
    <input type="hidden" data-field="${f.name}" value="${f._val ?? 10}"/>`;

// ════════════════════════════════════════════════════
//  BOOLEAN WIDGETS
// ════════════════════════════════════════════════════
W.boolean = (f) => `<input type="checkbox" class="ls-field-checkbox" data-field="${f.name}" ${f._val ? 'checked' : ''}/>`;

W.boolean_toggle = (f) => `<label class="ls-toggle-widget">
    <input type="checkbox" data-field="${f.name}" ${f._val ? 'checked' : ''}/>
    <span class="ls-toggle-slider"></span></label>`;

W.boolean_favorite = (f) => `<span class="ls-favorite-widget ${f._val ? 'active' : ''}" data-field="${f.name}" data-val="${f._val?1:0}">
    ${f._val ? '★' : '☆'}</span>`;

W.boolean_button = (f) => `<button class="ls-btn ls-boolean-btn ${f._val ? 'active' : ''}" data-field="${f.name}">
    ${f._val ? 'Active' : 'Inactive'}</button>`;

// ════════════════════════════════════════════════════
//  DATE / DATETIME WIDGETS
// ════════════════════════════════════════════════════
// date & datetime are OWL Components (FieldDate / FieldDatetime).
// These are fallback renderers for readonly display or when
// the OWL Component hasn't loaded yet.
W.date = (f) => `<input class="ls-field-input" type="date" data-field="${f.name}" value="${esc(f._val || '')}" ${f._readonly ? 'disabled' : ''}/>`;
W.datetime = (f) => {
    const val = f._val ? String(f._val).replace(' ', 'T') : '';
    return `<input class="ls-field-input" type="datetime-local" data-field="${f.name}" value="${esc(val)}" ${f._readonly ? 'disabled' : ''}/>`;
};

W.remaining_days = (f) => {
    const d = f._val;
    if (!d) return `<span class="ls-remaining-days ls-rd-none">No date</span>`;
    const diff = Math.ceil((new Date(d) - new Date()) / 86400000);
    const cls = diff < 0 ? 'ls-rd-overdue' : diff <= 3 ? 'ls-rd-soon' : 'ls-rd-ok';
    const label = diff < 0 ? `${Math.abs(diff)}d overdue` : diff === 0 ? 'Today' : `In ${diff}d`;
    return `<div class="ls-remaining-days-widget">
        <input class="ls-field-input" type="date" data-field="${f.name}" value="${esc(d)}" style="width:140px"/>
        <span class="ls-remaining-days ${cls}">${label}</span></div>`;
};

W.daterange = (f) => {
    const start = f._val && typeof f._val === 'object' ? f._val.start : (f._val || '');
    const end = f._val && typeof f._val === 'object' ? f._val.end : '';
    return `<div class="ls-daterange-widget">
        <input class="ls-field-input" type="date" data-field="${f.name}_start" value="${esc(start)}"/>
        <span class="ls-daterange-sep">→</span>
        <input class="ls-field-input" type="date" data-field="${f.name}_end" value="${esc(end)}"/>
    </div>`;
};

// ════════════════════════════════════════════════════
//  SELECTION WIDGETS
// ════════════════════════════════════════════════════
W.selection = (f) => {
    const sel = Array.isArray(f.selection) ? f.selection : Object.entries(f.selection || {});
    const userGroups = (window.AdvSoftUser?.groups) || [];
    let html = `<select class="ls-field-select" data-field="${f.name}" ${f.required ? 'required aria-required="true"' : ''}>`;
    if (!f.required) html += `<option value="">—</option>`;
    sel.forEach(item => {
        // Support legacy tuple and new dict format
        let v, l, groups = null;
        if (Array.isArray(item)) { v = item[0]; l = item[1]; groups = item[2] || null; }
        else { v = item.value; l = item.label; groups = item.groups || null; }
        // Filter by group: if item has groups, only show if user is in any of them
        if (groups && Array.isArray(groups) && groups.length > 0) {
            const hasGroup = groups.some(g => userGroups.includes(g));
            if (!hasGroup) return; // skip this option
        }
        html += `<option value="${esc(v)}" ${f._val==v?'selected':''}>${esc(l)}</option>`;
    });
    return html + '</select>';
};

W.radio = (f) => {
    const sel = Array.isArray(f.selection) ? f.selection : Object.entries(f.selection || {});
    const userGroups = (window.AdvSoftUser?.groups) || [];
    let html = '<div class="ls-radio-widget">';
    sel.forEach(item => {
        let v, l, groups = null;
        if (Array.isArray(item)) { v = item[0]; l = item[1]; groups = item[2] || null; }
        else { v = item.value; l = item.label; groups = item.groups || null; }
        if (groups && Array.isArray(groups) && groups.length > 0) {
            const hasGroup = groups.some(g => userGroups.includes(g));
            if (!hasGroup) return;
        }
        html += `<label class="ls-radio-item"><input type="radio" name="field_${f.name}" data-field="${f.name}" value="${esc(v)}" ${f._val==v?'checked':''} ${f.required ? 'required' : ''}/> <span>${esc(l)}</span></label>`;
    });
    return html + '</div>';
};

W.priority = (f) => {
    const max = (f.selection || []).length || 3;
    const val = Number(f._val) || 0;
    let html = '<div class="ls-priority-widget">';
    for (let i = 1; i <= max; i++) {
        html += `<span class="ls-priority-star ${val >= i ? 'filled' : ''}" data-field="${f.name}" data-level="${i}">★</span>`;
    }
    return html + '</div>';
};

W.badge = (f) => {
    const sel = Array.isArray(f.selection) ? f.selection : Object.entries(f.selection || {});
    const match = sel.find(s => (Array.isArray(s) ? s[0] : s.value) == f._val);
    const label = match ? (Array.isArray(match) ? match[1] : match.label) : (f._val || '');
    const colors = { draft: '#6b7280', confirmed: '#3b82f6', done: '#10b981', cancel: '#ef4444' };
    const bg = colors[f._val] || '#7c3aed';
    return `<span class="ls-badge-widget" style="background:${bg}15;color:${bg};border:1px solid ${bg}30">${esc(label)}</span>`;
};

W.statusbar = (f) => ''; // Rendered separately at form level

W.state_selection = (f) => {
    const sel = Array.isArray(f.selection) ? f.selection : Object.entries(f.selection || {});
    const match = sel.find(s => (Array.isArray(s) ? s[0] : s.value) == f._val);
    const currentLabel = match ? (Array.isArray(match) ? match[1] : match.label) : '';
    const icons = { draft: '⚪', confirmed: '🔵', done: '🟢', cancel: '🔴', available: '🟢', borrowed: '🟡' };
    return `<span class="ls-state-sel-widget">${icons[f._val] || '⚪'} ${esc(currentLabel)}</span>`;
};

W.badges = (f) => {
    const sel = Array.isArray(f.selection) ? f.selection : Object.entries(f.selection || {});
    let html = '<div class="ls-badges-widget">';
    sel.forEach(item => {
        const v = Array.isArray(item) ? item[0] : item.value;
        const l = Array.isArray(item) ? item[1] : item.label;
        html += `<span class="ls-badges-item ${f._val == v ? 'active' : ''}" data-field="${f.name}" data-value="${esc(v)}">${esc(l)}</span>`;
    });
    return html + '</div>';
};

W.percentage_pie = (f) => {
    const p = Math.min(Number(f._val) || 0, 100);
    const r = 18, cx = 22, cy = 22, c = 2 * Math.PI * r;
    const offset = c - (p / 100) * c;
    const color = p >= 100 ? '#10b981' : p >= 50 ? '#f59e0b' : '#3b82f6';
    return `<div class="ls-percentage-pie-widget">
        <svg viewBox="0 0 44 44" width="40" height="40">
            <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#e5e7eb" stroke-width="4"/>
            <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="4"
                    stroke-dasharray="${c}" stroke-dashoffset="${offset}"
                    transform="rotate(-90 ${cx} ${cy})" stroke-linecap="round"/>
            <text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="central"
                  font-size="10" font-weight="600" fill="${color}">${p}%</text>
        </svg>
    </div>`;
};

// ════════════════════════════════════════════════════
//  MANY2ONE WIDGETS — Odoo-style autocomplete
//  Full: autocomplete dropdown → quick_create → create & edit → search more
//  Options: no_create, no_quick_create, no_create_edit, no_open
// ════════════════════════════════════════════════════
// many2one: Inline autocomplete input (Odoo-style).
// The input gets bound by FormView._bindM2OAutocompletes() to an
// M2OAutocomplete instance for Search, Quick Create, Create & Edit, Search More.
W._many2one_display = (f) => {
    const val = f._val;
    const name = Array.isArray(val) ? val[1] : (val || '');
    return `<div class="ls-m2o-widget" data-field="${f.name}" data-type="many2one">${esc(name) || '<span class="ls-empty-dash">—</span>'}</div>`;
};

W.many2one = (f) => {
    const val = f._val;
    const valId = Array.isArray(val) ? val[0] : '';
    const valName = Array.isArray(val) ? val[1] : (val || '');
    const relation = f.relation || '';
    const noCreate = f.options?.no_create ? '1' : '0';
    const noQuickCreate = f.options?.no_quick_create ? '1' : '0';
    const noCreateEdit = f.options?.no_create_edit ? '1' : '0';

    if (f._readonly) {
        return `<div class="ls-reference-widget" data-field="${f.name}">
            ${valId ? `<a href="#" class="ls-m2o-external-link" data-id="${valId}" data-field="${f.name}">${esc(valName || valId)}</a>` : '<span class="ls-empty-dash">—</span>'}
        </div>`;
    }

    return `<div class="ls-reference-widget ls-m2o-widget" data-field="${f.name}"
        data-relation="${esc(relation)}"
        data-no-create="${noCreate}" data-no-quick-create="${noQuickCreate}" data-no-create-edit="${noCreateEdit}">
        <div class="ls-m2o-input-group">
            <input type="text" class="ls-field-input ls-m2o-autocomplete"
                placeholder="${esc(f.placeholder || f.string || '')}"
                data-field="${f.name}" data-relation="${esc(relation)}"
                data-cur-id="${valId || ''}" value="${esc(valName)}" autocomplete="off"/>
            <button type="button" class="ls-m2o-dropdown-trigger" data-field="${f.name}" tabindex="-1">
                <span class="ls-m2o-chevron">▼</span>
            </button>
            ${valId ? `<button type="button" class="ls-m2o-clear" data-field="${f.name}">✕</button>` : ''}
            ${valId ? `<a href="#" class="ls-m2o-external-link ls-m2o-internal-link" tabindex="-1" data-id="${valId}" data-field="${f.name}">🔗</a>` : ''}
        </div>
    </div>`;
};

W.many2one_avatar = (f) => {
    const name = Array.isArray(f._val) ? f._val[1] : '';
    const initial = (name || '?')[0].toUpperCase();
    // Generate consistent color from name
    let hash = 0;
    for (let i = 0; i < (name||'').length; i++) { hash = name.charCodeAt(i) + ((hash << 5) - hash); }
    const hue = Math.abs(hash) % 360;
    const bg = `hsl(${hue}, 55%, 50%)`;
    return `<div class="ls-m2o-avatar-widget">
        <span class="ls-m2o-avatar" style="background:${bg}">${initial}</span>
        ${W._many2one_display(f)}</div>`;
};

W.many2one_avatar_user = W.many2one_avatar;

W.many2onebutton = (f) => {
    const label = Array.isArray(f._val) ? f._val[1] : (f._val || 'Select');
    return `<button class="ls-btn ls-btn-sm ls-m2o-btn" data-field="${f.name}">${esc(label)}</button>`;
};

// many2many_tags: Native Owl Component for inline autocomplete with tag pills
const { Component, onMounted, onWillUnmount, useRef, onPatched } = window.owl;

class Many2manyTagsWidget extends Component {
    static template = window.owl.xml`
        <div class="ls-m2m-widget" t-att-data-no-create="props.noCreate ? '1' : '0'">
            <t t-foreach="props.tags" t-as="t" t-key="t.id">
                <span class="ls-m2m-tag" t-att-style="'color:' + (t.color || '#7c3aed') + ';border-color:' + (t.color || '#7c3aed') + '40;background:' + (t.color || '#7c3aed') + '15'">
                    <span t-esc="t.name || t.display_name || t.id" />
                    <button t-if="!props.readonly" type="button" class="ls-m2m-tag-remove" t-on-click.stop="() => props.onRemove(t.id)">✕</button>
                </span>
            </t>
            <input t-if="!props.readonly" type="text" t-ref="input" class="ls-m2m-autocomplete-internal"
                placeholder="Add..." autocomplete="off"
                style="border:none;background:transparent;outline:none;font-size:13px;width:100px;min-width:60px;flex:1;" />
        </div>
    `;

    setup() {
        this.inputRef = useRef('input');
        
        onMounted(() => {
            if (this.inputRef.el) {
                this.ac = new window.M2OAutocomplete({
                    input: this.inputRef.el,
                    relation: this.props.relation,
                    fieldLabel: this.props.label,
                    fieldName: this.props.name,
                    relOptions: this.props.relOptions || [],
                    options: this.props.options || {},
                    onSelect: (opt) => {
                        this.props.onAdd(opt);
                        this.inputRef.el.value = '';
                        this.inputRef.el.focus();
                    },
                    onClear: () => {}
                });
            }
        });

        onWillUnmount(() => {
            if (this.ac) this.ac.destroy();
        });
        
        onPatched(() => {
            if (this.ac) {
                this.ac.setRelOptions(this.props.relOptions || []);
                // Ensure focus remains if input was previously focused
                if (document.activeElement === this.inputRef.el) {
                    this.inputRef.el.focus();
                }
            }
        });
    }
}
window.Many2manyTagsWidget = Many2manyTagsWidget;

// Legacy fallback just in case
W.many2many_tags = (f) => '<div class="ls-m2m-widget" data-field="' + f.name + '">Many2many Tags Component</div>';

W.many2many_checkboxes = (f) => {
    const selected = (f._val || []).map(t => t.id);
    const all = f._relOptions || [];
    let html = '<div class="ls-m2m-checkboxes-widget" data-field="' + f.name + '">';
    all.forEach(o => {
        html += `<label class="ls-checkbox-item"><input type="checkbox" data-m2m-id="${o.id}" ${selected.includes(o.id)?'checked':''}/> ${esc(o.name)}</label>`;
    });
    return html + '</div>';
};

W.many2many = (f) => `<div class="ls-m2m-list-widget" data-field="${f.name}"><div class="ls-o2m-placeholder">(Many2many List)</div></div>`;
W.one2many = (f) => `<div class="ls-o2m-widget" data-field="${f.name}"><div class="ls-o2m-placeholder">(One2many List)</div></div>`;
W.one2many_list = W.one2many;
W.many2many_kanban = (f) => `<div class="ls-m2m-kanban-widget" data-field="${f.name}"><div class="ls-o2m-placeholder">(Kanban View)</div></div>`;
W.many2many_binary = (f) => `<div class="ls-m2m-binary-widget"><input type="file" multiple class="ls-field-file" data-field="${f.name}"/></div>`;

// ════════════════════════════════════════════════════
//  BINARY WIDGETS
// ════════════════════════════════════════════════════
W.binary = (f) => `<div class="ls-binary-widget"><input type="file" class="ls-field-file" data-field="${f.name}"/>
    ${f._val ? '<span class="ls-file-indicator">📎 File attached</span>' : ''}</div>`;

W.image = (f) => {
    const size = f.options?.size || [90, 90];
    const maxSize = (f.options?.max_size || 10) * 1024 * 1024;
    const allowedTypes = f.options?.allowed_types || ['image/png', 'image/jpeg', 'image/webp', 'image/gif'];
    const accept = allowedTypes.join(',');
    const src = f._val ? `data:image/png;base64,${f._val}` : '';
    
    return `<div class="ls-image-widget" data-max-size="${maxSize}" data-allowed-types="${accept}">
        <div class="ls-image-container" style="width:${size[0]}px; height:${size[1]}px;">
            ${src ? `<img src="${src}" width="${size[0]}" height="${size[1]}" class="ls-image-preview"/>` : `<div class="ls-image-placeholder" style="width:${size[0]}px; height:${size[1]}px; line-height:${size[1]}px;">📷</div>`}
            
            <div class="ls-image-actions">
                <button type="button" class="ls-image-action-btn" data-upload="${f.name}" title="Edit">✎</button>
                <button type="button" class="ls-image-action-btn ls-image-clear-btn" data-clear-image="${f.name}" title="Clear" style="display:${src ? 'flex' : 'none'}">🗑️</button>
            </div>
        </div>
        <input type="file" accept="${accept}" class="ls-field-file" data-field="${f.name}" data-validate="image" style="display:none"/>
        <div class="ls-image-error" style="display:none;color:var(--ls-widget-danger);font-size:11px;margin-top:4px;"></div>
    </div>`;
};

W.pdf_viewer = (f) => {
    return `<div class="ls-pdf-viewer" data-field="${f.name}">
        ${f._val ? `<iframe src="data:application/pdf;base64,${f._val}" width="100%" height="400px" style="border:1px solid #e5e7eb; border-radius:8px;"></iframe>` : '<div class="ls-pdf-placeholder">PDF Viewer (No file)</div>'}
        <input type="file" accept="application/pdf" class="ls-field-file" data-field="${f.name}" style="margin-top:8px;" />
    </div>`;
};

// ════════════════════════════════════════════════════
//  SPECIAL & COMPOSITE WIDGETS
// ════════════════════════════════════════════════════
W.color_picker = (f) => `<input type="color" class="ls-color-picker" data-field="${f.name}" value="${esc(f._val||'#7c3aed')}"/>`;

// Odoo integer color index (0-11 palette)
W.color = (f) => {
    const palette = ['#f06050','#f4a460','#f7cd1f','#6cc1ed','#814968','#eb7e7f','#2c8397','#475577','#d6145f','#30c381','#9365b8','#1abc9c'];
    const idx = Number(f._val) || 0;
    let html = '<div class="ls-color-index-widget" data-field="' + f.name + '">';
    palette.forEach((c, i) => {
        html += `<span class="ls-color-dot${i===idx?' active':''}" style="background:${c}" data-field="${f.name}" data-value="${i}" title="Color ${i}"></span>`;
    });
    return html + '</div>';
};

W.kanban_color_picker = W.color;

W.signature = (f) => `<div class="ls-signature-widget" data-field="${f.name}">
    ${f._val ? `<img src="data:image/png;base64,${f._val}" class="ls-signature-img"/>` : '<div class="ls-signature-pad"><canvas class="ls-sig-canvas" width="300" height="100"></canvas><span class="ls-sig-hint">Draw your signature</span></div>'}
    <div class="ls-sig-actions">
        ${!f._val ? `<button type="button" class="ls-btn ls-btn-primary ls-btn-sm ls-sig-accept">Accept</button>
                     <button type="button" class="ls-btn ls-btn-secondary ls-btn-sm ls-sig-clear-pad">Clear</button>` 
                  : `<button type="button" class="ls-btn ls-btn-secondary ls-btn-sm ls-sig-clear">Re-sign</button>`}
        <button type="button" class="ls-btn ls-btn-sm" data-upload="${f.name}">Upload</button>
        <input type="file" accept="image/*" class="ls-field-file" data-field="${f.name}" style="display:none"/>
    </div>
</div>`;

W.image_url = (f) => {
    return `<div class="ls-image-url-widget">
        ${f._val ? `<img src="${esc(f._val)}" class="ls-image-preview" style="max-height:150px;"/>` : '<div class="ls-image-placeholder">🔗 Image URL</div>'}
        <input type="url" class="ls-field-input" data-field="${f.name}" value="${esc(f._val||'')}" placeholder="https://..." style="margin-top:8px;" />
    </div>`;
};

// JSON field — structured data editor with syntax highlighting
W.json = (f) => {
    let pretty = '';
    try { pretty = typeof f._val === 'string' ? f._val : JSON.stringify(f._val, null, 2); } catch { pretty = String(f._val || '{}'); }
    return `<div class="ls-json-widget">
        <textarea class="ls-ace-widget" data-field="${f.name}" rows="6" placeholder='{"key": "value"}'>${esc(pretty)}</textarea>
    </div>`;
};

// Countdown / remaining time widget (live display)
W.countdown = (f) => {
    const d = f._val;
    if (!d) return `<span class="ls-countdown ls-rd-none">No date set</span>`;
    const now = new Date(), target = new Date(d);
    const diff = target - now;
    if (diff <= 0) return `<span class="ls-countdown ls-rd-overdue">Expired</span>`;
    const days = Math.floor(diff / 86400000), hrs = Math.floor((diff % 86400000) / 3600000), mins = Math.floor((diff % 3600000) / 60000);
    return `<div class="ls-countdown-widget">
        <input class="ls-field-input" type="datetime-local" data-field="${f.name}" value="${esc((d||'').replace(' ','T'))}" style="width:200px"/>
        <span class="ls-countdown ls-rd-ok">${days}d ${hrs}h ${mins}m</span>
    </div>`;
};

// Section & Note widget — for O2M inline separators
W.section_and_note = (f) => {
    const isSection = f._val && String(f._val).startsWith('[SECTION]');
    if (isSection) {
        return `<div class="ls-section-widget"><strong>${esc(String(f._val).replace('[SECTION]',''))}</strong></div>`;
    }
    return `<textarea class="ls-field-textarea ls-note-widget" data-field="${f.name}" rows="2" placeholder="Add a note...">${esc(f._val||'')}</textarea>`;
};

// Stat info widget (for stat buttons, read-only display)
W.stat_info = (f) => `<div class="ls-stat-info-widget">
    <span class="ls-stat-info-value">${esc(f._val ?? '0')}</span>
    <span class="ls-stat-info-label">${esc(f.string || f.name)}</span>
</div>`;

// Activity IDs widget placeholder
W.activity_ids = (f) => `<div class="ls-activity-widget" data-field="${f.name}">
    <span class="ls-activity-icon" title="Activities">📋</span>
    <span class="ls-activity-count">${Array.isArray(f._val) ? f._val.length : 0}</span>
</div>`;

// Monetary with separate currency field
W.monetary_field = (f) => {
    const sym = f.currency_symbol || f.options?.currency_field ? '' : '$';
    const step = f.digits ? Math.pow(10, -(f.digits[1]||2)) : 0.01;
    const currField = f.options?.currency_field || '';
    return `<div class="ls-monetary-widget ls-monetary-full">
        <span class="ls-currency-symbol">${esc(sym || '$')}</span>
        <input class="ls-field-input ls-monetary-input" type="number" step="${step}" data-field="${f.name}" value="${f._val ?? 0}"/>
        ${currField ? `<span class="ls-currency-field-hint" title="Currency: ${esc(currField)}">💱</span>` : ''}
    </div>`;
};

// Many2one with barcode scanner
W.many2one_barcode = (f) => {
    const opts = f._relOptions || [];
    const curId = Array.isArray(f._val) ? f._val[0] : f._val;
    let html = `<div class="ls-m2o-barcode-widget"><select class="ls-field-select" data-field="${f.name}" data-type="many2one">`;
    html += '<option value="">—</option>';
    opts.forEach(o => { html += `<option value="${o.id}" ${curId==o.id?'selected':''}>${esc(o.name)}</option>`; });
    html += '</select><button class="ls-btn-icon" title="Scan barcode">📷</button></div>';
    return html;
};

// Removed W.char_domain and W.domain (migrated to OWL Component FieldDomain)

// Selection as badge (clickable pills)
W.selection_badge = W.badges;

// Float with factor multiplier
W.float_factor = (f) => {
    const factor = f.options?.factor || 1;
    const display = (Number(f._val) || 0) * factor;
    return `<div class="ls-float-factor-widget">
        <input class="ls-field-input" type="number" step="0.01" data-field="${f.name}" value="${f._val ?? 0}" style="width:100px"/>
        <span class="ls-factor-display">= ${display.toFixed(2)} (×${factor})</span>
    </div>`;
};

// Float toggle (cycle through predefined values)
W.float_toggle = (f) => {
    const range = f.options?.range || [0, 0.5, 1];
    const val = Number(f._val) || 0;
    const idx = range.indexOf(val);
    const nextIdx = (idx + 1) % range.length;
    return `<button class="ls-btn ls-float-toggle" data-field="${f.name}" data-value="${range[nextIdx]}">${val}</button>`;
};

// Integer displayed as badge
W.integer_badge = (f) => {
    const v = Number(f._val) || 0;
    const bg = v > 0 ? '#3b82f6' : '#6b7280';
    return `<span class="ls-badge-widget" style="background:${bg}15;color:${bg};border:1px solid ${bg}30">${v}</span>`;
};

// Label selection (readonly display of selection value)
W.label_selection = (f) => {
    const sel = f.selection || [];
    const label = (sel.find(s => s[0] == f._val) || ['', f._val || ''])[1];
    return `<span class="ls-label-selection">${esc(label)}</span>`;
};

W.ace = (f) => `<textarea class="ls-ace-widget" style="font-family:monospace; background:#1e1e1e; color:#d4d4d4; width:100%; border-radius:6px; padding:10px; border:none; outline:none;" data-field="${f.name}" rows="6" placeholder="# Write code here...">${esc(f._val||'')}</textarea>`;

// ════════════════════════════════════════════════════
//  MISSING WIDGETS — percentage_pie, char_badge, char_image
// ════════════════════════════════════════════════════

// Percentage Pie — SVG circular progress indicator (Odoo style)
W.percentage_pie = (f) => {
    const pct = Math.min(100, Math.max(0, Number(f._val) || 0));
    const r = 18, circ = 2 * Math.PI * r, offset = circ * (1 - pct / 100);
    const color = pct >= 100 ? 'var(--ls-widget-success,#10b981)' : pct >= 50 ? 'var(--ls-widget-warning,#f59e0b)' : 'var(--ls-widget-info,#3b82f6)';
    return `<div class="ls-pct-pie-widget" title="${pct}%">
        <svg width="44" height="44" viewBox="0 0 44 44">
            <circle cx="22" cy="22" r="${r}" fill="none" stroke="var(--ls-border-light,#e5e7eb)" stroke-width="4"/>
            <circle cx="22" cy="22" r="${r}" fill="none" stroke="${color}" stroke-width="4"
                    stroke-dasharray="${circ}" stroke-dashoffset="${offset}"
                    stroke-linecap="round" transform="rotate(-90 22 22)"
                    style="transition: stroke-dashoffset 0.5s ease"/>
            <text x="22" y="24" text-anchor="middle" font-size="10" font-weight="700" fill="var(--ls-text,#374151)">${pct}%</text>
        </svg>
    </div>`;
};

// Char Badge — rounded tag display for char field (Odoo badge widget)
W.char_badge = (f) => {
    const color = f.options?.badge_color || 'var(--ls-primary,#714b67)';
    return `<span class="ls-char-badge" style="display:inline-block;padding:2px 10px;border-radius:12px;font-size:12px;font-weight:600;white-space:nowrap;background:${color}15;color:${color};border:1px solid ${color}30;">${esc(f._val || f.default || '')}</span>`;
};
W.badge_char = W.char_badge;

// Char Image — displays image from URL stored in char field
W.char_image = (f) => {
    const url = f._val || '';
    const size = f.options?.size || [120, 120];
    if (!url) return `<div class="ls-image-placeholder" style="width:${size[0]}px;height:${size[1]}px;border:2px dashed var(--ls-border,#d1d5db);border-radius:8px;display:flex;align-items:center;justify-content:center;color:var(--ls-text-muted,#9ca3af);font-size:11px;">No image URL</div>`;
    return `<div class="ls-char-image-widget">
        <img src="${esc(url)}" alt="Image" style="max-width:${size[0]}px;max-height:${size[1]}px;object-fit:contain;border-radius:6px;" onerror="this.style.display='none';this.nextElementSibling.style.display='flex';"/>
        <div class="ls-image-error" style="display:none;color:var(--ls-widget-danger);font-size:11px;">⚠ Invalid image URL</div>
    </div>`;
};

// ════════════════════════════════════════════════════
//  REFERENCE WIDGET — FK dinamis ke model apapun
// ════════════════════════════════════════════════════
W.reference = (f) => {
    const refSel = f.reference_selection || [];
    const val = f._val || '';
    let curModel = '', curId = '', curName = '';
    if (typeof val === 'string' && val.includes(',')) {
        [curModel, curId] = val.split(',');
    } else if (Array.isArray(val)) {
        curModel = val[0] || ''; 
        curId = val[1] || '';
        curName = val[2] || '';
    }
    let html = `<div class="ls-reference-widget" data-field="${f.name}" style="display:flex;gap:8px;align-items:center;">`;
    html += `<select class="ls-field-select ls-ref-model" style="flex:1;">`;
    html += `<option value="">— Model —</option>`;
    refSel.forEach(([m, l]) => { html += `<option value="${esc(m)}" ${curModel===m?'selected':''}>${esc(l)}</option>`; });
    html += `</select>`;
    html += `<div class="ls-ref-m2o-container" style="flex:1;">`;
    if (curModel) {
        const m2oFieldDef = {
            name: `${f.name}_ref_id`,
            relation: curModel,
            type: 'many2one',
            _val: curName ? [curId, curName] : [curId, curId ? `ID: ${curId}` : ''],
            options: f.options || {},
            _relOptions: []
        };
        html += W.many2one(m2oFieldDef);
    } else {
        html += `<input class="ls-field-input" type="text" disabled placeholder="Record ID" style="width:100%;"/>`;
    }
    html += `</div></div>`;
    return html;
};

// ════════════════════════════════════════════════════
//  RELATED FIELD — shortcut ke field lain (readonly)
// ════════════════════════════════════════════════════
W.related = (f) => {
    const relPath = f.related || f.relatedField || '';
    if (f._readonly !== false) {
        return `<div class="ls-related-widget">
            <span class="ls-related-value">${esc(f._val ?? '')}</span>
            <span class="ls-related-path" title="Related: ${esc(relPath)}">🔗</span>
        </div>`;
    }
    return W.char(f);
};

// ════════════════════════════════════════════════════
//  COMPUTED FIELD — @api.depends, store=True/False
// ════════════════════════════════════════════════════
W.computed = (f) => {
    const stored = f.store !== false;
    return `<div class="ls-computed-widget">
        <span class="ls-computed-value">${esc(f._val ?? '')}</span>
        ${!stored ? '<span class="ls-computed-badge" title="Computed on-the-fly (not stored)">⚡</span>' : ''}
    </div>`;
};

// ════════════════════════════════════════════════════
//  RESOLVE: pick the right widget for a field
//  widget="X" di view memilih widget
//  tanpa widget= maka pilih default otomatis
//
//  Resolution order:
//  1. resolveComponent(fDef) — OWL Components (many2one,
//     many2many_tags, date, datetime) take priority.
//  2. resolveWidget(fDef) — String renderers from W. registry
//     are used as fallback for readonly/list rendering, or
//     for composite widgets (many2one_avatar, reference).
// ════════════════════════════════════════════════════
function resolveWidget(fieldDef) {
    if (fieldDef.widget && W[fieldDef.widget]) return fieldDef.widget;
    // Default widget by type (Odoo auto-selection)
    const defaults = {
        char: 'char', text: 'text', html: 'html',
        integer: 'integer', float: 'float', monetary: 'monetary',
        boolean: 'boolean', date: 'date', datetime: 'datetime',
        selection: 'selection', binary: 'binary',
        many2one: 'many2one', many2many: 'many2many_tags',
        one2many: 'one2many', reference: 'reference',
        related: 'related', computed: 'computed',
    };
    return defaults[fieldDef.type] || 'char';
}

/**
 * Render a field using its widget.
 * @param {Object} fieldDef - Field definition from fields_get
 * @param {*} value - Current field value
 * @param {Object} extras - { relOptions, readonly }
 * @returns {string} HTML string (owl.markup)
 *
 * IMPORTANT: This is only called for fields that do NOT have
 * an OWL Component registered. The FormView checks
 * resolveComponent() first.
 */
function renderFieldWidget(fieldDef, value, extras = {}) {
    const f = { ...fieldDef, _val: value, _readonly: extras.readonly || fieldDef.readonly, _relOptions: extras.relOptions || [] };
    const widgetName = resolveWidget(fieldDef);
    const renderer = W[widgetName];
    if (!renderer) {
        // Graceful fallback: plain text display
        return owl.markup(`<span>${esc(value ?? '')}</span>`);
    }
    return owl.markup(renderer(f));
}

/**
 * Render a field value for list/tree view (read-only display).
 */
function renderListCell(fieldDef, value) {
    const type = fieldDef.type;
    const widget = fieldDef.widget;
    const name = fieldDef.name;

    let html = '';
    
    // Custom handling based on field name for the reference
    if (name === 'assignee' && value) {
        // Generate a consistent color based on name string
        let hash = 0;
        for (let i = 0; i < value.length; i++) { hash = value.charCodeAt(i) + ((hash << 5) - hash); }
        const h = Math.abs(hash) % 360;
        const color = `hsl(${h}, 70%, 40%)`;
        html = `<div style="display:flex;align-items:center;gap:6px;"><span style="color:${color};font-size:14px;">●</span> ${esc(value)}</div>`;
        return owl.markup(html);
    }
    
    if (name === 'planned_hours' || widget === 'float_time') {
        const v = Number(value) || 0;
        html = `<span style="color:#6b7280">${v}h</span>`;
        return owl.markup(html);
    }

    if (widget === 'progressbar' || widget === 'percentage') {
        const p = Number(value) || 0;
        const w = Math.min(p, 100);
        const bg = p >= 100 ? '#10b981' : p >= 50 ? '#f59e0b' : '#3b82f6';
        html = `<div style="display:flex;align-items:center;gap:12px;width:120px;">
            <div style="flex:1;height:6px;background:#e5e7eb;border-radius:4px;overflow:hidden;display:flex;">
                <div style="width:${w}%;background:${bg};border-radius:4px;"></div>
            </div>
            <span style="font-size:12px;color:#6b7280;width:35px;text-align:right;">${p}%</span>
        </div>`;
    }
    else if (widget === 'percentage_pie') {
        const p = Math.min(Number(value) || 0, 100);
        const r = 14, cx = 16, cy = 16, c = 2 * Math.PI * r;
        const offset = c - (p / 100) * c;
        const color = p >= 100 ? '#10b981' : p >= 50 ? '#f59e0b' : '#3b82f6';
        html = `<svg viewBox="0 0 32 32" width="28" height="28">
            <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#e5e7eb" stroke-width="3"/>
            <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="3"
                    stroke-dasharray="${c}" stroke-dashoffset="${offset}"
                    transform="rotate(-90 ${cx} ${cy})" stroke-linecap="round"/>
            <text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="central"
                  font-size="7" font-weight="600" fill="${color}">${p}</text>
        </svg>`;
    }
    else if (widget === 'priority') {
        const v = Number(value) || 0;
        html = Array.from({length: 3}, (_, i) => `<span class="ls-priority-star ${v > i ? 'filled' : ''}">★</span>`).join('');
    }
    else if (widget === 'badge' || widget === 'badges' || widget === 'state_selection' || widget === 'statusbar') {
        let label = '';
        if (type === 'many2one' && Array.isArray(value)) label = value[1];
        else if (type === 'selection') {
            const selArray = Array.isArray(fieldDef.selection) ? fieldDef.selection : Object.entries(fieldDef.selection || {});
            const match = selArray.find(s => (Array.isArray(s) ? s[0] : s) == value);
            label = match ? (Array.isArray(match) ? match[1] : match) : (value || '');
        }
        else label = value;

        if (!label) return owl.markup('');

        const colors = {
            'Done': { bg: '#dcfce7', text: '#166534' }, 'done': { bg: '#dcfce7', text: '#166534' },
            'Review': { bg: '#f3e8ff', text: '#6b21a8' }, 'review': { bg: '#f3e8ff', text: '#6b21a8' },
            'New': { bg: '#e0f2fe', text: '#075985' },
            'In Progress': { bg: '#fef3c7', text: '#92400e' },
            'Draft': { bg: '#f3f4f6', text: '#374151' }, 'draft': { bg: '#f3f4f6', text: '#374151' },
            'Published': { bg: '#dcfce7', text: '#166534' }, 'published': { bg: '#dcfce7', text: '#166534' },
            'Cancelled': { bg: '#fef2f2', text: '#991b1b' }, 'cancel': { bg: '#fef2f2', text: '#991b1b' },
            'Confirmed': { bg: '#dbeafe', text: '#1e40af' }, 'confirmed': { bg: '#dbeafe', text: '#1e40af' },
        };
        const c = colors[label] || colors[String(value).toLowerCase()] || { bg: '#f3f4f6', text: '#374151' };
        html = `<span style="display:inline-block;padding:2px 10px;border-radius:12px;font-size:12px;font-weight:500;background:${c.bg};color:${c.text};">${esc(label)}</span>`;
    }
    // Check boolean_favorite BEFORE generic boolean to avoid false-positive
    else if (widget === 'boolean_favorite') {
        html = value ? '<span style="color:#f59e0b;font-size:16px;">★</span>' : '<span style="color:#d1d5db;font-size:16px;">☆</span>';
    }
    else if (widget === 'boolean_toggle' || type === 'boolean') {
        html = value ? '<span style="color:#10b981;">✓</span>' : '<span style="color:#d1d5db;">—</span>';
    }
    else if (widget === 'many2many_tags') {
        const tagPalette = ['#7c3aed','#2563eb','#059669','#d97706','#dc2626','#ec4899','#8b5cf6','#0891b2'];
        html = `<div style="display:flex;gap:4px;flex-wrap:wrap;">` + (value || []).map((t, i) => {
            const name = t.name || '';
            const base = t.color || tagPalette[i % tagPalette.length];
            return `<span style="padding:1px 8px;border-radius:10px;font-size:11px;font-weight:500;background:${base}15;color:${base};border:1px solid ${base}30;">${esc(name)}</span>`;
        }).join('') + `</div>`;
    }
    else if (widget === 'monetary') {
        const sym = fieldDef.currency_symbol || fieldDef.currencySymbol || '';
        const d = fieldDef.digits ? fieldDef.digits[1] : 2;
        const formatted = Number(value || 0).toLocaleString('id-ID', { minimumFractionDigits: d, maximumFractionDigits: d });
        html = `<span style="font-variant-numeric:tabular-nums;">${sym ? esc(sym) + ' ' : ''}${formatted}</span>`;
    }
    else if (widget === 'many2one_avatar' || widget === 'many2one_avatar_user') {
        const n = Array.isArray(value) ? value[1] : (value || '');
        if (!n) { html = '<span style="color:#d1d5db;">—</span>'; }
        else {
            let hash = 0; for (let i = 0; i < n.length; i++) { hash = n.charCodeAt(i) + ((hash << 5) - hash); }
            const h = Math.abs(hash) % 360;
            const bg = `hsl(${h}, 60%, 50%)`;
            html = `<div style="display:flex;align-items:center;gap:6px;"><span style="width:22px;height:22px;border-radius:50%;background:${bg};color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:600;">${n[0].toUpperCase()}</span><span>${esc(n)}</span></div>`;
        }
    }
    else if (widget === 'email') html = value ? `<a href="mailto:${esc(value)}" style="color:var(--ls-primary);text-decoration:none;">${esc(value)}</a>` : '';
    else if (widget === 'url') html = value ? `<a href="${esc(value)}" target="_blank" style="color:var(--ls-primary);text-decoration:none;">${esc(value)}</a>` : '';
    else if (widget === 'phone') html = value ? `<a href="tel:${esc(value)}" style="color:var(--ls-primary);text-decoration:none;">${esc(value)}</a>` : '';
    else if (widget === 'image') html = value ? '<span>📷</span>' : '';
    else if (widget === 'color_picker') html = `<span class="ls-color-dot" style="background:${esc(value||'#ccc')};width:16px;height:16px;display:inline-block;border-radius:4px;"></span>`;
    else if (widget === 'color' || widget === 'kanban_color_picker') {
        const palette = ['#f06050','#f4a460','#f7cd1f','#6cc1ed','#814968','#eb7e7f','#2c8397','#475577','#d6145f','#30c381','#9365b8','#1abc9c'];
        const c = palette[Number(value) || 0] || '#ccc';
        html = `<span class="ls-color-dot" style="background:${c};width:18px;height:18px;display:inline-block;border-radius:50%;border:2px solid ${c}40;"></span>`;
    }
    else if (widget === 'countdown') {
        if (!value) { html = '<span class="ls-rd-none">—</span>'; }
        else {
            const diff = Math.ceil((new Date(value) - new Date()) / 86400000);
            const cls = diff < 0 ? 'ls-rd-overdue' : diff <= 3 ? 'ls-rd-soon' : 'ls-rd-ok';
            const label = diff < 0 ? `${Math.abs(diff)}d ago` : diff === 0 ? 'Today' : `In ${diff}d`;
            html = `<span class="ls-remaining-days ${cls}">${label}</span>`;
        }
    }
    else if (widget === 'json') {
        const preview = typeof value === 'object' ? JSON.stringify(value).substring(0, 40) : String(value||'').substring(0, 40);
        html = `<span class="ls-code-font" style="font-size:11px;color:#6b7280;">${esc(preview)}${(preview||'').length >= 40 ? '…' : ''}</span>`;
    }
    else if (widget === 'signature') html = value ? '<span title="Signed">✍️</span>' : '<span style="color:#d1d5db;">—</span>';
    else if (widget === 'integer_badge') {
        const v = Number(value) || 0;
        const bg = v > 0 ? '#3b82f6' : '#6b7280';
        html = `<span style="display:inline-block;padding:1px 8px;border-radius:10px;font-size:12px;background:${bg}15;color:${bg};border:1px solid ${bg}30;">${v}</span>`;
    }
    else if (widget === 'float_factor') {
        const factor = fieldDef.options?.factor || 1;
        html = `<span style="font-variant-numeric:tabular-nums;">${((Number(value)||0)*factor).toFixed(2)}</span>`;
    }
    else if (widget === 'float_toggle') html = `<span style="font-weight:600;">${Number(value)||0}</span>`;
    else if (widget === 'activity_ids') {
        const count = Array.isArray(value) ? value.length : 0;
        html = count > 0 ? `<span title="Activities">📋 ${count}</span>` : '';
    }
    else if (widget === 'remaining_days' && value) {
        const diff = Math.ceil((new Date(value) - new Date()) / 86400000);
        const cls = diff < 0 ? 'ls-rd-overdue' : diff <= 3 ? 'ls-rd-soon' : 'ls-rd-ok';
        const label = diff < 0 ? `${Math.abs(diff)}d overdue` : diff === 0 ? 'Today' : `In ${diff}d`;
        html = `<span class="ls-remaining-days ${cls}">${label}</span>`;
    }

    // Widget-specific list renderers for new widgets
    else if (widget === 'percentage_pie') {
        const pct = Math.min(100, Math.max(0, Number(value) || 0));
        const color = pct >= 100 ? 'var(--ls-widget-success,#10b981)' : pct >= 50 ? 'var(--ls-widget-warning,#f59e0b)' : 'var(--ls-widget-info,#3b82f6)';
        html = `<span style="display:inline-flex;align-items:center;gap:6px;"><span style="width:24px;height:24px;border-radius:50%;background:conic-gradient(${color} ${pct*3.6}deg, #e5e7eb 0);display:inline-block;"></span><span style="font-weight:600;font-size:12px;">${pct}%</span></span>`;
    }
    else if (widget === 'char_badge' || widget === 'badge_char') {
        const bColor = fieldDef.options?.badge_color || 'var(--ls-primary,#714b67)';
        html = `<span style="padding:1px 8px;border-radius:10px;font-size:11px;font-weight:600;background:${bColor}15;color:${bColor};border:1px solid ${bColor}30;">${esc(value || fieldDef.default || '')}</span>`;
    }
    else if (widget === 'char_image') {
        html = value ? '<span style="font-size:14px;">🖼️</span>' : '<span style="color:#d1d5db;">—</span>';
    }
    else if (widget === 'handle') html = '<span style="color:#d1d5db;cursor:grab;">⋮⋮</span>';
    else if (widget === 'pdf_viewer') html = value ? '<span title="PDF attached">📄</span>' : '<span style="color:#d1d5db;">—</span>';
    else if (widget === 'badge' || widget === 'badges') {
        const sel = fieldDef.selection || [];
        const label = (sel.find(s => s[0] == value) || ['', value || ''])[1];
        const colorMap = { draft: '#6b7280', done: '#10b981', confirmed: '#3b82f6', cancelled: '#ef4444', pending: '#f59e0b' };
        const vk = String(value || '').toLowerCase();
        const bg = colorMap[vk] || '#6b7280';
        html = `<span style="display:inline-block;padding:1px 10px;border-radius:12px;font-size:11px;font-weight:600;background:${bg}15;color:${bg};border:1px solid ${bg}30;">${esc(label)}</span>`;
    }
    else if (widget === 'daterange') {
        html = value ? `<span style="font-size:12px;">${esc(value)}</span>` : '<span style="color:#d1d5db;">—</span>';
    }
    else if (widget === 'ace') html = value ? '<span style="font-family:monospace;font-size:11px;color:#6b7280;">📝 code</span>' : '<span style="color:#d1d5db;">—</span>';
    else if (widget === 'section_and_note') {
        if (value && String(value).startsWith('[SECTION]')) {
            html = `<strong style="color:var(--ls-text);">${esc(String(value).replace('[SECTION]',''))}</strong>`;
        } else {
            html = value ? `<span style="color:var(--ls-text-muted);font-style:italic;">${esc(String(value).substring(0,60))}${String(value).length>60?'…':''}</span>` : '';
        }
    }

    // Default by type
    else if (type === 'many2one') {
        const n = Array.isArray(value) ? value[1] : (value || '');
        html = n ? esc(n) : '<span class="ls-empty-dash">—</span>';
    }
    else if (type === 'selection') {
        const sel = fieldDef.selection || [];
        html = esc((sel.find(s => s[0] == value) || ['', value || ''])[1]);
    }
    else if (type === 'boolean') {
        html = value ? '<span style="color:#10b981;">✓</span>' : '<span class="ls-empty-dash">—</span>';
    }
    else if (type === 'date') html = `<span class="ls-list-date">${esc(value || '')}</span>`;
    else if (type === 'datetime') {
        const v = value || '';
        html = v ? `<span class="ls-list-date">${esc(v.replace('T',' ').substring(0,16))}</span>` : '';
    }
    else if (type === 'float') {
        const d = fieldDef.digits ? fieldDef.digits[1] : 2;
        html = Number(value || 0).toFixed(d);
    }
    else if (type === 'integer') {
        html = `<span style="font-variant-numeric:tabular-nums;">${Number(value || 0)}</span>`;
    }
    else if (type === 'monetary') {
        const sym = fieldDef.currency_symbol || fieldDef.currencySymbol || '';
        const d = fieldDef.digits ? fieldDef.digits[1] : 2;
        const formatted = Number(value || 0).toLocaleString('id-ID', { minimumFractionDigits: d, maximumFractionDigits: d });
        html = `<span style="font-variant-numeric:tabular-nums;">${sym ? esc(sym) + ' ' : ''}${formatted}</span>`;
    }
    else if (type === 'reference') {
        if (typeof value === 'string' && value.includes(',')) {
            const [m, id] = value.split(',');
            html = `<span class="ls-ref-display">${esc(m)}:${esc(id)}</span>`;
        } else {
            html = esc(value ?? '');
        }
    }
    else if (type === 'related' || type === 'computed') {
        html = esc(value ?? '');
    }
    else if (type === 'html') html = value ? '<span class="ls-list-muted">(HTML content)</span>' : '';
    else if (type === 'binary') html = value ? '<span>📎</span>' : '<span class="ls-empty-dash">—</span>';
    else html = `<span class="ls-list-char" style="font-weight:500;">${esc(value ?? '')}</span>`;

    return owl.markup(html);
}

/**
 * Register a custom widget (extends Component pattern).
 * Usage: FieldWidgets.register('my_widget', (f) => `<div>...</div>`);
 *
 * Custom widgets can also provide a list renderer:
 * FieldWidgets.registerList('my_widget', (fieldDef, value) => owl.markup(`<span>...</span>`));
 */
function registerWidget(name, formRenderer, listRenderer) {
    W[name] = formRenderer;
    if (listRenderer) {
        registerWidget._listRenderers = registerWidget._listRenderers || {};
        registerWidget._listRenderers[name] = listRenderer;
    }
}

// Export — public API for the widget system
window.FieldWidgets = {
    registry: W,
    components: {}, // For Phase 3 OWL Components
    resolve: resolveWidget,
    resolveComponent: (fDef) => {
        // Check explicit widget first, then fall back to type
        const key = fDef.widget || fDef.type || 'char';
        // Type → component mapping for OWL Components
        const typeMap = {
            many2many: 'many2many_tags',
        };
        const lookup = typeMap[key] || key;
        return window.FieldWidgets.components[lookup] || null;
    },
    render: renderFieldWidget,
    renderList: renderListCell,
    register: registerWidget,
    // Introspection: list all available widgets
    getAvailable: () => Object.keys(W),
};
})();


/* --- [FILE: js/widgets/fields/owl-field-m2o.js] --- */
(function(){
const { Component, useState, onMounted, useRef, onPatched, onWillUnmount } = owl;

class FieldMany2one extends Component {
    static template = owl.xml`
        <div class="ls-reference-widget ls-m2o-widget" t-att-data-field="props.fieldDef.name" t-att-data-relation="props.fieldDef.relation">
            <t t-if="props.readonly">
                <a t-if="props.value and props.value[0]" href="#" class="ls-m2o-external-link" t-att-data-id="props.value[0]" t-att-data-field="props.fieldDef.name" t-esc="props.value[1] || props.value[0]" t-on-click.prevent="openRecord"/>
                <span t-else="" class="ls-empty-dash">—</span>
            </t>
            <t t-else="">
                <div class="ls-m2o-input-group">
                    <input type="text" class="ls-field-input ls-m2o-autocomplete"
                        t-ref="input"
                        data-m2o-bound="1"
                        t-att-placeholder="props.fieldDef.placeholder || ''"
                        t-att-data-field="props.fieldDef.name"
                        t-att-data-relation="props.fieldDef.relation" />
                    <button type="button" class="ls-m2o-dropdown-trigger" tabindex="-1" t-on-click.prevent="focusInput">
                        <span class="ls-m2o-chevron">▼</span>
                    </button>
                    <button type="button" class="ls-m2o-clear" t-if="props.value" t-on-click="onClear">✕</button>
                    <a t-if="props.value and props.value[0]" href="#" class="ls-m2o-external-link ls-m2o-internal-link" tabindex="-1" t-att-data-id="props.value[0]" t-att-data-field="props.fieldDef.name" t-on-click.prevent="openRecord">🔗</a>
                </div>
            </t>
        </div>
    `;

    setup() {
        this.inputRef = useRef("input");
        this.m2oInstance = null;
        
        onMounted(() => {
            this._initAutocomplete();
        });
        
        onPatched(() => {
            this._syncAutocomplete();
        });
        
        onWillUnmount(() => {
            if (this.m2oInstance) this.m2oInstance.destroy();
        });
    }

    _initAutocomplete() {
        if (!this.inputRef.el || this.props.readonly) return;
        
        const fDef = this.props.fieldDef;
        this.m2oInstance = new window.M2OAutocomplete({
            input: this.inputRef.el,
            relation: fDef.relation,
            fieldLabel: fDef.string || fDef.name,
            fieldName: fDef.name,
            relOptions: this.props.relOptions || [],
            options: fDef.options || {},
            onSelect: (item) => {
                this.props.updateField([item.id, item.name]);
            },
            onClear: () => {
                this.props.updateField(false);
            }
        });
        this._syncAutocomplete();
    }

    _syncAutocomplete() {
        if (!this.m2oInstance) return;
        if (this.props.value) {
            this.inputRef.el.value = Array.isArray(this.props.value) ? this.props.value[1] : this.props.value;
        } else {
            this.inputRef.el.value = '';
        }
    }

    onClear(ev) {
        ev.preventDefault();
        this.props.updateField(false);
        if (this.inputRef.el) {
            this.inputRef.el.value = '';
            this.inputRef.el.focus();
        }
    }
    
    focusInput() {
        if (this.inputRef.el) this.inputRef.el.focus();
    }
    
    openRecord(ev) {
        if (!this.props.value || !this.props.value[0]) return;
        const id = Array.isArray(this.props.value) ? this.props.value[0] : this.props.value;
        const relation = this.props.fieldDef.relation;
        if (relation && id && window.__doAction) {
            window.__doAction({
                type: 'ir.actions.act_window',
                res_model: relation,
                res_id: parseInt(id),
                view_mode: 'form'
            });
        }
    }
}

class FieldMany2manyTags extends Component {
    static template = owl.xml`
        <div class="ls-m2m-widget" t-att-data-field="props.fieldDef.name" t-att-data-relation="props.fieldDef.relation">
            <t t-if="props.value and props.value.length">
                <span t-foreach="props.value" t-as="tag" t-key="tag.id" t-att-class="'ls-badge ' + (tag.color ? 'ls-badge-color-' + tag.color : 'ls-badge-primary')">
                    <t t-esc="tag.name"/>
                    <button t-if="!props.readonly" type="button" class="ls-m2m-tag-remove" t-on-click.prevent="() => this.removeTag(tag.id)">✕</button>
                </span>
            </t>
            <t t-else="">
                <span t-if="props.readonly" class="ls-empty-dash">—</span>
            </t>
            
            <t t-if="!props.readonly">
                <div class="ls-m2m-input-container" style="display:inline-block; vertical-align:middle; margin-left:4px;">
                    <input type="text" class="ls-m2m-autocomplete"
                        t-ref="input"
                        data-m2o-bound="1"
                        placeholder="Add..."
                        style="border:none; outline:none; background:transparent; width:120px;"
                        t-att-data-field="props.fieldDef.name"
                        t-att-data-relation="props.fieldDef.relation" />
                </div>
            </t>
        </div>
    `;

    setup() {
        this.inputRef = useRef("input");
        this.m2oInstance = null;
        
        onMounted(() => {
            this._initAutocomplete();
        });
        
        onWillUnmount(() => {
            if (this.m2oInstance) this.m2oInstance.destroy();
        });
    }

    _initAutocomplete() {
        if (!this.inputRef.el || this.props.readonly) return;
        
        const fDef = this.props.fieldDef;
        this.m2oInstance = new window.M2OAutocomplete({
            input: this.inputRef.el,
            relation: fDef.relation,
            fieldLabel: fDef.string || fDef.name,
            fieldName: fDef.name,
            relOptions: this.props.relOptions || [],
            options: fDef.options || {},
            onSelect: (item) => {
                const current = Array.isArray(this.props.value) ? [...this.props.value] : [];
                if (!current.find(t => t.id === item.id)) {
                    current.push({ id: item.id, name: item.name });
                    this.props.updateField(current);
                }
                this.inputRef.el.value = '';
                this.inputRef.el.focus();
            }
        });
    }

    removeTag(tagId) {
        if (this.props.readonly) return;
        const current = Array.isArray(this.props.value) ? [...this.props.value] : [];
        const filtered = current.filter(t => t.id !== tagId);
        this.props.updateField(filtered);
    }
}

// Register as OWL component
if (window.FieldWidgets && window.FieldWidgets.components) {
    window.FieldWidgets.components['many2one'] = FieldMany2one;
    window.FieldWidgets.components['many2many_tags'] = FieldMany2manyTags;
} else {
    // Wait for FieldWidgets to be initialized
    window.addEventListener('load', () => {
        if (window.FieldWidgets && window.FieldWidgets.components) {
            window.FieldWidgets.components['many2one'] = FieldMany2one;
            window.FieldWidgets.components['many2many_tags'] = FieldMany2manyTags;
        }
    });
}

})();


/* --- [FILE: js/widgets/fields/owl-field-datetime.js] --- */
(function(){
const { Component, useState, useRef, onMounted, onWillUnmount } = owl;

// ═══════════════════════════════════════════════════════════════
//  SHARED CALENDAR UTILITIES
// ═══════════════════════════════════════════════════════════════
const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const MONTHS_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const DAYS_SHORT = ['Mo','Tu','We','Th','Fr','Sa','Su'];
const DAYS_MIN = ['M','T','W','T','F','S','S'];

function daysInMonth(y, m) { return new Date(y, m+1, 0).getDate(); }
function firstDayOfMonth(y, m) { const d = new Date(y, m, 1).getDay(); return d === 0 ? 6 : d-1; }
function toISODate(y, m, d) { return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`; }
function todayISO() { const t=new Date(); return toISODate(t.getFullYear(), t.getMonth(), t.getDate()); }
function parseDate(val) { if(!val) return null; const p=val.substring(0,10).split(/[-/]/); if(p.length!==3) return null; return {y:+p[0], m:+p[1]-1, d:+p[2]}; }

// ═══════════════════════════════════════════════════════════════
//  CALENDAR MONTH COMPONENT
// ═══════════════════════════════════════════════════════════════
class CalendarMonth extends Component {
    static template = owl.xml`
        <div class="ls-datepicker-popup" t-on-click.stop="() => {}">
            <div class="ls-dp-header">
                <button class="ls-dp-nav" t-on-click="prevMonth" title="Previous month">‹</button>
                <span class="ls-dp-month-year">
                    <t t-esc="monthLabel"/> <t t-esc="state.year"/>
                </span>
                <button class="ls-dp-nav" t-on-click="nextMonth" title="Next month">›</button>
            </div>
            <div class="ls-dp-weekdays">
                <t t-foreach="DAYS_MIN" t-as="d" t-key="d"><span t-esc="d"/></t>
            </div>
            <div class="ls-dp-grid">
                <t t-foreach="state.days" t-as="day" t-key="day.key">
                    <button
                        t-att-class="'ls-dp-day' + (day.isToday ? ' ls-dp-today' : '') + (day.isSelected ? ' ls-dp-selected' : '') + (day.isOtherMonth ? ' ls-dp-other' : '') + (day.isDisabled ? ' ls-dp-disabled' : '')"
                        t-att-disabled="day.isDisabled"
                        t-on-click="() => this.selectDay(day)"
                        t-esc="day.label"/>
                </t>
            </div>
            <t t-if="props.showTime">
                <div class="ls-dp-time">
                    <input type="number" class="ls-dp-time-input" t-ref="hourInput" min="0" max="23" t-att-value="state.hours" t-on-change="onTimeChange" placeholder="HH"/>
                    <span>:</span>
                    <input type="number" class="ls-dp-time-input" t-ref="minInput" min="0" max="59" t-att-step="props.timeInterval||5" t-att-value="state.minutes" t-on-change="onTimeChange" placeholder="MM"/>
                    <t t-if="props.showSeconds">
                        <span>:</span>
                        <input type="number" class="ls-dp-time-input" t-ref="secInput" min="0" max="59" t-att-value="state.seconds" t-on-change="onTimeChange" placeholder="SS"/>
                    </t>
                </div>
            </t>
            <div class="ls-dp-footer">
                <button class="ls-btn ls-btn-sm" t-on-click="clear">Clear</button>
                <button class="ls-btn ls-btn-sm" t-on-click="setToday">Today</button>
                <button class="ls-btn ls-btn-primary ls-btn-sm" t-on-click="confirm">OK</button>
            </div>
        </div>
    `;

    static props = {
        value: { type: String, optional: true },
        minDate: { type: String, optional: true },
        maxDate: { type: String, optional: true },
        showTime: { type: Boolean, optional: true },
        showSeconds: { type: Boolean, optional: true },
        timeInterval: { type: Number, optional: true },
        onSelect: { type: Function },
        onClose: { type: Function },
    };

    setup() {
        const today = new Date();
        const parsed = parseDate(this.props.value);
        const y = parsed ? parsed.y : today.getFullYear();
        const m = parsed ? parsed.m : today.getMonth();
        const d = parsed ? parsed.d : today.getDate();
        let hours = 0, mins = 0, secs = 0;
        if (this.props.value && this.props.value.length >= 16) {
            const tp = this.props.value.substring(11, 19).split(':');
            hours = +tp[0]||0; mins = +tp[1]||0; secs = +tp[2]||0;
        }

        this.state = useState({
            year: y, month: m,
            hours, minutes: mins, seconds: secs,
            selectedDate: { y, m, d },
            days: [],
        });
        this._buildDays();
    }

    get monthLabel() { return MONTHS[this.state.month]; }

    _buildDays() {
        const { year, month, selectedDate } = this.state;
        const dim = daysInMonth(year, month);
        const first = firstDayOfMonth(year, month);
        const today = todayISO();
        const minD = this.props.minDate;
        const maxD = this.props.maxDate;
        const days = [];

        // Previous month filler
        const prevDim = daysInMonth(year, month-1 < 0 ? 11 : month-1);
        for (let i = first-1; i >= 0; i--) {
            const d = prevDim - i;
            days.push({ key: 'p'+d, label: d, isOtherMonth: true, isToday: false, isSelected: false, isDisabled: true });
        }

        // Current month
        for (let d = 1; d <= dim; d++) {
            const iso = toISODate(year, month, d);
            const sel = selectedDate && selectedDate.y === year && selectedDate.m === month && selectedDate.d === d;
            let disabled = false;
            if (minD && iso < minD) disabled = true;
            if (maxD && iso > maxD) disabled = true;
            days.push({ key: 'd'+d, label: d, isOtherMonth: false, isToday: iso === today, isSelected: !!sel, isDisabled: disabled });
        }

        // Next month filler
        const remaining = 42 - days.length;
        for (let d = 1; d <= remaining; d++) {
            days.push({ key: 'n'+d, label: d, isOtherMonth: true, isToday: false, isSelected: false, isDisabled: true });
        }

        this.state.days = days;
    }

    prevMonth() { if (this.state.month===0) { this.state.month=11; this.state.year--; } else { this.state.month--; } this._buildDays(); }
    nextMonth() { if (this.state.month===11) { this.state.month=0; this.state.year++; } else { this.state.month++; } this._buildDays(); }

    selectDay(day) {
        if (day.isOtherMonth || day.isDisabled) return;
        this.state.selectedDate = { y: this.state.year, m: this.state.month, d: day.label };
        this._buildDays();
    }

    setToday() {
        const t = new Date();
        this.state.year = t.getFullYear();
        this.state.month = t.getMonth();
        this.state.selectedDate = { y: t.getFullYear(), m: t.getMonth(), d: t.getDate() };
        this._buildDays();
    }

    clear() { if (this.props.onClose) this.props.onClose(null); }

    confirm() {
        const { year, month, selectedDate, hours, minutes, seconds } = this.state;
        let val = toISODate(year, month, selectedDate.d);
        if (this.props.showTime) {
            val += ` ${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}`;
            if (this.props.showSeconds) val += `:${String(seconds).padStart(2,'0')}`;
            else val += ':00';
        }
        if (this.props.onSelect) this.props.onSelect(val);
        if (this.props.onClose) this.props.onClose(val);
    }

    onTimeChange(ev) {
        const target = ev.target;
        const name = target === this.hourInputRef?.el ? 'hours' : target === this.minInputRef?.el ? 'minutes' : 'seconds';
        let v = parseInt(target.value, 10) || 0;
        if (name === 'hours') v = Math.max(0, Math.min(23, v));
        else v = Math.max(0, Math.min(59, v));
        this.state[name] = v;
    }
}

// ═══════════════════════════════════════════════════════════════
//  DATE FIELD COMPONENT (with popup calendar)
// ═══════════════════════════════════════════════════════════════
class FieldDate extends Component {
    static template = owl.xml`
        <div class="ls-date-widget" t-att-data-field="props.fieldDef.name">
            <t t-if="props.readonly">
                <span class="ls-date-display" t-esc="formattedDisplay || '—'"/>
            </t>
            <t t-else="">
                <div class="ls-datepicker-input-group">
                    <input class="ls-field-input ls-datepicker-input" type="text"
                        t-ref="input"
                        t-att-value="formattedDisplay || ''"
                        t-att-placeholder="props.fieldDef.options?.placeholder || 'YYYY-MM-DD'"
                        t-on-focus="openPicker"
                        t-on-keydown="onKeydown"
                        readonly="true"
                        autocomplete="off"/>
                    <button class="ls-datepicker-trigger" t-on-click="openPicker" title="Open calendar" tabindex="-1">📅</button>
                </div>
                <div class="ls-datepicker-dropdown" t-if="state.open" t-ref="dropdown">
                    <CalendarMonth
                        value="props.value"
                        minDate="props.fieldDef.options?.min_date"
                        maxDate="props.fieldDef.options?.max_date"
                        showTime="false"
                        onSelect="(val) => this.onDateSelect(val)"
                        onClose="(val) => this.onDateSelect(val)"
                    />
                </div>
            </t>
        </div>
    `;
    static components = { CalendarMonth };

    setup() {
        this.state = useState({ open: false });
        this.inputRef = useRef("input");
        this.dropdownRef = useRef("dropdown");

        onMounted(() => {
            document.addEventListener('click', this._onDocClick);
        });
        onWillUnmount(() => {
            document.removeEventListener('click', this._onDocClick);
        });
    }

    _onDocClick = (ev) => {
        if (this.state.open && this.dropdownRef?.el && !this.dropdownRef.el.contains(ev.target) && ev.target !== this.inputRef?.el) {
            this.state.open = false;
        }
    };

    get formattedDisplay() {
        const v = this.props.value;
        if (!v) return '';
        const d = new Date(v);
        if (isNaN(d.getTime())) return v;
        return d.toLocaleDateString('id-ID', { year: 'numeric', month: 'short', day: 'numeric' });
    }

    openPicker() { this.state.open = !this.state.open; }

    onDateSelect(val) {
        this.state.open = false;
        if (val === null) {
            this.props.updateField(false);
        } else if (val !== undefined) {
            this.props.updateField(val);
        }
    }

    onKeydown(ev) {
        if (ev.key === 'Escape') { this.state.open = false; }
        if (ev.key === 'ArrowDown') { this.state.open = true; ev.preventDefault(); }
    }
}

// ═══════════════════════════════════════════════════════════════
//  DATETIME FIELD COMPONENT (with popup calendar + time)
// ═══════════════════════════════════════════════════════════════
class FieldDatetime extends Component {
    static template = owl.xml`
        <div class="ls-datetime-widget" t-att-data-field="props.fieldDef.name">
            <t t-if="props.readonly">
                <span class="ls-date-display" t-esc="formattedDisplay || '—'"/>
            </t>
            <t t-else="">
                <div class="ls-datepicker-input-group">
                    <input class="ls-field-input ls-datepicker-input" type="text"
                        t-ref="input"
                        t-att-value="formattedDisplay || ''"
                        t-att-placeholder="props.fieldDef.options?.placeholder || 'YYYY-MM-DD HH:MM'"
                        t-on-focus="openPicker"
                        t-on-keydown="onKeydown"
                        readonly="true"
                        autocomplete="off"/>
                    <button class="ls-datepicker-trigger" t-on-click="openPicker" title="Open calendar" tabindex="-1">📅</button>
                </div>
                <div class="ls-datepicker-dropdown" t-if="state.open" t-ref="dropdown">
                    <CalendarMonth
                        value="props.value"
                        minDate="props.fieldDef.options?.min_date"
                        maxDate="props.fieldDef.options?.max_date"
                        showTime="true"
                        showSeconds="props.fieldDef.options?.show_seconds || false"
                        timeInterval="props.fieldDef.options?.time_interval || 5"
                        onSelect="(val) => this.onDateSelect(val)"
                        onClose="(val) => this.onDateSelect(val)"
                    />
                </div>
            </t>
        </div>
    `;
    static components = { CalendarMonth };

    setup() {
        this.state = useState({ open: false });
        this.inputRef = useRef("input");
        this.dropdownRef = useRef("dropdown");

        onMounted(() => {
            document.addEventListener('click', this._onDocClick);
        });
        onWillUnmount(() => {
            document.removeEventListener('click', this._onDocClick);
        });
    }

    _onDocClick = (ev) => {
        if (this.state.open && this.dropdownRef?.el && !this.dropdownRef.el.contains(ev.target) && ev.target !== this.inputRef?.el) {
            this.state.open = false;
        }
    };

    get formattedDisplay() {
        const v = this.props.value;
        if (!v) return '';
        const d = new Date(v.replace(' ','T'));
        if (isNaN(d.getTime())) return v;
        const datePart = d.toLocaleDateString('id-ID', { year: 'numeric', month: 'short', day: 'numeric' });
        const timePart = d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
        return `${datePart} ${timePart}`;
    }

    openPicker() { this.state.open = !this.state.open; }

    onDateSelect(val) {
        this.state.open = false;
        if (val === null) {
            this.props.updateField(false);
        } else if (val !== undefined) {
            this.props.updateField(val);
        }
    }

    onKeydown(ev) {
        if (ev.key === 'Escape') { this.state.open = false; }
        if (ev.key === 'ArrowDown') { this.state.open = true; ev.preventDefault(); }
    }
}

// Register as OWL components
window.addEventListener('load', () => {
    if (window.FieldWidgets && window.FieldWidgets.components) {
        window.FieldWidgets.components['date'] = FieldDate;
        window.FieldWidgets.components['datetime'] = FieldDatetime;
    }
});

})();


/* --- [FILE: js/widgets/fields/owl-field-domain.js] --- */
(function(){
const { Component, useState, onMounted } = owl;

class FieldDomain extends Component {
    static template = owl.xml`
        <div class="ls-domain-builder-component" t-att-data-field="props.fieldDef.name" style="position: relative;">
            <t t-if="props.readonly">
                <div class="ls-field-input ls-code-font" style="background:#f8fafc; color:#64748b; padding:6px 12px; border-radius:4px;" t-esc="props.value || '[]'"/>
            </t>
            <t t-else="">
                <input type="text" class="ls-field-input ls-code-font" 
                    t-att-value="props.value || '[]'" 
                    placeholder="[('field', '=', 'value')]"
                    t-on-change="onChange"/>
                <span class="ls-domain-hint" title="Open Visual Domain Builder" 
                      style="cursor: pointer; position: absolute; right: 10px; top: 50%; transform: translateY(-50%);"
                      t-on-click="openDialog">🔧</span>
            </t>
        </div>
    `;

    setup() {
        // We use the existing DomainBuilderDialog for the UI modal, but handle state natively in OWL
    }

    onChange(ev) {
        this.props.updateField(ev.target.value);
    }

    openDialog() {
        if (!window.DomainBuilderDialog) {
            console.error("DomainBuilderDialog not found!");
            return;
        }
        
        window.DomainBuilderDialog.open({
            domain: this.props.value || '[]',
            model: this.props.fieldDef.relation || this.props.record?._model || '',
            onSave: (newDomain) => {
                this.props.updateField(newDomain);
            }
        });
    }
}

// Register as OWL component
window.addEventListener('load', () => {
    if (window.FieldWidgets && window.FieldWidgets.components) {
        window.FieldWidgets.components['domain'] = FieldDomain;
        window.FieldWidgets.components['char_domain'] = FieldDomain;
    }
});

})();


