/* --- [FILE: js/pages/accounting/owl-accounting-report.js] --- */
// ══════════════════════════════════════════════════════════════
//  AccountingReports — Owl Component
//  Financial reporting dashboard for the Accounting module.
// ══════════════════════════════════════════════════════════════
(function () {
const { Component, useState, useRef, onMounted } = owl;

class AccountingReports extends Component {
    static template = window.ACCOUNTING_REPORT_TPL;

    setup() {
        const today = new Date();
        const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);

        this.state = useState({
            activeReport: 'trial_balance',
            dateFrom: firstDay.toISOString().slice(0, 10),
            dateTo: today.toISOString().slice(0, 10),
            targetMove: 'posted',
            loading: false,
            data: null,
            glCollapsed: {},
        });

        this.reportRef = useRef('reportContent');

        onMounted(() => {
            this.loadReport();
        });
    }

    // ── Number formatter (Indonesian locale) ──
    fmt(value) {
        if (value == null || value === '') return '0,00';
        const n = Number(value) || 0;
        return n.toLocaleString('id-ID', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
        });
    }

    // ── Switch report type ──
    switchReport(type) {
        this.state.activeReport = type;
        this.state.data = null;
        this.loadReport();
    }

    // ── Toggle GL account section ──
    toggleGLSection(accountId) {
        this.state.glCollapsed[accountId] = !this.state.glCollapsed[accountId];
    }

    // ── Load report data from API ──
    async loadReport() {
        const endpoints = {
            trial_balance: '/api/accounting/trial-balance',
            general_ledger: '/api/accounting/general-ledger',
            balance_sheet: '/api/accounting/balance-sheet',
            income_statement: '/api/accounting/income-statement',
        };

        const url = endpoints[this.state.activeReport];
        if (!url) return;

        this.state.loading = true;
        this.state.data = null;

        try {
            const csrf = document.querySelector('meta[name="csrf-token"]')?.content || window.__CSRF_TOKEN__;
            const resp = await fetch(url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': csrf,
                    'Accept': 'application/json',
                },
                body: JSON.stringify({
                    date_from: this.state.dateFrom,
                    date_to: this.state.dateTo,
                    target_move: this.state.targetMove,
                }),
            });

            if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
            this.state.data = await resp.json();
        } catch (e) {
            console.error('Report load error:', e);
            this.state.data = null;
        } finally {
            this.state.loading = false;
        }
    }

    // ── Print report ──
    printReport() {
        const content = this.reportRef?.el;
        if (!content) return;

        const printWindow = window.open('', '_blank');
        printWindow.document.write(`<!DOCTYPE html>
<html><head>
<title>${this.state.data?.title || 'Laporan Keuangan'}</title>
<style>
    body { font-family: 'Inter', sans-serif; padding: 20px; color: #1a1a2e; }
    h2 { margin: 0 0 4px; font-size: 18px; }
    p { margin: 0 0 16px; color: #64748b; font-size: 13px; }
    table { width: 100%; border-collapse: collapse; font-size: 12px; margin-bottom: 16px; }
    th { background: #f1f5f9; padding: 8px; text-align: left; border-bottom: 2px solid #cbd5e1; font-weight: 600; }
    td { padding: 6px 8px; border-bottom: 1px solid #e2e8f0; }
    .ls-col-num { text-align: right; font-variant-numeric: tabular-nums; }
    .ls-report-total-row { background: #f8fafc; font-weight: 700; border-top: 2px solid #94a3b8; }
    .ls-report-subtotal { background: #f8fafc; }
    .ls-negative { color: #dc2626; }
    .ls-bs-section, .ls-is-section { margin-bottom: 20px; }
    .ls-bs-section-title, .ls-is-section-title { font-size: 14px; font-weight: 700; color: #1e293b; margin: 12px 0 6px; padding: 4px 0; border-bottom: 1px solid #e2e8f0; }
    .ls-is-summary { margin-top: 20px; border-top: 2px solid #1e293b; padding-top: 12px; }
    .ls-is-summary-row { display: flex; justify-content: space-between; padding: 6px 0; font-size: 14px; }
    .ls-is-net-income { font-size: 16px; border-top: 2px solid #1e293b; margin-top: 8px; padding-top: 8px; }
    .ls-profit strong { color: #16a34a; }
    .ls-loss strong { color: #dc2626; }
    .ls-gl-account-header { font-weight: 700; background: #f1f5f9; padding: 8px; margin: 12px 0 4px; border-radius: 4px; }
    .ls-balanced { color: #16a34a; padding: 12px; text-align: center; }
    .ls-unbalanced { color: #dc2626; padding: 12px; text-align: center; }
    @media print { body { padding: 0; } }
</style>
</head><body>${content.innerHTML}</body></html>`);
        printWindow.document.close();
        setTimeout(() => { printWindow.print(); }, 300);
    }
}

window.AccountingReports = AccountingReports;
})();


/* --- [FILE: js/pages/adianti/owl-adianti-page.js] --- */
// ══════════════════════════════════════════════════════════════
//  AdiantiPageView — Owl Component
//  Renders any standard Adianti Controller inside AdvSoft SPA
// ══════════════════════════════════════════════════════════════
(function () {
    const { Component, useState, useRef, onMounted } = owl;

    class AdiantiPageView extends Component {
        static template = window.TEMPLATES.AdiantiPageView;

        setup() {
            this.contentSlot = useRef('contentSlot');
            this.state = useState({
                loading: true,
                error: null,
                className: '',
                method: '',
                htmlContent: '',
            });

            onMounted(() => {
                this.loadAdiantiController();
            });
        }

        async loadAdiantiController() {
            this.state.loading = true;
            this.state.error = null;

            const raw = window.location.hash.slice(1) || window.location.search.slice(1);
            const params = new URLSearchParams(raw);
            let className = params.get('class') || window.AdvSoftRootInstance?.state?.adiantiControllerClass || 'SampleController';
            if (className === 'adianti_page' || !className) {
                className = window.AdvSoftRootInstance?.state?.adiantiControllerClass || 'SampleController';
            }
            const method = params.get('method') || window.AdvSoftRootInstance?.state?.adiantiControllerMethod || '';

            this.state.className = className;
            this.state.method = method;

            params.set('class', className);
            if (method) params.set('method', method);

            try {
                const url = '/engine.php?' + params.toString();
                const res = await fetch(url, {
                    headers: {
                        'X-Requested-With': 'XMLHttpRequest',
                        'Accept': 'text/html, application/json, */*'
                    }
                });

                if (!res.ok) {
                    throw new Error(`HTTP Error ${res.status}: Gagal mengeksekusi controller`);
                }

                const html = await res.text();
                this.state.htmlContent = html;
                this.state.loading = false;

                // Inject into DOM
                setTimeout(() => {
                    if (this.contentSlot.el) {
                        this.contentSlot.el.innerHTML = html;
                        // Execute any scripts embedded in the Adianti output
                        const scripts = this.contentSlot.el.querySelectorAll('script');
                        scripts.forEach(s => {
                            try {
                                const fn = new Function(s.textContent);
                                fn.call(window);
                            } catch (err) {
                                console.warn('[Adianti Script Eval Note]:', err);
                            }
                        });
                    }
                }, 50);
            } catch (e) {
                console.error('[AdiantiPageView] Error:', e);
                this.state.error = e.message || 'Gagal memuat halaman Adianti.';
                this.state.loading = false;
            }
        }

        reloadPage() {
            this.loadAdiantiController();
        }
    }

    window.AdvSoftPageRegistry = window.AdvSoftPageRegistry || {};
    window.AdvSoftPageRegistry['adianti_page'] = AdiantiPageView;
    window.AdvSoftPageRegistry['sample_controller'] = AdiantiPageView;
    window.AdiantiPageView = AdiantiPageView;
})();


/* --- [FILE: js/pages/admin/owl-menu-editor.js] --- */
// ══════════════════════════════════════════════════════════════
//  MenuEditorView — Odoo-style Menu Item Editor Component
//  Features: tree CRUD, drag-drop, action binding, search
// ══════════════════════════════════════════════════════════════
(function () {
const { Component, useState, onWillStart, onMounted } = owl;
const RPC = window.AdvSoftRPC;

class MenuEditorView extends Component {
    static template = window.TEMPLATES.MenuEditor;
    static props = {};

    setup() {
        this.state = useState({
            loading: true,
            saving: false,
            savingAction: false,
            tree: [],
            stats: null,
            expanded: {},
            searchQuery: '',
            showInactive: false,

            // Dialog state
            dialogOpen: false,
            dialogMode: 'create', // 'create' | 'edit'
            editForm: this._emptyForm(),
            editingId: null,

            // Action create dialog
            actionDialogOpen: false,
            actionForm: { name: '', res_model: '', view_mode: 'list,form' },

            // Binding mode: 'action' | 'model' | 'security' | 'none'
            bindingMode: 'none',

            // Reference data
            availableModels: [],
            availableActions: [],

            // Drag state
            dragItem: null,
            dragOverId: null,

            // Toast
            toast: null,
            toastType: 'info',
        });

        onWillStart(async () => {
            await this.loadTree();
            await this.loadReferenceData();
        });
    }

    // ════════════════════════════════════════════════
    //  Data Loading
    // ════════════════════════════════════════════════

    async loadTree() {
        this.state.loading = true;
        try {
            const data = await RPC.get('/api/menu-editor/tree');
            this.state.tree = data.tree || [];
            this.state.stats = data.stats || {};
            // Auto-expand root items
            for (const item of this.state.tree) {
                this.state.expanded[item.id] = true;
            }
        } catch (e) {
            this.showToast('Failed to load menu tree: ' + e.message, 'error');
        }
        this.state.loading = false;
    }

    async loadReferenceData() {
        try {
            const [models, actions] = await Promise.all([
                RPC.get('/api/menu-editor/available-models'),
                RPC.get('/api/menu-editor/available-actions'),
            ]);
            this.state.availableModels = models || [];
            this.state.availableActions = actions || [];
        } catch (e) {
            console.warn('Failed to load reference data:', e);
        }
    }

    // ════════════════════════════════════════════════
    //  Computed properties
    // ════════════════════════════════════════════════

    get filteredTree() {
        let tree = this.state.tree;
        if (!this.state.showInactive) {
            tree = this._filterActive(tree);
        }
        if (this.state.searchQuery) {
            tree = this._filterBySearch(tree, this.state.searchQuery.toLowerCase());
        }
        return tree;
    }

    /**
     * Flatten the hierarchical tree into a flat array of { item, depth }
     * for rendering. Only includes children that are expanded.
     */
    get flatRows() {
        const rows = [];
        const walk = (items, depth) => {
            for (const item of items) {
                rows.push({ item, depth });
                if (item.children && item.children.length && this.state.expanded[item.id]) {
                    walk(item.children, depth + 1);
                }
            }
        };
        walk(this.filteredTree, 0);
        return rows;
    }

    get flatMenuList() {
        const result = [];
        const flatten = (items, prefix = '') => {
            for (const item of items) {
                const path = prefix ? `${prefix} / ${item.name}` : item.name;
                result.push({ id: item.id, path, name: item.name });
                if (item.children && item.children.length) {
                    flatten(item.children, path);
                }
            }
        };
        flatten(this.state.tree);
        return result;
    }

    // ════════════════════════════════════════════════
    //  Tree Operations
    // ════════════════════════════════════════════════

    toggleExpand(id) {
        this.state.expanded[id] = !this.state.expanded[id];
    }

    expandAll() {
        const expand = (items) => {
            for (const item of items) {
                this.state.expanded[item.id] = true;
                if (item.children) expand(item.children);
            }
        };
        expand(this.state.tree);
    }

    collapseAll() {
        this.state.expanded = {};
    }

    toggleInactiveFilter() {
        this.state.showInactive = !this.state.showInactive;
    }

    onSearch() {
        // Debounced by OWL reactivity
        if (this.state.searchQuery) {
            this.expandAll();
        }
    }

    // ════════════════════════════════════════════════
    //  CRUD: Create
    // ════════════════════════════════════════════════

    openCreateDialog() {
        this.state.editForm = this._emptyForm();
        this.state.editingId = null;
        this.state.dialogMode = 'create';
        this.state.bindingMode = 'none';
        this.state.dialogOpen = true;
    }

    openCreateChild(parent) {
        this.state.editForm = this._emptyForm();
        this.state.editForm.parent_id = String(parent.id);
        this.state.editingId = null;
        this.state.dialogMode = 'create';
        this.state.bindingMode = 'none';
        this.state.dialogOpen = true;
    }

    // ════════════════════════════════════════════════
    //  CRUD: Edit
    // ════════════════════════════════════════════════

    openEditDialog(item) {
        this.state.editForm = {
            name: item.name || '',
            parent_id: item.parent_id ? String(item.parent_id) : '',
            sequence: item.sequence || 10,
            active: item.active !== false,
            action_id: item.action_id ? String(item.action_id) : '',
            model: item.model || '',
            view_type: item.view_type || item.view || 'list',
            icon: item.icon || '',
            web_icon: item.web_icon || '',
            web_icon_color: item.web_icon_color || '#7C3AED',
            groups: item.groups || '',
            security_view: item.security_view || '',
        };
        this.state.editingId = item.id;
        this.state.dialogMode = 'edit';

        // Determine binding mode
        if (item.action_id || item.action) {
            this.state.bindingMode = 'action';
        } else if (item.model) {
            this.state.bindingMode = 'model';
        } else if (item.security_view) {
            this.state.bindingMode = 'security';
        } else {
            this.state.bindingMode = 'none';
        }

        this.state.dialogOpen = true;
    }

    // ════════════════════════════════════════════════
    //  CRUD: Save
    // ════════════════════════════════════════════════

    async saveDialog() {
        if (!this.state.editForm.name.trim()) {
            this.showToast('Menu name is required', 'error');
            return;
        }

        this.state.saving = true;

        // Build payload based on binding mode
        const payload = {
            name: this.state.editForm.name,
            parent_id: this.state.editForm.parent_id ? parseInt(this.state.editForm.parent_id) : null,
            sequence: parseInt(this.state.editForm.sequence) || 10,
            active: this.state.editForm.active,
            icon: this.state.editForm.icon || null,
            web_icon: this.state.editForm.web_icon || null,
            web_icon_color: this.state.editForm.web_icon_color || null,
            groups: this.state.editForm.groups || null,
            action_id: null,
            model: null,
            view_type: null,
            security_view: null,
        };

        if (this.state.bindingMode === 'action') {
            payload.action_id = this.state.editForm.action_id ? parseInt(this.state.editForm.action_id) : null;
        } else if (this.state.bindingMode === 'model') {
            payload.model = this.state.editForm.model || null;
            payload.view_type = this.state.editForm.view_type || 'list';
        } else if (this.state.bindingMode === 'security') {
            payload.security_view = this.state.editForm.security_view || null;
        }

        try {
            if (this.state.dialogMode === 'create') {
                await RPC.call('/api/menu-editor/create', payload);
                this.showToast('Menu item created successfully', 'success');
            } else {
                const csrf = RPC.csrf;
                const res = await fetch(`/api/menu-editor/update/${this.state.editingId}`, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf, 'Accept': 'application/json' },
                    body: JSON.stringify(payload),
                });
                if (!res.ok) {
                    const err = await res.json().catch(() => ({}));
                    throw new Error(err.error || 'Update failed');
                }
                this.showToast('Menu item updated successfully', 'success');
            }
            this.closeDialog();
            await this.loadTree();
        } catch (e) {
            this.showToast('Save failed: ' + e.message, 'error');
        }

        this.state.saving = false;
    }

    // ════════════════════════════════════════════════
    //  CRUD: Delete
    // ════════════════════════════════════════════════

    async deleteItem(item) {
        const childCount = this._countChildren(item);
        const msg = childCount > 0
            ? `Delete "${item.name}" and its ${childCount} child item(s)?`
            : `Delete "${item.name}"?`;
        if (!confirm(msg)) return;

        try {
            const csrf = RPC.csrf;
            const res = await fetch(`/api/menu-editor/delete/${item.id}`, {
                method: 'DELETE',
                headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf, 'Accept': 'application/json' },
            });
            if (!res.ok) throw new Error('Delete failed');
            this.showToast(`"${item.name}" deleted`, 'success');
            await this.loadTree();
        } catch (e) {
            this.showToast('Delete failed: ' + e.message, 'error');
        }
    }

    // ════════════════════════════════════════════════
    //  Active Toggle
    // ════════════════════════════════════════════════

    async toggleItemActive(item) {
        try {
            await RPC.call('/api/menu-editor/toggle-active', { id: item.id });
            item.active = !item.active;
            this.showToast(`"${item.name}" ${item.active ? 'activated' : 'deactivated'}`, 'info');
        } catch (e) {
            this.showToast('Toggle failed: ' + e.message, 'error');
        }
    }

    // ════════════════════════════════════════════════
    //  Drag & Drop Reordering
    // ════════════════════════════════════════════════

    onDragStart(ev, item) {
        this.state.dragItem = item;
        ev.dataTransfer.effectAllowed = 'move';
        ev.dataTransfer.setData('text/plain', String(item.id));
        // Add visual class
        ev.target.classList.add('dragging');
    }

    onDragOver(ev, overItem) {
        ev.preventDefault();
        ev.dataTransfer.dropEffect = 'move';
        if (this.state.dragItem && overItem.id !== this.state.dragItem.id) {
            this.state.dragOverId = overItem.id;
        }
    }

    onDragLeave(ev) {
        this.state.dragOverId = null;
    }

    async onDrop(ev, dropTarget) {
        ev.preventDefault();
        this.state.dragOverId = null;
        document.querySelectorAll('.dragging').forEach(el => el.classList.remove('dragging'));

        const dragItem = this.state.dragItem;
        this.state.dragItem = null;

        if (!dragItem || dragItem.id === dropTarget.id) return;

        // Move to same parent as drop target, positioned after it
        try {
            await RPC.call('/api/menu-editor/move', {
                menu_id: dragItem.id,
                parent_id: dropTarget.parent_id || null,
                sequence: (dropTarget.sequence || 10) + 5,
            });
            this.showToast(`Moved "${dragItem.name}"`, 'info');
            await this.loadTree();
        } catch (e) {
            this.showToast('Move failed: ' + e.message, 'error');
        }
    }

    // ════════════════════════════════════════════════
    //  Action Quick Create
    // ════════════════════════════════════════════════

    openActionCreate() {
        this.state.actionForm = { name: '', res_model: '', view_mode: 'list,form' };
        this.state.actionDialogOpen = true;
    }

    closeActionDialog() {
        this.state.actionDialogOpen = false;
    }

    async createActionInline() {
        if (!this.state.actionForm.name || !this.state.actionForm.res_model) {
            this.showToast('Action name and model are required', 'error');
            return;
        }

        this.state.savingAction = true;
        try {
            const result = await RPC.call('/api/menu-editor/create-action', this.state.actionForm);
            // Add to available actions
            this.state.availableActions.push(result.action);
            // Auto-select it
            this.state.editForm.action_id = String(result.action.id);
            this.showToast('Action created: ' + result.action.name, 'success');
            this.closeActionDialog();
        } catch (e) {
            this.showToast('Create action failed: ' + e.message, 'error');
        }
        this.state.savingAction = false;
    }

    // ════════════════════════════════════════════════
    //  Dialog helpers
    // ════════════════════════════════════════════════

    closeDialog() {
        this.state.dialogOpen = false;
        this.state.editingId = null;
    }

    _emptyForm() {
        return {
            name: '',
            parent_id: '',
            sequence: 10,
            active: true,
            action_id: '',
            model: '',
            view_type: 'list',
            icon: '',
            web_icon: '',
            web_icon_color: '#7C3AED',
            groups: '',
            security_view: '',
        };
    }

    // ════════════════════════════════════════════════
    //  Filtering helpers
    // ════════════════════════════════════════════════

    _filterActive(items) {
        return items.filter(item => item.active !== false).map(item => ({
            ...item,
            children: item.children ? this._filterActive(item.children) : [],
        }));
    }

    _filterBySearch(items, query) {
        const result = [];
        for (const item of items) {
            const nameMatch = (item.name || '').toLowerCase().includes(query);
            const modelMatch = (item.model || '').toLowerCase().includes(query);
            const actionMatch = (item.action?.res_model || '').toLowerCase().includes(query);
            const filteredChildren = item.children ? this._filterBySearch(item.children, query) : [];

            if (nameMatch || modelMatch || actionMatch || filteredChildren.length > 0) {
                result.push({ ...item, children: filteredChildren });
            }
        }
        return result;
    }

    _countChildren(item) {
        let count = 0;
        if (item.children) {
            count = item.children.length;
            for (const child of item.children) {
                count += this._countChildren(child);
            }
        }
        return count;
    }

    // ════════════════════════════════════════════════
    //  Toast notification
    // ════════════════════════════════════════════════

    showToast(message, type = 'info') {
        this.state.toast = message;
        this.state.toastType = type;
        clearTimeout(this._toastTimer);
        this._toastTimer = setTimeout(() => {
            this.state.toast = null;
        }, 3500);
    }
}

// Export globally
window.MenuEditorView = MenuEditorView;
})();


/* --- [FILE: js/pages/admin/owl-security-views.js] --- */
// ══════════════════════════════════════════════════════════════════
//  AdvSoft Security Management UI
//  4 components: AccessRights (matrix), RecordRules, Groups, Users
//  Each is a full Odoo-style view with list+form switching.
// ══════════════════════════════════════════════════════════════════
(function () {
const { Component, useState, useRef, onWillStart, onMounted } = owl;
const RPC = window.AdvSoftRPC;
const icons = window.AdvSoftIcons;

const PERM_COLS = [
    { key: 'r', label: 'Read',   short: 'R', color: '#059669' },
    { key: 'w', label: 'Write',  short: 'W', color: '#2563eb' },
    { key: 'c', label: 'Create', short: 'C', color: '#7c3aed' },
    { key: 'u', label: 'Delete', short: 'D', color: '#dc2626' },
];

function esc(s) {
    if (s == null) return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ═══════════════════════════════════════════════════════════════
//  0. SECURITY OVERVIEW
// ═══════════════════════════════════════════════════════════════
class SecurityOverview extends Component {
    static template = window.TEMPLATES.securityOverview;
    static props = {};

    setup() {
        this.state = useState({
            loading: true,
            data: {
                counts: { users: 0, groups: 0, models: 0, acl_rules: 0, record_rules: 0 },
                top_users: []
            }
        });
        onMounted(() => this.load());
    }

    async load() {
        this.state.loading = true;
        try {
            const res = await RPC.get('/api/security/overview');
            if (res && res.counts) {
                this.state.data = res;
            }
        } catch (e) {
            console.error('Load overview failed', e);
        }
        this.state.loading = false;
    }
}
window.SecurityOverview = SecurityOverview;

// ═══════════════════════════════════════════════════════════════
//  1. ACCESS RIGHTS MATRIX — the iconic Odoo grid view
// ═══════════════════════════════════════════════════════════════
class AccessRights extends Component {
    static template = window.TEMPLATES.accessRights;
    static props = {};

    setup() {
        this.state = useState({
            loading: true,
            groups: [],
            models: [],
            cells:  {},
            filter: '',
            selectedModule: 'all',
            saving: {},
            showCreate: false,
            newModel: { model: '', name: '' },
        });
        onMounted(() => this.load());
    }

    get modules() {
        const set = new Set(this.state.models.map(m => m.module || 'AdvSoft'));
        return Array.from(set).sort();
    }

    get filteredModels() {
        const term = this.state.filter.toLowerCase();
        const mod = this.state.selectedModule;
        return this.state.models.filter(m => {
            if (mod !== 'all' && (m.module || 'AdvSoft') !== mod) return false;
            if (!term) return true;
            return m.model.toLowerCase().includes(term) ||
                   (m.name || '').toLowerCase().includes(term);
        });
    }

    get filteredGroups() {
        const term = this.state.filter.toLowerCase();
        if (!term) return this.state.groups;
        return this.state.groups.filter(g => g.name.toLowerCase().includes(term));
    }

    getCell(modelId, groupId) {
        return this.state.cells[modelId + ':' + groupId] || null;
    }

    isSaving(modelId, groupId, perm) {
        return !!this.state.saving[modelId + ':' + groupId + ':' + perm];
    }

    async load() {
        this.state.loading = true;
        try {
            const res = await RPC.get('/api/security/acl/matrix');
            this.state.groups = res.groups;
            this.state.models = res.models;
            this.state.cells  = res.cells;
        } catch (e) {
            console.error('Load matrix failed', e);
            alert('Failed to load ACL matrix: ' + e.message);
        }
        this.state.loading = false;
    }

    async toggleCell(modelId, groupId, perm, currentValue) {
        const key = modelId + ':' + groupId + ':' + perm;
        this.state.saving[key] = true;
        try {
            const res = await RPC.call('/api/security/acl/toggle', {
                model_id: modelId, group_id: groupId, perm, value: !currentValue,
            });
            const cellKey = modelId + ':' + groupId;
            const existing = this.state.cells[cellKey] || {
                r: false, w: false, c: false, u: false, group_id: groupId,
            };
            this.state.cells[cellKey] = {
                ...existing,
                ...res.cell,
                acl_id: res.acl_id,
                group_id: groupId,
            };
        } catch (e) {
            alert('Toggle failed: ' + e.message);
        }
        this.state.saving[key] = false;
    }

    async syncModels() {
        if (!confirm('Re-discover all Odoo model definitions and register them in ir.model?')) return;
        try {
            const res = await RPC.call('/api/security/sync-models', {});
            alert(`Synced: discovered=${res.discovered}, in db=${res.in_database}`);
            await this.load();
        } catch (e) {
            alert('Sync failed: ' + e.message);
        }
    }

    permColor(permKey) {
        return (PERM_COLS.find(p => p.key === permKey) || {}).color || '#6b7280';
    }
}

window.AccessRights = AccessRights;

// ═══════════════════════════════════════════════════════════════
//  2. RECORD RULES — tree + form with domain editor
// ═══════════════════════════════════════════════════════════════
class RecordRules extends Component {
    static template = window.TEMPLATES.recordRules;
    static props = {};

    setup() {
        this.state = useState({
            mode: 'list',              // 'list' | 'form'
            records: [],
            loading: true,
            search: '',
            current: null,             // form values
            models: [],                // for model_id select
            groups: [],                // for groups M2M
            error: '',
            saving: false,
        });
        onMounted(() => this.load());
    }

    async load() {
        this.state.loading = true;
        try {
            const [rules, models, groups] = await Promise.all([
                RPC.searchRead('ir.rule', [], { order: 'id asc', limit: 200 }),
                RPC.nameSearch('ir.model', '', 200),
                RPC.nameSearch('res.groups', '', 200),
            ]);
            this.state.records = rules.records || [];
            this.state.models  = models.results || models;
            this.state.groups  = groups.results || groups;
        } catch (e) {
            alert('Load failed: ' + e.message);
        }
        this.state.loading = false;
    }

    get filteredRecords() {
        const q = this.state.search.toLowerCase();
        if (!q) return this.state.records;
        return this.state.records.filter(r =>
            (r.name || '').toLowerCase().includes(q) ||
            (r.model_id && String(r.model_id[1] || '').toLowerCase().includes(q))
        );
    }

    newRecord() {
        this.state.current = {
            name: '',
            model_id: false,
            domain_force: '[]',
            global: false,
            groups: [],
            perm_read: true,
            perm_write: false,
            perm_create: false,
            perm_unlink: false,
            active: true,
        };
        this.state.mode = 'form';
        this.state.error = '';
    }

    editRecord(rec) {
        this.state.current = {
            id: rec.id,
            name: rec.name || '',
            model_id: rec.model_id ? rec.model_id[0] : false,
            domain_force: rec.domain_force || '[]',
            global: !!rec.global,
            groups: Array.isArray(rec.groups) ? rec.groups.map(g => (g && typeof g === 'object' && !Array.isArray(g)) ? g.id : (Array.isArray(g) ? g[0] : g)) : [],
            perm_read: !!rec.perm_read,
            perm_write: !!rec.perm_write,
            perm_create: !!rec.perm_create,
            perm_unlink: !!rec.perm_unlink,
            active: rec.active === undefined ? true : !!rec.active,
        };
        this.state.mode = 'form';
        this.state.error = '';
    }

    backToList() {
        this.state.mode = 'list';
        this.state.current = null;
    }

    async save() {
        const c = this.state.current;
        if (!c.name.trim()) { this.state.error = 'Name is required.'; return; }
        if (!c.model_id)    { this.state.error = 'Model is required.'; return; }
        if (!c.domain_force.trim()) { this.state.error = 'Domain is required.'; return; }

        this.state.saving = true;
        this.state.error = '';
        try {
            const vals = {
                name: c.name,
                model_id: c.model_id,
                domain_force: c.domain_force,
                global: c.global,
                groups: [[6, 0, c.groups]],   // M2M replace
                perm_read: c.perm_read,
                perm_write: c.perm_write,
                perm_create: c.perm_create,
                perm_unlink: c.perm_unlink,
                active: c.active,
            };
            if (c.id) {
                await RPC.write('ir.rule', [c.id], vals);
            } else {
                await RPC.create('ir.rule', vals);
            }
            await this.load();
            this.backToList();
        } catch (e) {
            this.state.error = e.message || String(e);
        }
        this.state.saving = false;
    }

    async deleteRecord(rec) {
        if (!confirm(`Delete rule "${rec.name}"?`)) return;
        try {
            await RPC.unlink('ir.rule', [rec.id]);
            await this.load();
        } catch (e) {
            alert('Delete failed: ' + e.message);
        }
    }

    toggleGroupInForm(gid) {
        const i = this.state.current.groups.indexOf(gid);
        if (i >= 0) this.state.current.groups.splice(i, 1);
        else this.state.current.groups.push(gid);
    }

    insertPlaceholder(ph) {
        this.state.current.domain_force += ph;
    }

    // Predefined domain templates
    insertTemplate(tpl) {
        this.state.current.domain_force = tpl;
    }
}

window.RecordRules = RecordRules;

// ═══════════════════════════════════════════════════════════════
//  3. GROUPS — tree + form + users
// ═══════════════════════════════════════════════════════════════
class GroupsView extends Component {
    static template = window.TEMPLATES.groupsView;
    static props = {};

    setup() {
        this.state = useState({
            mode: 'list',
            records: [],
            loading: true,
            search: '',
            current: null,
            categories: [],
            groups: [],
            error: '',
            saving: false,
            groupUsers: null,
        });
        onMounted(() => this.load());
    }

    async load() {
        this.state.loading = true;
        try {
            const [groups, categories, allGroups] = await Promise.all([
                RPC.searchRead('res.groups', [], { order: 'name asc', limit: 200 }),
                RPC.searchRead('res.groups.category', [], { order: 'name asc', limit: 100 }),
                RPC.nameSearch('res.groups', '', 200),
            ]);
            this.state.records   = groups.records || [];
            this.state.categories = categories.records || [];
            this.state.groups    = allGroups.results || allGroups;
        } catch (e) {
            alert('Load failed: ' + e.message);
        }
        this.state.loading = false;
    }

    get filteredRecords() {
        const q = this.state.search.toLowerCase();
        if (!q) return this.state.records;
        return this.state.records.filter(r =>
            (r.name || '').toLowerCase().includes(q) ||
            (r.description || '').toLowerCase().includes(q)
        );
    }

    newRecord() {
        this.state.current = {
            name: '',
            description: '',
            category_id: false,
            share: false,
            implied_ids: [],
        };
        this.state.mode = 'form';
        this.state.error = '';
        this.state.groupUsers = null;
    }

    editRecord(rec) {
        this.state.current = {
            id: rec.id,
            name: rec.name || '',
            description: rec.description || '',
            category_id: rec.category_id ? (Array.isArray(rec.category_id) ? rec.category_id[0] : (typeof rec.category_id === 'object' ? rec.category_id.id : rec.category_id)) : false,
            share: !!rec.share,
            implied_ids: Array.isArray(rec.implied_ids) ? rec.implied_ids.map(g => (g && typeof g === 'object' && !Array.isArray(g)) ? g.id : (Array.isArray(g) ? g[0] : g)) : [],
        };
        this.state.mode = 'form';
        this.state.error = '';
        this.loadGroupUsers(rec.id);
    }

    async loadGroupUsers(gid) {
        try {
            const res = await RPC.get('/api/security/groups/' + gid + '/users');
            this.state.groupUsers = res;
        } catch { this.state.groupUsers = null; }
    }

    backToList() {
        this.state.mode = 'list';
        this.state.current = null;
        this.state.groupUsers = null;
    }

    async save() {
        const c = this.state.current;
        if (!c.name.trim()) { this.state.error = 'Name is required.'; return; }
        this.state.saving = true;
        this.state.error = '';
        try {
            const vals = {
                name: c.name,
                description: c.description,
                category_id: c.category_id || false,
                share: c.share,
                implied_ids: [[6, 0, c.implied_ids]],
            };
            if (c.id) {
                await RPC.write('res.groups', [c.id], vals);
            } else {
                const res = await RPC.create('res.groups', vals);
                c.id = res.id;
            }
            await this.load();
            this.state.mode = 'form';   // stay in form to view users
            this.loadGroupUsers(c.id);
        } catch (e) {
            this.state.error = e.message || String(e);
        }
        this.state.saving = false;
    }

    async deleteRecord(rec) {
        if (!confirm(`Delete group "${rec.name}"?\nUsers in this group will lose its permissions.`)) return;
        try {
            await RPC.unlink('res.groups', [rec.id]);
            await this.load();
        } catch (e) {
            alert('Delete failed: ' + e.message);
        }
    }

    toggleImplied(gid) {
        const i = this.state.current.implied_ids.indexOf(gid);
        if (i >= 0) this.state.current.implied_ids.splice(i, 1);
        else this.state.current.implied_ids.push(gid);
    }
}

window.GroupsView = GroupsView;

// ═══════════════════════════════════════════════════════════════
//  4. USERS — tree + form + groups + admin password reset
// ═══════════════════════════════════════════════════════════════
class UsersView extends Component {
    static template = window.TEMPLATES.usersView;
    static props = {};

    setup() {
        this.state = useState({
            mode: 'list',
            records: [],
            loading: true,
            search: '',
            current: null,
            groups: [],
            companies: [],
            error: '',
            saving: false,
            showPasswordReset: false,
            passwordForm: { password: '', password_confirmation: '' },
            passwordMessage: '',
        });
        onMounted(() => this.load());
    }

    async load() {
        this.state.loading = true;
        try {
            const [users, groups, companies] = await Promise.all([
                RPC.searchRead('res.users', [], { order: 'login asc', limit: 200 }),
                RPC.nameSearch('res.groups', '', 200),
                RPC.nameSearch('res.company', '', 50),
            ]);
            this.state.records  = users.records || [];
            this.state.groups   = groups.results || groups;
            this.state.companies = companies.results || companies;
        } catch (e) {
            alert('Load failed: ' + e.message);
        }
        this.state.loading = false;
    }

    get filteredRecords() {
        const q = this.state.search.toLowerCase();
        if (!q) return this.state.records;
        return this.state.records.filter(r =>
            (r.login || '').toLowerCase().includes(q) ||
            (r.name || '').toLowerCase().includes(q) ||
            (r.email || '').toLowerCase().includes(q)
        );
    }

    newRecord() {
        this.state.current = {
            login: '',
            name: '',
            email: '',
            company_id: false,
            active: true,
            share: false,
            signature: '',
            group_ids: [],
            password: '',
        };
        this.state.mode = 'form';
        this.state.error = '';
        this.state.showPasswordReset = false;
    }

    editRecord(rec) {
        this.state.current = {
            id: rec.id,
            login: rec.login,
            name: rec.name || '',
            email: rec.email || '',
            company_id: rec.company_id ? (Array.isArray(rec.company_id) ? rec.company_id[0] : (typeof rec.company_id === 'object' ? rec.company_id.id : rec.company_id)) : false,
            active: rec.active === undefined ? true : !!rec.active,
            share: !!rec.share,
            signature: rec.signature || '',
            group_ids: Array.isArray(rec.groups_id) ? rec.groups_id.map(g => (g && typeof g === 'object' && !Array.isArray(g)) ? g.id : (Array.isArray(g) ? g[0] : g)) : [],
            password: '',
        };
        this.state.mode = 'form';
        this.state.error = '';
        this.state.showPasswordReset = false;
    }

    backToList() {
        this.state.mode = 'list';
        this.state.current = null;
        this.state.showPasswordReset = false;
    }

    async save() {
        const c = this.state.current;
        if (!c.login.trim()) { this.state.error = 'Login is required.'; return; }
        if (!c.id && !c.password) { this.state.error = 'Password is required for new users.'; return; }

        this.state.saving = true;
        this.state.error = '';
        try {
            const vals = {
                login: c.login,
                name: c.name,
                email: c.email,
                company_id: c.company_id || false,
                active: c.active,
                share: c.share,
                signature: c.signature,
                groups_id: [[6, 0, c.group_ids]],
            };
            if (c.id) {
                await RPC.write('res.users', [c.id], vals);
            } else {
                vals.password = c.password;
                const res = await RPC.create('res.users', vals);
                c.id = res.id;
            }
            // Sync groups separately (M2M through relation table)
            await RPC.call('/api/security/users/' + c.id + '/groups', {
                group_ids: c.group_ids,
            });
            await this.load();
        } catch (e) {
            this.state.error = e.message || String(e);
        }
        this.state.saving = false;
    }

    async deleteRecord(rec) {
        if (!confirm(`Delete user "${rec.login}"?`)) return;
        try {
            await RPC.unlink('res.users', [rec.id]);
            await this.load();
        } catch (e) {
            alert('Delete failed: ' + e.message);
        }
    }

    toggleGroupInForm(gid) {
        const i = this.state.current.group_ids.indexOf(gid);
        if (i >= 0) this.state.current.group_ids.splice(i, 1);
        else this.state.current.group_ids.push(gid);
    }

    openPasswordReset() {
        this.state.showPasswordReset = true;
        this.state.passwordForm = { password: '', password_confirmation: '' };
        this.state.passwordMessage = '';
    }

    async submitPasswordReset() {
        const f = this.state.passwordForm;
        if (f.password.length < 6) {
            this.state.passwordMessage = 'Password must be at least 6 characters.';
            return;
        }
        if (f.password !== f.password_confirmation) {
            this.state.passwordMessage = 'Passwords do not match.';
            return;
        }
        try {
            await RPC.call('/api/security/users/' + this.state.current.id + '/password', {
                password: f.password,
                password_confirmation: f.password_confirmation,
            });
            this.state.passwordMessage = 'Password reset successfully.';
            this.state.passwordForm = { password: '', password_confirmation: '' };
        } catch (e) {
            this.state.passwordMessage = 'Error: ' + e.message;
        }
    }
}

window.UsersView = UsersView;
})();


/* --- [FILE: js/pages/admin/owl-view-builder.js] --- */
// View Builder Component — Odoo Studio-style view configuration
(function(){
const { Component, useState, onMounted, markup } = owl;
const RPC = window.AdvSoftRPC;

class ViewBuilderView extends Component {
    static template = window.TEMPLATES.ViewBuilder;
    static props = {};

    setup() {
        this._undoStack = [];
        this._redoStack = [];
        this.state = useState({
            activeTab: 'list',
            models: [],
            selectedModel: '',
            fields: {},
            arch: {},
            selectedField: null,
            selectedGroup: null,
            showXml: false,
            xmlPreview: '',
            formActiveTab: '',
            toast: '',
            toastType: '',
            loading: false,
            fieldSearch: '',
            showCode: false,
            codePreview: '',
        });
        onMounted(() => this.loadModels());
    }

    // ── Tab definitions ────────────────────────────────
    get builderTabs() {
        return [
            { id: 'list', label: 'List builder', icon: 'table' },
            { id: 'form', label: 'Form builder', icon: 'file-text' },
            { id: 'kanban', label: 'Kanban builder', icon: 'columns' },
            { id: 'calendar', label: 'Calendar builder', icon: 'calendar' },
            { id: 'pivot', label: 'Pivot builder', icon: 'grid-3x3' },
            { id: 'spreadsheet', label: 'Spreadsheet builder', icon: 'file-spreadsheet' },
        ];
    }

    // ── Palette items ──────────────────────────────────
    get listComponents() {
        return [
            { id: 'handle', label: 'Handle (drag)', icon: 'grip-vertical', type: 'handle' },
            { id: 'char', label: 'Char / text', icon: 'type', type: 'char' },
            { id: 'many2one', label: 'Many2one', icon: 'link', type: 'many2one' },
            { id: 'date', label: 'Date', icon: 'calendar', type: 'date' },
            { id: 'monetary', label: 'Monetary', icon: 'dollar-sign', type: 'monetary' },
            { id: 'selection', label: 'Selection badge', icon: 'list', type: 'selection' },
            { id: 'boolean', label: 'Boolean toggle', icon: 'toggle-left', type: 'boolean' },
            { id: 'button', label: 'Button', icon: 'square', type: 'button' },
        ];
    }

    get formComponents() {
        return [
            { id: 'group', label: 'Group (2-col)', icon: 'columns', type: 'group' },
            { id: 'tab', label: 'Notebook Tab', icon: 'book-open', type: 'tab' },
            { id: 'separator', label: 'Separator', icon: 'minus', type: 'separator' },
            { id: 'statusbar', label: 'Statusbar', icon: 'git-branch', type: 'statusbar' },
            { id: 'chatter', label: 'Chatter', icon: 'message-circle', type: 'chatter' },
            { id: 'stat_button', label: 'Stat Button', icon: 'bar-chart-2', type: 'stat_button' },
        ];
    }

    get listAttrCards() {
        return [
            { name: 'optional', type: '"show"/"hide"', desc: 'Column can be hidden/shown by user via gear icon.' },
            { name: 'column_invisible', type: 'domain', desc: 'Hide column based on parent context expression.' },
            { name: 'sum / avg / max / min', type: 'string label', desc: 'Show aggregation in footer. String = label text.' },
            { name: 'decoration-danger/warning', type: 'domain expr', desc: 'Color rows based on field condition expression.' },
            { name: 'width', type: 'string "80px"', desc: 'Override column width manually (px or ratio).' },
            { name: 'nolabel', type: 'bool "1"', desc: 'Hide column header label. Useful for handle/button.' },
        ];
    }

    // ── Field getters ──────────────────────────────────
    get availableFields() {
        const fields = this.state.fields;
        let list = Object.values(fields).filter(f => !f.invisible);
        const q = (this.state.fieldSearch || '').trim().toLowerCase();
        if (q) {
            list = list.filter(f => (f.string || '').toLowerCase().includes(q) || (f.name || '').toLowerCase().includes(q) || (f.type || '').toLowerCase().includes(q));
        }
        return list.sort((a, b) => (a.string || '').localeCompare(b.string || ''));
    }

    get groupableFields() {
        return Object.values(this.state.fields).filter(f => f.groupable);
    }

    get numericFields() {
        return Object.values(this.state.fields).filter(f => f.is_numeric);
    }

    get dateFields() {
        return Object.values(this.state.fields).filter(f => f.is_temporal);
    }

    get stringFields() {
        return Object.values(this.state.fields).filter(f => f.is_string || f.type === 'char');
    }

    get m2mFields() {
        return Object.values(this.state.fields).filter(f => f.type === 'many2many');
    }

    get o2mFields() {
        return Object.values(this.state.fields).filter(f => f.type === 'one2many');
    }

    get binaryFields() {
        return Object.values(this.state.fields).filter(f => f.type === 'binary' || f.type === 'image');
    }

    get colorFields() {
        return Object.values(this.state.fields).filter(f => f.widget === 'color_picker' || f.name === 'color');
    }

    get selectionFields() {
        return Object.values(this.state.fields).filter(f => f.type === 'selection');
    }

    get allFields() {
        return Object.values(this.state.fields);
    }

    getFieldLabel(fieldName) {
        const f = this.state.fields[fieldName];
        return f ? (f.string || f.name) : fieldName;
    }

    removeFromArchArray(key, value) {
        if (!this.state.arch[key]) return;
        this.state.arch[key] = this.state.arch[key].filter(v => v !== value);
        this.state.arch = { ...this.state.arch };
    }

    // ── Calendar days generator ─────────────────────────
    get calendarDays() {
        const days = [];
        const today = new Date();
        const first = new Date(today.getFullYear(), today.getMonth(), 1);
        const startDay = (first.getDay() + 6) % 7; // Monday=0
        for (let i = 0; i < 35; i++) {
            const d = new Date(first);
            d.setDate(1 - startDay + i);
            days.push({
                num: d.getDate(),
                month: d.getMonth(),
                today: d.toDateString() === today.toDateString(),
                otherMonth: d.getMonth() !== today.getMonth(),
                event: [5, 12, 18, 23, 27].includes(d.getDate()) && d.getMonth() === today.getMonth(),
            });
        }
        return days;
    }

    // ── Data loading ───────────────────────────────────
    async loadModels() {
        try {
            const resp = await fetch('/api/view-builder/models');
            const models = await resp.json();
            this.state.models = models;
        } catch (e) {
            console.error('Failed to load models', e);
        }
    }

    async onModelChange() {
        const model = this.state.selectedModel;
        if (!model) { this.state.fields = {}; return; }
        try {
            this.state.loading = true;
            const data = await RPC.call('/api/view-builder/fields', { model });
            this.state.fields = data.fields || {};
            await this.loadCurrentView();
        } catch (e) {
            this.showToast('Failed to load model fields', 'error');
        } finally {
            this.state.loading = false;
        }
    }

    async loadCurrentView() {
        try {
            const data = await RPC.call('/api/view-builder/load-view', {
                model: this.state.selectedModel,
                type: this.state.activeTab,
            });
            if (data.arch && Object.keys(data.arch).length) {
                this.state.arch = { ...data.arch };
                if (data.arch.tabs && data.arch.tabs.length) {
                    this.state.formActiveTab = data.arch.tabs[0].name || '';
                }
            } else {
                this.initDefaultArch();
            }
        } catch (e) {
            this.initDefaultArch();
        }
    }

    initDefaultArch() {
        const fieldNames = Object.keys(this.state.fields).slice(0, 6);
        const tab = this.state.activeTab;
        if (tab === 'list') {
            this.state.arch = { fields: fieldNames, column_config: {}, decoration: {}, limit: 80 };
        } else if (tab === 'form') {
            const half = Math.ceil(fieldNames.length / 2);
            this.state.arch = {
                string: this.state.selectedModel,
                groups: [{ columns: [fieldNames.slice(0, half), fieldNames.slice(half)] }],
                tabs: [], statusbar: '', header_buttons: [], field_config: {},
            };
        } else if (tab === 'kanban') {
            const gb = this.groupableFields[0];
            this.state.arch = {
                default_group_by: gb?.name || '', quick_create: true,
                card_title: Object.keys(this.state.fields)[0] || 'name',
                card_fields: fieldNames.slice(1, 4), card_tags: '',
                card_image: '', color_field: '', card_footer: ['priority'],
            };
        } else if (tab === 'calendar') {
            const df = this.dateFields[0];
            this.state.arch = {
                date_start: df?.name || '', date_stop: '', color: '',
                mode: 'month', event_display_fields: fieldNames.slice(0, 2),
                quick_create: true, create_name_field: '', date_delay: '',
                color_legend: true,
            };
        } else if (tab === 'pivot') {
            const dims = this.groupableFields.slice(0, 2).map(f => f.name);
            const meas = this.numericFields.slice(0, 2).map(f => f.name);
            this.state.arch = {
                row_groupby: dims.slice(0, 1), col_groupby: dims.slice(1, 2), measures: meas,
            };
        } else if (tab === 'spreadsheet') {
            this.state.arch = {
                fields: fieldNames, column_width: 120, row_height: 28,
                limit: 1000, aggregation: 'sum', readonly: false,
            };
        }
    }

    // ── Field manipulation ─────────────────────────────
    addField(fieldName) {
        const tab = this.state.activeTab;
        if (tab === 'list') {
            if (!this.state.arch.fields) this.state.arch.fields = [];
            if (!this.state.arch.fields.includes(fieldName)) {
                this.state.arch.fields = [...this.state.arch.fields, fieldName];
            }
        } else if (tab === 'kanban') {
            if (!this.state.arch.card_fields) this.state.arch.card_fields = [];
            if (!this.state.arch.card_fields.includes(fieldName)) {
                this.state.arch.card_fields = [...this.state.arch.card_fields, fieldName];
            }
        } else if (tab === 'spreadsheet') {
            if (!this.state.arch.fields) this.state.arch.fields = [];
            if (!this.state.arch.fields.includes(fieldName)) {
                this.state.arch.fields = [...this.state.arch.fields, fieldName];
            }
        } else if (tab === 'calendar') {
            if (!this.state.arch.event_display_fields) this.state.arch.event_display_fields = [];
            if (!this.state.arch.event_display_fields.includes(fieldName)) {
                this.state.arch.event_display_fields = [...this.state.arch.event_display_fields, fieldName];
            }
        } else if (tab === 'form') {
            this.removeSelectedFieldByName(fieldName);

            // If a notebook tab is active and is layout type, add to that tab's groups
            const activeTab = this.state.formActiveTab
                ? (this.state.arch.tabs || []).find(t => t.name === this.state.formActiveTab)
                : null;

            if (activeTab && (!activeTab.type || activeTab.type === 'layout')) {
                // Add to active tab's groups
                if (!activeTab.groups || !activeTab.groups.length) {
                    activeTab.groups = [{ columns: [[], []] }];
                }
                const grp = activeTab.groups[0];
                if (grp.columns && grp.columns.length) {
                    grp.columns[0] = [...grp.columns[0], fieldName];
                }
            } else {
                // Add to main form groups
                if (!this.state.arch.groups || !this.state.arch.groups.length) {
                    this.state.arch.groups = [{ columns: [[], []] }];
                }
                const grp = this.state.arch.groups[0];
                if (grp.columns && grp.columns.length) {
                    grp.columns[0] = [...grp.columns[0], fieldName];
                }
            }
            this.state.arch = { ...this.state.arch };
        }
        this.selectField(fieldName);
    }

    // ── Layout Component click-to-add ─────────────────
    addFormComponent(type) {
        this._pushUndo();
        if (type === 'group') {
            const activeTab = this.state.formActiveTab
                ? (this.state.arch.tabs || []).find(t => t.name === this.state.formActiveTab)
                : null;
            if (activeTab && (!activeTab.type || activeTab.type === 'layout')) {
                activeTab.groups = activeTab.groups || [];
                activeTab.groups.push({ columns: [[], []] });
            } else {
                this.state.arch.groups = this.state.arch.groups || [];
                this.state.arch.groups.push({ columns: [[], []] });
            }
        } else if (type === 'tab') {
            this.state.arch.tabs = this.state.arch.tabs || [];
            const newTab = { name: 'tab_' + Date.now(), label: 'New Tab' };
            this.state.arch.tabs.push(newTab);
            if (this.state.arch.tabs.length === 1) {
                this.state.formActiveTab = newTab.name;
            }
        } else if (type === 'separator') {
            this.state.arch.groups = this.state.arch.groups || [];
            this.state.arch.groups.push({ columns: [['separator_' + Date.now()], []] });
        } else if (type === 'statusbar') {
            this.state.arch.statusbar = this.state.arch.statusbar || '1';
        } else if (type === 'chatter') {
            this.state.arch.chatter = true;
        } else if (type === 'stat_button') {
            this.state.arch.stat_buttons = this.state.arch.stat_buttons || [];
            this.state.arch.stat_buttons.push({ name: 'stat_' + Date.now() });
        }
        this.state.arch = { ...this.state.arch };
    }

    selectField(fieldName) {
        this.state.selectedField = fieldName;
        this.state.selectedTab = null;
        this.state.selectedGroup = null;
    }

    removeSelectedField() {
        const fn = this.state.selectedField;
        if (!fn) return;
        if (this.state.activeTab === 'list' && this.state.arch.fields) {
            this.state.arch.fields = this.state.arch.fields.filter(f => f !== fn);
            if (this.state.arch.column_config) delete this.state.arch.column_config[fn];
        }
        if (this.state.activeTab === 'spreadsheet' && this.state.arch.fields) {
            this.state.arch.fields = this.state.arch.fields.filter(f => f !== fn);
        }
        if (this.state.activeTab === 'kanban' && this.state.arch.card_fields) {
            this.state.arch.card_fields = this.state.arch.card_fields.filter(f => f !== fn);
        }
        if (this.state.activeTab === 'form') {
            let removed = false;
            if (this.state.arch.groups) {
                for (let g = 0; g < this.state.arch.groups.length; g++) {
                    const grp = this.state.arch.groups[g];
                    for (let c = 0; c < (grp.columns || []).length; c++) {
                        const col = grp.columns[c];
                        const idx = col.findIndex(f => (typeof f === 'string' ? f : f.name) === fn);
                        if (idx !== -1) {
                            col.splice(idx, 1);
                            removed = true;
                        }
                    }
                }
            }
            if (this.state.arch.tabs) {
                for (let t = 0; t < this.state.arch.tabs.length; t++) {
                    const tab = this.state.arch.tabs[t];
                    if (tab.groups) {
                        for (let g = 0; g < tab.groups.length; g++) {
                            const grp = tab.groups[g];
                            for (let c = 0; c < (grp.columns || []).length; c++) {
                                const col = grp.columns[c];
                                const idx = col.findIndex(f => (typeof f === 'string' ? f : f.name) === fn);
                                if (idx !== -1) {
                                    col.splice(idx, 1);
                                    removed = true;
                                }
                            }
                        }
                    }
                }
            }
            if (removed) this.state.arch = { ...this.state.arch };
        }
        this.state.selectedField = null;
    }

    setColumnConfig(fieldName, key, value) {
        if (!this.state.arch.column_config) this.state.arch.column_config = {};
        if (!this.state.arch.column_config[fieldName]) this.state.arch.column_config[fieldName] = {};
        if (key === '_agg') {
            delete this.state.arch.column_config[fieldName].sum;
            delete this.state.arch.column_config[fieldName].avg;
            delete this.state.arch.column_config[fieldName].max;
            delete this.state.arch.column_config[fieldName].min;
            if (value) this.state.arch.column_config[fieldName][value] = 'Total';
        } else {
            if (value) {
                this.state.arch.column_config[fieldName][key] = value;
            } else {
                delete this.state.arch.column_config[fieldName][key];
            }
        }
        this.state.arch = { ...this.state.arch };
    }

    addToArchArray(key, value) {
        if (!value) return;
        if (!this.state.arch[key]) this.state.arch[key] = [];
        if (!this.state.arch[key].includes(value)) {
            this.state.arch[key] = [...this.state.arch[key], value];
        }
    }

    // ── Undo / Redo ────────────────────────────────────
    _pushUndo() {
        this._undoStack.push(JSON.stringify(this.state.arch));
        if (this._undoStack.length > 50) this._undoStack.shift();
        this._redoStack = [];
    }
    undo() {
        if (!this._undoStack.length) return;
        this._redoStack.push(JSON.stringify(this.state.arch));
        this.state.arch = JSON.parse(this._undoStack.pop());
    }
    redo() {
        if (!this._redoStack.length) return;
        this._undoStack.push(JSON.stringify(this.state.arch));
        this.state.arch = JSON.parse(this._redoStack.pop());
    }

    // ── Drag & Drop Handlers ───────────────────────────
    onPaletteDrag(ev, component) {
        ev.dataTransfer.setData('text/plain', JSON.stringify(component));
        ev.dataTransfer.effectAllowed = 'copy';
        ev.currentTarget.classList.add('ls-vb-dragging');
    }
    onPaletteDragEnd(ev) {
        ev.currentTarget.classList.remove('ls-vb-dragging');
    }

    onFieldPaletteDrag(ev, fieldName) {
        ev.dataTransfer.setData('text/plain', JSON.stringify({ type: 'field', name: fieldName }));
        ev.dataTransfer.effectAllowed = 'copy';
        ev.currentTarget.classList.add('ls-vb-dragging');
    }
    onFieldPaletteDragEnd(ev) {
        ev.currentTarget.classList.remove('ls-vb-dragging');
    }

    onDragOver(ev) {
        ev.preventDefault();
        ev.dataTransfer.dropEffect = 'copy';
        const el = ev.currentTarget;
        if (el && el.classList) {
            el.classList.add('drag-over');
        }
    }

    onDragLeave(ev) {
        const el = ev.currentTarget;
        if (el && el.classList) {
            el.classList.remove('drag-over');
        }
    }

    onFormFieldDrag(ev, fldName, grpIdx, colIdx, fldIdx) {
        ev.dataTransfer.setData('text/plain', JSON.stringify({
            type: 'move_field', name: fldName, grpIdx, colIdx, fldIdx
        }));
        ev.dataTransfer.effectAllowed = 'move';
        ev.currentTarget.classList.add('ls-vb-dragging');
    }
    onFormFieldDragEnd(ev) {
        ev.currentTarget.classList.remove('ls-vb-dragging');
    }

    onFormFieldDragTab(ev, tabName, fieldName, grpIdx, colIdx, fldIdx) {
        ev.dataTransfer.setData('text/plain', JSON.stringify({
            type: 'move_field_tab', name: fieldName, tabName, grpIdx, colIdx, fldIdx
        }));
        ev.dataTransfer.effectAllowed = 'move';
        ev.currentTarget.classList.add('ls-vb-dragging');
    }

    onDropFormCol(ev, grpIndex, colIndex, targetFldIndex = null) {
        ev.preventDefault();
        ev.stopPropagation();
        this.onDragLeave(ev);
        const dataStr = ev.dataTransfer.getData('text/plain');
        if (!dataStr) return;
        try {
            const data = JSON.parse(dataStr);
            if (data.type === 'move_field') {
                // Intra/inter-column move: remove from source first, then insert at target
                this._pushUndo();
                this._removeFieldAt(data.grpIdx, data.colIdx, data.fldIdx);
                // Adjust target index if moving within same column
                let adjIdx = targetFldIndex;
                if (grpIndex === data.grpIdx && colIndex === data.colIdx && adjIdx !== null && data.fldIdx < adjIdx) {
                    adjIdx--;
                }
                this._insertFieldAt(data.name, grpIndex, colIndex, adjIdx);
                this.state.arch = { ...this.state.arch };
                this.selectField(data.name);
                return;
            }
            const fieldName = data.name;
            if (fieldName) {
                this._pushUndo();
                this.addFieldToFormCol(fieldName, grpIndex, colIndex, targetFldIndex);
            }
        } catch(e) {}
    }

    onDropFormTabCol(ev, tabName, grpIndex, colIndex, targetFldIndex = null) {
        ev.preventDefault();
        ev.stopPropagation();
        this.onDragLeave(ev);
        const dataStr = ev.dataTransfer.getData('text/plain');
        if (!dataStr) return;
        try {
            const data = JSON.parse(dataStr);
            const fieldName = data.name || (data.type === 'field' ? data.name : null);
            if (fieldName) {
                this.addFieldToFormTabCol(fieldName, tabName, grpIndex, colIndex, targetFldIndex);
            }
        } catch(e) {}
    }

    onDropFormLayout(ev) {
        ev.preventDefault();
        ev.stopPropagation();
        this.onDragLeave(ev);
        const dataStr = ev.dataTransfer.getData('text/plain');
        if (!dataStr) return;
        try {
            const data = JSON.parse(dataStr);
            if (data.type === 'group') {
                this.state.arch.groups = this.state.arch.groups || [];
                this.state.arch.groups.push({ columns: [[], []] });
                this.state.arch = { ...this.state.arch };
            } else if (data.type === 'tab') {
                this.state.arch.tabs = this.state.arch.tabs || [];
                const newTabName = 'new_tab_' + Date.now();
                this.state.arch.tabs.push({ name: newTabName, label: 'New Tab' });
                if (this.state.arch.tabs.length === 1) {
                    this.state.formActiveTab = newTabName;
                }
                this.state.arch = { ...this.state.arch };
                if (this.state.arch.tabs.length === 1) {
                    this.state.formActiveTab = this.state.arch.tabs[0].name;
                }
            } else if (data.type === 'statusbar') {
                this.state.arch.statusbar = '1';
                this.state.arch = { ...this.state.arch };
            } else if (data.type === 'chatter') {
                this.state.arch.chatter = '1';
                this.state.arch = { ...this.state.arch };
            } else if (data.type === 'stat_button') {
                this.state.arch.stat_buttons = this.state.arch.stat_buttons || [];
                this.state.arch.stat_buttons.push({ name: 'stat_' + Date.now() });
                this.state.arch = { ...this.state.arch };
            } else if (data.type === 'separator') {
                this.state.arch.groups = this.state.arch.groups || [];
                this.state.arch.groups.push({ columns: [['separator_' + Date.now()], []] });
                this.state.arch = { ...this.state.arch };
            } else if (data.type === 'field' || (data.name && !data.id)) {
                this.state.arch.groups = this.state.arch.groups || [];
                this.state.arch.groups.push({ columns: [[data.name], []] });
                this.removeSelectedFieldByName(data.name);
                this.selectField(data.name);
                this.state.arch = { ...this.state.arch };
            }
        } catch(e) {}
    }

    removeStatButton(index) {
        if (!this.state.arch.stat_buttons) return;
        this.state.arch.stat_buttons.splice(index, 1);
        this.state.arch = { ...this.state.arch };
    }

    onDropFormTabLayout(ev) {
        ev.preventDefault();
        ev.stopPropagation();
        this.onDragLeave(ev);
        if (!this.state.formActiveTab) return;
        const tab = this.state.arch.tabs.find(t => t.name === this.state.formActiveTab);
        if (!tab) return;
        
        const dataStr = ev.dataTransfer.getData('text/plain');
        if (!dataStr) return;
        try {
            const data = JSON.parse(dataStr);
            if (data.type === 'group') {
                tab.groups = tab.groups || [];
                tab.groups.push({ columns: [[], []] });
                this.state.arch = { ...this.state.arch };
            } else if (data.type === 'field' || (data.name && !data.id)) {
                tab.groups = tab.groups || [];
                tab.groups.push({ columns: [[data.name], []] });
                this.removeSelectedFieldByName(data.name);
                this.selectField(data.name);
                this.state.arch = { ...this.state.arch };
            } else if (data.type === 'tab') {
                this.state.arch.tabs = this.state.arch.tabs || [];
                const newTabName = 'new_tab_' + Date.now();
                this.state.arch.tabs.push({ name: newTabName, label: 'New Tab' });
                this.state.formActiveTab = newTabName;
                this.state.arch = { ...this.state.arch };
            }
        } catch(e) {}
    }

    _removeFieldAt(grpIdx, colIdx, fldIdx) {
        if (this.state.arch.groups && this.state.arch.groups[grpIdx]) {
            const col = this.state.arch.groups[grpIdx].columns?.[colIdx];
            if (col && fldIdx >= 0 && fldIdx < col.length) col.splice(fldIdx, 1);
        }
    }
    _insertFieldAt(fieldName, grpIdx, colIdx, fldIdx) {
        if (this.state.arch.groups && this.state.arch.groups[grpIdx]) {
            const col = this.state.arch.groups[grpIdx].columns?.[colIdx];
            if (col) {
                if (fldIdx !== null && fldIdx >= 0) col.splice(fldIdx, 0, fieldName);
                else col.push(fieldName);
            }
        }
    }

    addFieldToFormCol(fieldName, grpIndex, colIndex, targetFldIndex = null) {
        this.removeSelectedFieldByName(fieldName);
        
        if (this.state.arch.groups && this.state.arch.groups[grpIndex]) {
            const grp = this.state.arch.groups[grpIndex];
            if (grp.columns && grp.columns[colIndex]) {
                if (targetFldIndex !== null && targetFldIndex >= 0) {
                    grp.columns[colIndex].splice(targetFldIndex, 0, fieldName);
                } else {
                    grp.columns[colIndex].push(fieldName);
                }
                this.state.arch = { ...this.state.arch };
            }
        }
        this.selectField(fieldName);
    }

    addFieldToFormTabCol(fieldName, tabName, grpIndex, colIndex, targetFldIndex = null) {
        this.removeSelectedFieldByName(fieldName);
        
        if (this.state.arch.tabs) {
            const tab = this.state.arch.tabs.find(t => t.name === tabName);
            if (tab && tab.groups && tab.groups[grpIndex]) {
                const grp = tab.groups[grpIndex];
                if (grp.columns && grp.columns[colIndex]) {
                    if (targetFldIndex !== null && targetFldIndex >= 0) {
                        grp.columns[colIndex].splice(targetFldIndex, 0, fieldName);
                    } else {
                        grp.columns[colIndex].push(fieldName);
                    }
                    this.state.arch = { ...this.state.arch };
                }
            }
        }
        this.selectField(fieldName);
    }

    removeSelectedFieldByName(fn) {
        if (this.state.activeTab === 'form') {
            if (this.state.arch.groups) {
                for (let g = 0; g < this.state.arch.groups.length; g++) {
                    const grp = this.state.arch.groups[g];
                    for (let c = 0; c < (grp.columns || []).length; c++) {
                        const col = grp.columns[c];
                        const idx = col.findIndex(f => (typeof f === 'string' ? f : f.name) === fn);
                        if (idx !== -1) col.splice(idx, 1);
                    }
                }
            }
            if (this.state.arch.tabs) {
                for (let t = 0; t < this.state.arch.tabs.length; t++) {
                    const tab = this.state.arch.tabs[t];
                    if (tab.groups) {
                        for (let g = 0; g < tab.groups.length; g++) {
                            const grp = tab.groups[g];
                            for (let c = 0; c < (grp.columns || []).length; c++) {
                                const col = grp.columns[c];
                                const idx = col.findIndex(f => (typeof f === 'string' ? f : f.name) === fn);
                                if (idx !== -1) col.splice(idx, 1);
                            }
                        }
                    }
                }
            }
        }
    }

    // ── Form Layout Controls ───────────────────────────
    selectTab(index) {
        this.state.selectedTab = index;
        this.state.selectedField = null;
        this.state.selectedGroup = null;
        if (this.state.arch.tabs[index]) {
            this.state.formActiveTab = this.state.arch.tabs[index].name;
        }
    }

    selectGroup(index) {
        this.state.selectedGroup = index;
        this.state.selectedField = null;
        this.state.selectedTab = null;
    }

    moveTab(index, dir) {
        if (!this.state.arch.tabs) return;
        const target = index + dir;
        if (target < 0 || target >= this.state.arch.tabs.length) return;
        const tabs = this.state.arch.tabs;
        const temp = tabs[index];
        tabs[index] = tabs[target];
        tabs[target] = temp;
        this.state.selectedTab = target;
        this.state.arch = { ...this.state.arch };
    }

    removeTab(index) {
        if (!this.state.arch.tabs) return;
        this.state.arch.tabs.splice(index, 1);
        this.state.selectedTab = null;
        this.state.arch = { ...this.state.arch };
    }

    setGroupColumns(grpIndex, colCount) {
        colCount = parseInt(colCount) || 2;
        this._pushUndo();
        const grp = this.state.arch.groups?.[grpIndex];
        if (!grp) return;
        const current = grp.columns || [];
        while (current.length < colCount) current.push([]);
        while (current.length > colCount) {
            const removed = current.pop();
            if (removed.length && current.length > 0) current[current.length - 1].push(...removed);
        }
        grp.columns = current;
        this.state.arch = { ...this.state.arch };
    }

    moveGroup(index, dir) {
        if (!this.state.arch.groups) return;
        const target = index + dir;
        if (target < 0 || target >= this.state.arch.groups.length) return;
        this._pushUndo();
        const groups = this.state.arch.groups;
        const temp = groups[index];
        groups[index] = groups[target];
        groups[target] = temp;
        this.state.arch = { ...this.state.arch };
    }

    removeGroup(index) {
        if (!this.state.arch.groups) return;
        if (confirm("Remove this group and all its fields?")) {
            this.state.arch.groups.splice(index, 1);
            this.state.arch = { ...this.state.arch };
        }
    }

    moveTabGroup(tabName, index, dir) {
        const tab = (this.state.arch.tabs || []).find(t => t.name === tabName);
        if (!tab || !tab.groups) return;
        const target = index + dir;
        if (target < 0 || target >= tab.groups.length) return;
        const temp = tab.groups[index];
        tab.groups[index] = tab.groups[target];
        tab.groups[target] = temp;
        this.state.arch = { ...this.state.arch };
    }

    removeTabGroup(tabName, index) {
        const tab = (this.state.arch.tabs || []).find(t => t.name === tabName);
        if (!tab || !tab.groups) return;
        if (confirm("Remove this group and all its fields?")) {
            tab.groups.splice(index, 1);
            this.state.arch = { ...this.state.arch };
        }
    }

    // ── Tab Type Management ───────────────────────────
    setTabType(index, type) {
        const tab = this.state.arch.tabs[index];
        if (!tab) return;
        tab.type = type;
        if (type === 'one2many') {
            tab.field = tab.field || '';
            tab.editable = tab.editable || 'bottom';
            tab.tree_fields = tab.tree_fields || [];
            delete tab.groups;
        } else if (type === 'field') {
            tab.field = tab.field || '';
            delete tab.groups;
            delete tab.tree_fields;
            delete tab.editable;
        } else {
            // layout (default)
            tab.groups = tab.groups || [];
            delete tab.field;
            delete tab.tree_fields;
            delete tab.editable;
            delete tab.type;
        }
        this.state.arch = { ...this.state.arch };
    }

    setTabField(index, fieldName) {
        const tab = this.state.arch.tabs[index];
        if (!tab) return;
        tab.field = fieldName;
        // Auto-populate tree_fields for one2many from child model if empty
        if (tab.type === 'one2many' && (!tab.tree_fields || tab.tree_fields.length === 0)) {
            const f = this.state.fields[fieldName];
            if (f && f.relation_fields) {
                tab.tree_fields = Object.keys(f.relation_fields).slice(0, 5);
            }
        }
        this.state.arch = { ...this.state.arch };
    }

    addTabTreeField(index, fieldName) {
        const tab = this.state.arch.tabs[index];
        if (!tab || !fieldName) return;
        if (!tab.tree_fields) tab.tree_fields = [];
        if (!tab.tree_fields.includes(fieldName)) {
            tab.tree_fields.push(fieldName);
            this.state.arch = { ...this.state.arch };
        }
    }

    removeTabTreeField(index, fieldIndex) {
        const tab = this.state.arch.tabs[index];
        if (!tab || !tab.tree_fields) return;
        tab.tree_fields.splice(fieldIndex, 1);
        this.state.arch = { ...this.state.arch };
    }

    getTabChildFields(tabIndex) {
        const tab = this.state.arch.tabs?.[tabIndex];
        if (!tab || !tab.field) return [];
        const f = this.state.fields[tab.field];
        if (!f || !f.relation_fields) return [];
        return Object.entries(f.relation_fields).map(([name, meta]) => ({
            name,
            string: meta.string || name,
            type: meta.type || 'char',
        }));
    }

    // ── Form Field Config ──────────────────────────────
    get widgetOptions() {
        if (!this.state.selectedField) return [['', 'Default']];
        const type = this.fieldType(this.state.selectedField);
        const map = {
            char: [['','Default'],['email','Email'],['phone','Phone'],['url','URL'],['image','Image'],['color','Color Picker']],
            text: [['','Default'],['html','Rich Text (HTML)']],
            integer: [['','Default'],['progressbar','Progress Bar'],['handle','Drag Handle']],
            float: [['','Default'],['float_time','Duration (H:M)'],['progressbar','Progress Bar'],['percentage','Percentage']],
            monetary: [['','Default (Monetary)']],
            boolean: [['','Default (Checkbox)'],['toggle','Toggle Switch']],
            date: [['','Default'],['remaining_days','Remaining Days']],
            datetime: [['','Default'],['remaining_days','Remaining Days']],
            selection: [['','Default'],['badge','Badge'],['radio','Radio'],['priority','Priority Stars'],['statusbar','Status Bar']],
            many2one: [['','Default'],['many2one_avatar','Avatar']],
            one2many: [['','Default (Inline List)']],
            many2many: [['','Default'],['many2many_tags','Tags'],['many2many_checkboxes','Checkboxes']],
            html: [['','Default (HTML)']],
        };
        return map[type] || [['','Default']];
    }

    setFormFieldConfig(fieldName, key, value) {
        if (!this.state.arch.field_config) this.state.arch.field_config = {};
        if (!this.state.arch.field_config[fieldName]) this.state.arch.field_config[fieldName] = {};
        if (value === '' || value === false || value === null || value === undefined) {
            delete this.state.arch.field_config[fieldName][key];
            if (Object.keys(this.state.arch.field_config[fieldName]).length === 0) {
                delete this.state.arch.field_config[fieldName];
            }
        } else {
            this.state.arch.field_config[fieldName][key] = value;
        }
        this.state.arch = { ...this.state.arch };
    }

    getFormFieldConfig(fieldName, key) {
        return this.state.arch?.field_config?.[fieldName]?.[key] ?? '';
    }

    setGroupString(grpIndex, value) {
        if (this.state.arch.groups && this.state.arch.groups[grpIndex]) {
            this.state.arch.groups[grpIndex].string = value || null;
            this.state.arch = { ...this.state.arch };
        }
    }

    // ── Helper methods ─────────────────────────────────
    fieldLabel(fieldName) {
        if (fieldName && fieldName.startsWith('separator_')) return 'Separator';
        const f = this.state.fields[fieldName];
        return f?.string || fieldName;
    }

    fieldType(fieldName) {
        if (fieldName && fieldName.startsWith('separator_')) return 'separator';
        return this.state.fields[fieldName]?.type || 'char';
    }

    fieldIcon(type) {
        const map = {
            char: 'type', text: 'align-left', integer: 'hash', float: 'hash',
            monetary: 'dollar-sign', boolean: 'toggle-left', date: 'calendar',
            datetime: 'clock', selection: 'list', many2one: 'link',
            one2many: 'git-branch', many2many: 'tags', html: 'code', separator: 'minus'
        };
        return map[type] || 'box';
    }

    sampleValue(fieldName, rowIndex) {
        if (fieldName && fieldName.startsWith('separator_')) return markup(`<hr style="margin: 4px 0; padding: 0; border: 0; border-top: 2px dashed #d1d5db;"/>`);
        const f = this.state.fields[fieldName];
        if (!f) return fieldName;
        const type = f.type;
        const samples = {
            char: ['Laptop Pro 15', 'Monitor 4K 27"', 'Keyboard Mech', 'Mouse Wireless'],
            text: ['Description...', 'Notes here...', 'Details...', 'Content...'],
            integer: [42, 128, 7, 365],
            float: [24.50, 9.75, 3.25, 1.05],
            monetary: ['Rp 24.000.000', 'Rp 9.000.000', 'Rp 3.750.000', 'Rp 1.050.000'],
            boolean: [true, false, true, false],
            date: ['2026-06-01', '2026-06-15', '2026-07-01', '2026-07-30'],
            datetime: ['2026-06-01 08:00', '2026-06-15 14:30', '2026-07-01 09:00', '2026-07-30 16:00'],
            selection: ['New', 'In Progress', 'Done', 'Cancelled'],
            many2one: ['Project Alpha', 'Beta Corp', 'Gamma Inc', 'Delta LLC'],
            many2many: ['Tag A, Tag B', 'Tag C', 'Tag A, Tag D', 'Tag B, Tag C'],
        };
        const arr = samples[type] || samples.char;
        const idx = ((rowIndex || 1) - 1) % arr.length;
        const val = arr[idx];
        if (type === 'monetary') return val;
        if (type === 'many2one') return markup(`<span class="ls-vb-sample-m2o">${val}</span>`);
        if (type === 'selection') return markup(`<span class="ls-vb-sample-badge">${val}</span>`);
        if (type === 'boolean') return markup(`<span class="ls-vb-sample-check ${val ? 'checked' : ''}"></span>`);
        if (type === 'many2many') return markup(`<span class="ls-vb-sample-tags">${val.split(',').map(t => `<span class="ls-vb-sample-tag">${t.trim()}</span>`).join('')}</span>`);
        return String(val);
    }

    async switchTab(tabId) {
        this.state.activeTab = tabId;
        this.state.selectedField = null;
        this.state.showXml = false;
        if (this.state.selectedModel) {
            await this.loadCurrentView();
        }
    }

    onPaletteDrag(ev, component) {
        ev.dataTransfer.setData('text/plain', JSON.stringify(component));
    }

    // ── XML preview & actions ──────────────────────────
    async viewXml() {
        try {
            const data = await RPC.call('/api/view-builder/preview-xml', {
                type: this.state.activeTab,
                arch: this.state.arch,
            });
            this.state.xmlPreview = data.xml || '';
            this.state.showXml = !this.state.showXml || this.state.xmlPreview;
        } catch (e) {
            this.showToast('Failed to generate XML', 'error');
        }
    }

    copyXml() {
        navigator.clipboard.writeText(this.state.xmlPreview);
        this.showToast('XML copied to clipboard', 'success');
    }

    async resetView() {
        this.initDefaultArch();
        this.state.selectedField = null;
        this.state.showXml = false;
        this.showToast('View reset to defaults', 'success');
    }

    async saveView() {
        if (!this.state.selectedModel) return;
        try {
            await RPC.call('/api/view-builder/save-view', {
                model: this.state.selectedModel,
                type: this.state.activeTab,
                arch: this.state.arch,
            });
            this.showToast('View saved successfully!', 'success');
        } catch (e) {
            this.showToast('Failed to save view: ' + e.message, 'error');
        }
    }

    async exportToCode() {
        if (!this.state.selectedModel) return;
        try {
            const res = await RPC.call('/api/view-builder/export-code', {
                model: this.state.selectedModel,
                type: this.state.activeTab,
                arch: this.state.arch,
            });
            this.state.codePreview = res.code || '// No code generated';
            this.state.showCode = true;
        } catch (e) {
            this.showToast('Failed to export code: ' + e.message, 'error');
        }
    }

    copyCode() {
        if (navigator.clipboard && this.state.codePreview) {
            navigator.clipboard.writeText(this.state.codePreview).then(() => {
                this.showToast('Code copied to clipboard!', 'success');
            });
        }
    }

    showToast(msg, type = '') {
        this.state.toast = msg;
        this.state.toastType = type;
        setTimeout(() => { this.state.toast = ''; }, 3000);
    }
}

window.ViewBuilderView = ViewBuilderView;
})();


/* --- [FILE: js/pages/custom/owl-my-custom-page.js] --- */
// ══════════════════════════════════════════════════════════════
//  MyCustomPage — Owl Component
//  Halaman kustom terintegrasi dengan backend AdvSoft.
//  Fitur: CRUD items, stats, search/filter, sorting, modals.
// ══════════════════════════════════════════════════════════════
(function () {
    const { Component, useState, onMounted } = owl;
    const RPC = window.AdvSoftRPC;

    // Warna avatar berdasarkan nama (deterministik)
    const AVATAR_COLORS = [
        '#7c3aed', '#0d9488', '#dc2626', '#d97706',
        '#2563eb', '#db2777', '#059669', '#7c3aed',
    ];

    function avatarColor(name = '') {
        let hash = 0;
        for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
        return AVATAR_COLORS[Math.abs(hash) % AVATAR_COLORS.length];
    }

    class MyCustomPage extends Component {
        static template = window.MY_CUSTOM_PAGE_TPL;

        setup() {
            this.state = useState({
                // Data utama
                items: [],
                stats: null,
                loading: false,
                error: null,

                // Search & filter
                searchQuery: '',
                filterStatus: '',
                sortField: 'created_at',
                sortDir: 'desc',

                // Modal buat/edit
                modal: {
                    open: false,
                    mode: 'create', // 'create' | 'edit'
                    editId: null,
                    form: { name: '', description: '', status: 'active' },
                    saving: false,
                    error: null,
                },

                // Modal detail
                detail: {
                    open: false,
                    item: null,
                },

                // Konfirmasi hapus
                deleteConfirm: {
                    open: false,
                    item: null,
                    deleting: false,
                },
            });

            onMounted(() => this.fetchData());
        }

        // ── Data Layer ──────────────────────────────────

        async fetchData() {
            this.state.loading = true;
            this.state.error = null;

            try {
                const res = await RPC.call('/api/custom-page/items', {});
                const items = (res.items || []).map(item => ({
                    ...item,
                    color: avatarColor(item.name),
                }));
                this.state.items = items;
                this.state.stats = res.stats || this._computeStats(items);
            } catch (e) {
                this.state.error = e.message || 'Gagal memuat data dari server.';
            } finally {
                this.state.loading = false;
            }
        }

        _computeStats(items) {
            return {
                total:    items.length,
                active:   items.filter(i => i.status === 'active').length,
                pending:  items.filter(i => i.status === 'pending').length,
                inactive: items.filter(i => i.status === 'inactive').length,
            };
        }

        // ── Computed: filtered + sorted items ──────────

        get filteredItems() {
            let list = this.state.items;

            // Search
            if (this.state.searchQuery) {
                const q = this.state.searchQuery.toLowerCase();
                list = list.filter(i =>
                    i.name.toLowerCase().includes(q) ||
                    (i.description || '').toLowerCase().includes(q)
                );
            }

            // Filter status
            if (this.state.filterStatus) {
                list = list.filter(i => i.status === this.state.filterStatus);
            }

            // Sort
            const field = this.state.sortField;
            const dir = this.state.sortDir === 'asc' ? 1 : -1;
            list = [...list].sort((a, b) => {
                const va = a[field] || '';
                const vb = b[field] || '';
                return va < vb ? -dir : va > vb ? dir : 0;
            });

            return list;
        }

        // ── Search / Filter / Sort ──────────────────────

        onSearch() {
            // Reaktif via t-model, tidak perlu action tambahan
        }

        onFilter() {
            // Reaktif via t-model
        }

        clearFilters() {
            this.state.searchQuery = '';
            this.state.filterStatus = '';
        }

        sortBy(field) {
            if (this.state.sortField === field) {
                this.state.sortDir = this.state.sortDir === 'asc' ? 'desc' : 'asc';
            } else {
                this.state.sortField = field;
                this.state.sortDir = 'asc';
            }
        }

        // ── Modal: Create ────────────────────────────────

        openCreateModal() {
            this.state.modal = {
                open: true,
                mode: 'create',
                editId: null,
                form: { name: '', description: '', status: 'active' },
                saving: false,
                error: null,
            };
        }

        // ── Modal: Edit ──────────────────────────────────

        openEdit(item) {
            this.state.modal = {
                open: true,
                mode: 'edit',
                editId: item.id,
                form: { name: item.name, description: item.description || '', status: item.status },
                saving: false,
                error: null,
            };
        }

        // ── Modal: Save ──────────────────────────────────

        async saveModal() {
            const form = this.state.modal.form;

            if (!form.name.trim()) {
                this.state.modal.error = 'Nama tidak boleh kosong.';
                return;
            }

            this.state.modal.saving = true;
            this.state.modal.error = null;

            try {
                if (this.state.modal.mode === 'create') {
                    await RPC.call('/api/custom-page/items/create', form);
                } else {
                    await RPC.call('/api/custom-page/items/update', {
                        id: this.state.modal.editId,
                        ...form,
                    });
                }
                this.closeModal();
                await this.fetchData();
            } catch (e) {
                this.state.modal.error = e.message || 'Gagal menyimpan data.';
            } finally {
                this.state.modal.saving = false;
            }
        }

        closeModal() {
            this.state.modal.open = false;
        }

        // ── Detail view ──────────────────────────────────

        openDetail(item) {
            this.state.detail = { open: true, item };
        }

        closeDetail() {
            this.state.detail.open = false;
        }

        // ── Delete ────────────────────────────────────────

        confirmDelete(item) {
            this.state.deleteConfirm = { open: true, item, deleting: false };
        }

        cancelDelete() {
            this.state.deleteConfirm.open = false;
        }

        async deleteItem() {
            this.state.deleteConfirm.deleting = true;
            try {
                await RPC.call('/api/custom-page/items/delete', {
                    id: this.state.deleteConfirm.item.id,
                });
                this.state.deleteConfirm.open = false;
                await this.fetchData();
            } catch (e) {
                console.error('Delete error:', e);
                this.state.deleteConfirm.deleting = false;
            }
        }

        // ── Formatters ────────────────────────────────────

        statusLabel(status) {
            return { active: 'Aktif', pending: 'Tertunda', inactive: 'Nonaktif' }[status] || status;
        }

        formatDate(dateStr) {
            if (!dateStr) return '—';
            const d = new Date(dateStr);
            if (isNaN(d)) return dateStr;
            return d.toLocaleDateString('id-ID', {
                day: '2-digit', month: 'short', year: 'numeric',
            });
        }
    }

    // Daftarkan ke AdvSoftPageRegistry
    window.AdvSoftPageRegistry = window.AdvSoftPageRegistry || {};
    window.AdvSoftPageRegistry['my_custom_page'] = MyCustomPage;
})();


/* --- [FILE: js/core/owl-root.js] --- */
// ══════════════════════════════════════════════════════════════════
//  WebClient — Odoo-style menu-driven SPA with multi-view support
//  Components: AppSwitcher, NavBar, SubMenu, Breadcrumb, WebClient
(function () {
    const { Component, useState, useRef, onWillStart, onMounted, onError } = owl;
    const RPC = window.AdvSoftRPC;

    // View type icons (SVG inline)
    const VIEW_ICONS = {
        list: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>',
        kanban: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>',
        calendar: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>',
        graph: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>',
        pivot: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="3" y1="15" x2="21" y2="15"/><line x1="9" y1="3" x2="9" y2="21"/></svg>',
        spreadsheet: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="3" y1="15" x2="21" y2="15"/><line x1="9" y1="3" x2="9" y2="21"/><line x1="15" y1="3" x2="15" y2="21"/></svg>',
    };

    const VIEW_LABELS = {
        list: 'List', kanban: 'Kanban', calendar: 'Calendar',
        graph: 'Graph', pivot: 'Pivot', form: 'Form', spreadsheet: 'Spreadsheet',
    };

    // Global Page Registry
    window.AdvSoftPageRegistry = Object.assign({
        'security_overview': window.SecurityOverview,
        'security_access': window.AccessRights,
        'security_rules': window.RecordRules,
        'security_groups': window.GroupsView,
        'security_users': window.UsersView,
        'menu_editor': window.MenuEditorView,
        'view_builder': window.ViewBuilderView,
        'accounting_reports': window.AccountingReports,
    }, window.AdvSoftPageRegistry || {});
    window.AdvsoftPageRegistry = window.AdvSoftPageRegistry;
    window.LarasoftPageRegistry = window.AdvSoftPageRegistry;

    window.registerCustomPage = function(viewId, componentClass) {
        window.AdvSoftPageRegistry[viewId] = componentClass;
    };

    // ── App Theme Palette Helper for Odoo Enterprise Look ─
    function getAppVisuals(app) {
        const name = (app.name || '').toLowerCase();
        const icon = (app.web_icon || app.icon || '').toLowerCase();
        
        if (name.includes('project') || icon.includes('briefcase') || icon.includes('layers')) {
            return {
                gradient: 'linear-gradient(135deg, #8B5CF6 0%, #6D28D9 100%)',
                glow: 'rgba(139, 92, 246, 0.45)',
                icon: 'layers',
            };
        }
        if (name.includes('account') || name.includes('invoic') || name.includes('finance') || icon.includes('book')) {
            return {
                gradient: 'linear-gradient(135deg, #10B981 0%, #047857 100%)',
                glow: 'rgba(16, 185, 129, 0.45)',
                icon: 'book-open',
            };
        }
        if (name.includes('showcase') || icon.includes('eye')) {
            return {
                gradient: 'linear-gradient(135deg, #06B6D4 0%, #0284C7 100%)',
                glow: 'rgba(6, 182, 212, 0.45)',
                icon: 'sparkles',
            };
        }
        if (name.includes('security') || name.includes('user') || icon.includes('shield') || icon.includes('lock')) {
            return {
                gradient: 'linear-gradient(135deg, #F43F5E 0%, #BE123C 100%)',
                glow: 'rgba(244, 63, 94, 0.45)',
                icon: 'shield-check',
            };
        }
        if (name.includes('spreadsheet') || icon.includes('sheet') || icon.includes('table')) {
            return {
                gradient: 'linear-gradient(135deg, #059669 0%, #064E3B 100%)',
                glow: 'rgba(5, 150, 105, 0.45)',
                icon: 'file-spreadsheet',
            };
        }
        if (name.includes('setting') || name.includes('admin') || icon.includes('settings')) {
            return {
                gradient: 'linear-gradient(135deg, #6366F1 0%, #4338CA 100%)',
                glow: 'rgba(99, 102, 241, 0.45)',
                icon: 'settings',
            };
        }

        if (app.web_icon_color) {
            return {
                gradient: `linear-gradient(135deg, ${app.web_icon_color} 0%, #4C1D95 100%)`,
                glow: app.web_icon_color + '77',
                icon: app.web_icon || app.icon || 'box',
            };
        }

        return {
            gradient: 'linear-gradient(135deg, #8B5CF6 0%, #6D28D9 100%)',
            glow: 'rgba(139, 92, 246, 0.45)',
            icon: app.web_icon || app.icon || 'box',
        };
    }

    // ── AppSwitcher Component ────────────────────────────
    class AppSwitcher extends Component {
        static template = window.TEMPLATES.AppSwitcher;
        static props = {
            apps: { type: Array },
            onAppClick: { type: Function },
            onMenuClick: { type: Function, optional: true },
        };

        setup() {
            this.state = useState({
                searchQuery: '',
            });
            this.searchInputRef = useRef('searchInput');

            this._onKeyDown = (ev) => {
                const tag = ev.target.tagName;
                if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') {
                    if (ev.key === 'Escape') {
                        this.state.searchQuery = '';
                        this.searchInputRef.el?.blur();
                    } else if (ev.key === 'Enter') {
                        this.openSelected();
                    }
                    return;
                }
                // If user pressed '/' or starts typing an alphanumeric key on home screen, focus search
                if (ev.key === '/' || (ev.key.length === 1 && !ev.ctrlKey && !ev.metaKey && !ev.altKey)) {
                    if (ev.key === '/') ev.preventDefault();
                    if (this.searchInputRef.el) {
                        this.searchInputRef.el.focus();
                    }
                }
            };

            onMounted(() => {
                window.addEventListener('keydown', this._onKeyDown);
                setTimeout(() => this.searchInputRef.el?.focus(), 80);
            });

            owl.onWillDestroy(() => {
                window.removeEventListener('keydown', this._onKeyDown);
            });
        }

        get filteredApps() {
            const q = this.state.searchQuery.trim().toLowerCase();
            if (!q) return this.props.apps || [];
            return (this.props.apps || []).filter(app => {
                return (app.name || '').toLowerCase().includes(q);
            });
        }

        get matchingMenuItems() {
            const q = this.state.searchQuery.trim().toLowerCase();
            if (!q) return [];
            const results = [];
            const collect = (items, path) => {
                for (const item of items) {
                    const currentPath = path ? `${path} / ${item.name}` : item.name;
                    if ((item.name || '').toLowerCase().includes(q)) {
                        results.push({ ...item, fullPath: currentPath });
                    }
                    if (item.children && item.children.length) {
                        collect(item.children, currentPath);
                    }
                }
            };
            for (const app of this.props.apps || []) {
                if (app.children && app.children.length) {
                    collect(app.children, app.name);
                }
            }
            return results.slice(0, 12);
        }

        getAppVisuals(app) {
            return getAppVisuals(app);
        }

        onAppClick(app) {
            this.props.onAppClick(app);
        }

        onMenuItemClick(item) {
            if (this.props.onMenuClick) {
                this.props.onMenuClick(item);
            }
        }

        openSelected() {
            const apps = this.filteredApps;
            if (apps.length > 0) {
                this.onAppClick(apps[0]);
            } else if (this.matchingMenuItems.length > 0) {
                this.onMenuItemClick(this.matchingMenuItems[0]);
            }
        }

        clearSearch() {
            this.state.searchQuery = '';
            this.searchInputRef.el?.focus();
        }
    }

    // ── NavBar Component (Top Navigation) ───────────────
    class NavBar extends Component {
        static template = window.TEMPLATES.NavBar;
        static props = {
            apps: { type: Array },
            activeAppId: { type: Number, optional: true },
            onAppClick: { type: Function },
            onHome: { type: Function },
            onOpenProfile: { type: Function, optional: true },
            isHome: { type: Boolean, optional: true },
        };

        onAppClick(app) { this.props.onAppClick(app); }
        onProfileClick(ev) {
            if (ev) ev.preventDefault();
            const uid = window.AdvSoftUser?.uid || 1;
            if (this.props.onOpenProfile) {
                this.props.onOpenProfile(uid);
            }
        }
        toggleTheme() {
            if (window.AdvSoftLayout) {
                window.AdvSoftLayout.setTheme(window.AdvSoftLayout.effectiveTheme === 'dark' ? 'light' : 'dark');
            }
        }
        toggleSettings() {
            if (window.AdvSoftLayout) window.AdvSoftLayout.toggleSettings();
        }
        get effectiveTheme() {
            return window.AdvSoftLayout ? window.AdvSoftLayout.effectiveTheme : 'light';
        }
    }

    // ── SubMenu Component (Level 2-3 with dropdowns) ─────
    class SubMenu extends Component {
        static template = window.TEMPLATES.SubMenu;
        static props = {
            items: { type: Array, optional: true },
            activeMenuId: { type: Number, optional: true },
            onMenuClick: { type: Function },
        };

        setup() {
            this.state = useState({ openDropdown: null });
            this._onDocClick = (ev) => {
                if (ev.target.closest('.ls-submenu-dropdown') || ev.target.closest('.ls-submenu-dropdown-toggle')) {
                    return;
                }
                this.state.openDropdown = null;
            };
            onMounted(() => document.addEventListener('click', this._onDocClick));
            owl.onWillDestroy(() => document.removeEventListener('click', this._onDocClick));
        }

        toggleDropdown(id, ev) {
            if (ev) {
                ev.preventDefault();
                ev.stopPropagation();
            }
            this.state.openDropdown = this.state.openDropdown === id ? null : id;
        }

        onMenuClick(item) {
            this.state.openDropdown = null;
            this.props.onMenuClick(item);
        }
    }

    // ── WebClient (Root) ─────────────────────────────────
    class WebClient extends Component {
        static template = window.TEMPLATES.Root;
        static components = {
            AppSwitcher, NavBar, SubMenu,
            ListView: window.ListView,
            FormView: window.FormView,
            KanbanView: window.KanbanView,
            CalendarView: window.CalendarView,
            GraphView: window.GraphView,
            PivotView: window.PivotView,
            SpreadsheetView: window.SpreadsheetView,
        };

        // Get the dynamic component from registry
        get customComponent() {
            return window.AdvSoftPageRegistry[this.state.currentView] || null;
        }

        get isCustomView() {
            return !!window.AdvSoftPageRegistry[this.state.currentView];
        }

        setup() {
            this.state = useState({
                // Menu state
                menus: [],
                apps: [],
                activeAppId: null,
                activeMenuId: null,

                // View state
                currentView: 'home',
                actionView: 'list',
                currentModel: null,
                actionTitle: '',
                actionDomain: [],
                actionContext: {},

                // Action data
                currentAction: null,
                searchViewDef: {},
                listViewDef: {},
                formViewDef: {},
                kanbanViewDef: {},
                calendarViewDef: {},
                graphViewDef: {},
                pivotViewDef: {},
                spreadsheetViewDef: {},

                // Available view modes for current action
                viewModes: ['list', 'form'],

                // Form navigation
                formRecordId: null,
                formIndex: 1,
                formTotal: 0,

                // Shared relation data
                stages: [],
                projects: [],
                tags: [],

                // Breadcrumb stack
                breadcrumbs: [],

                // URL hash
                hash: {},

                // Error state
                clientError: null,

                // Layout / Theme / Device state
                layout: window.AdvSoftLayout ? window.AdvSoftLayout.toState() : {
                    theme: 'light', effectiveTheme: 'light', brandColor: 'purple',
                    density: 'default', device: 'desktop', isMobile: false,
                    isTablet: false, isDesktop: true, settingsOpen: false,
                    mobileMenuOpen: false, brandColors: [],
                },
            });

            this._menuCache = {};
            this._actionCache = {};

            // Sync LayoutService → Owl state
            if (window.AdvSoftLayout) {
                window.AdvSoftLayout.onChange(() => {
                    Object.assign(this.state.layout, window.AdvSoftLayout.toState());
                });
            }

            // Expose security-nav API for menu clicks
            window.__navSecurity = (type) => this.openCustomView(type);
            window.__doAction = (action) => this._executeActionDict(action);

            // Global Error Boundary for Owl Components
            onError(error => {
                console.error("[Owl Error Boundary Caught]", error);
                const cause = error.cause || error;
                if (error.cause) {
                    console.error("[Owl Error Cause]", error.cause);
                }
                this.state.clientError = {
                    message: cause.message || String(cause),
                    stack: cause.stack || '',
                    serverError: cause.serverError || null
                };
            });

            // Global window error catchers
            const handleGlobalError = (event) => {
                if (this.state.clientError) return; // Don't overwrite if already showing
                const err = event.error || event.reason;
                if (err) {
                    this.state.clientError = {
                        message: err.message || String(err),
                        stack: err.stack || '',
                        serverError: err.serverError || null
                    };
                }
            };
            window.addEventListener('error', handleGlobalError);
            window.addEventListener('unhandledrejection', handleGlobalError);

            onWillStart(async () => {
                const menus = await RPC.get('/api/orm/load_menus');
                // PERFORMA: markRaw pada data master
                this.state.menus = menus;
                this.state.apps = menus;

                const [projects, stages, tags] = await Promise.all([
                    RPC.nameSearch('project.project', '', 100).catch(() => []),
                    RPC.nameSearch('project.stage', '', 100).catch(() => []),
                    RPC.nameSearch('project.tag', '', 100).catch(() => []),
                ]);
                this.state.projects = projects || [];
                this.state.stages = stages || [];
                this.state.tags = tags || [];

                this._parseHash();
            });

            onMounted(() => {
                window.addEventListener('hashchange', () => this._parseHash());
            });
        }

        // ── Custom SPA Page Navigation ──────────────
        openCustomView(type, updateHash = true) {
            if (!window.AdvSoftPageRegistry[type]) {
                console.warn('Custom page not found in registry:', type);
                return;
            }
            this.state.currentView = type;
            
            // Try to find which app and menu item has this security_view to highlight the menu
            for (const app of this.state.apps) {
                if (app.security_view === type) {
                    this.state.activeAppId = app.id;
                    this.state.activeMenuId = app.id;
                    break;
                }
                const menuItem = this._findMenuBySecurityView(app.children || [], type);
                if (menuItem) {
                    this.state.activeAppId = app.id;
                    this.state.activeMenuId = menuItem.id;
                    break;
                }
            }
            if (updateHash && type !== 'adianti_page') {
                this._updateHash({ class: this._customViewToClass(type) });
            }
        }

        _findMenuBySecurityView(items, type) {
            for (const item of items) {
                if (item.security_view === type) return item;
                if (item.children) {
                    const found = this._findMenuBySecurityView(item.children, type);
                    if (found) return found;
                }
            }
            return null;
        }

        // ── Error Handling ──────────────────────────────
        clearError() {
            this.state.clientError = null;
        }

        reloadPage() {
            window.location.reload();
        }

        setTheme(theme) {
            if (window.AdvSoftLayout) window.AdvSoftLayout.setTheme(theme);
        }

        closeSettings() {
            if (window.AdvSoftLayout) window.AdvSoftLayout.closeSettings();
        }

        // ── View Mode Switcher ──────────────────────────
        get availableViewModes() {
            const modes = this.state.viewModes.filter(m => m !== 'form');
            return modes.map(type => ({
                type,
                label: VIEW_LABELS[type] || type,
                icon: owl.markup(VIEW_ICONS[type] || VIEW_ICONS.list),
            }));
        }

        switchView(viewType) {
            if (viewType === this.state.actionView) return;
            this.state.actionView = viewType;
            this._updateHash({
                class: this._modelViewToClass(this.state.currentModel, viewType),
            });
        }

        // ── Menu Navigation ──────────────────────────────

        onAppClick(app) {
            this.state.activeAppId = app.id;

            if (app.action_id && app.action) {
                this._executeAction(app.action, app.id);
            } else if (app.security_view) {
                this.onMenuClick(app);
            } else if (app.model) {
                this.onMenuClick(app);
            } else if (app.children && app.children.length > 0) {
                const firstAction = this._findFirstAction(app.children);
                if (firstAction) {
                    this.onMenuClick(firstAction);
                }
            }
        }

        onMenuClick(item) {
            // Security management view (custom SPA pages)
            if (item.security_view) {
                this.openCustomView(item.security_view);
                return;
            }

            // Odoo action dict
            if (item.action_id && item.action) {
                this._executeAction(item.action, item.id);
                return;
            }

            // Simple model+view menu item (e.g. "model=res.users, view=list")
            if (item.model) {
                const viewMode = (item.view || 'list');
                this._executeActionDict({
                    type: 'ir.actions.act_window',
                    res_model: item.model,
                    name: item.name || item.model,
                    view_mode: viewMode + ',form',
                });
                this.state.activeMenuId = item.id;
            }
        }

        goHome() {
            this.state.currentView = 'home';
            this.state.activeAppId = null;
            this.state.activeMenuId = null;
            this.state.currentAction = null;
            this._updateHash({});
        }

        get currentSubMenus() {
            if (!this.state.activeAppId) {
                // If activeAppId is not set, try to find the app from currentModel
                if (this.state.currentModel) {
                    const match = this._findAppForModelOrAction(this.state.currentModel);
                    if (match) {
                        this.state.activeAppId = match.app.id;
                    }
                }
            }
            const app = (this.state.apps || []).find(a => a.id === this.state.activeAppId);
            return app?.children || [];
        }

        _findAppForModelOrAction(model, actionId) {
            if (!this.state.apps || !this.state.apps.length) return null;
            for (const app of this.state.apps) {
                if (app.model === model || (actionId && app.action_id === actionId)) {
                    return { app, menu: app };
                }
                const foundMenu = this._findMenuItem(app.children || [], model, actionId);
                if (foundMenu) {
                    return { app, menu: foundMenu };
                }
            }
            return null;
        }

        _findMenuItem(items, model, actionId) {
            for (const item of items) {
                if (actionId && item.action_id === actionId) return item;
                if (model && item.model === model) return item;
                if (model && item.action && item.action.res_model === model) return item;
                if (item.children && item.children.length) {
                    const found = this._findMenuItem(item.children, model, actionId);
                    if (found) return found;
                }
            }
            return null;
        }

        _findMenuById(items, menuId) {
            for (const item of items) {
                if (item.id === menuId) return item;
                if (item.children && item.children.length) {
                    const found = this._findMenuById(item.children, menuId);
                    if (found) return found;
                }
            }
            return null;
        }

        // ── Action Execution (ActionService) ─────────────

        async _executeAction(actionDef, menuId) {
            this.state.activeMenuId = menuId;

            // Ensure activeAppId is set
            if (menuId) {
                for (const app of this.state.apps) {
                    if (app.id === menuId || this._findMenuById(app.children || [], menuId)) {
                        this.state.activeAppId = app.id;
                        break;
                    }
                }
            }
            if (!this.state.activeAppId && actionDef && actionDef.res_model) {
                const match = this._findAppForModelOrAction(actionDef.res_model, actionDef.id);
                if (match) {
                    this.state.activeAppId = match.app.id;
                    if (!this.state.activeMenuId) this.state.activeMenuId = match.menu.id;
                }
            }

            this.state.currentAction = actionDef;
            this.state.currentModel = actionDef.res_model;
            this.state.actionTitle = actionDef.name;
            try { this.state.actionDomain = actionDef.domain ? (typeof actionDef.domain === 'string' ? JSON.parse(actionDef.domain) : actionDef.domain) : []; } catch (e) { this.state.actionDomain = []; }
            try { this.state.actionContext = actionDef.context ? (typeof actionDef.context === 'string' ? JSON.parse(actionDef.context) : actionDef.context) : {}; } catch (e) { this.state.actionContext = {}; }

            // Parse view_mode to determine available views
            const viewModes = actionDef.view_mode
                ? actionDef.view_mode.split(',').map(m => m.trim())
                : ['list', 'form'];
            this.state.viewModes = viewModes;
            this.state.actionView = viewModes[0] === 'form' ? 'list' : viewModes[0];
            this.state.currentView = 'action';

            // Load view definitions for this action
            const cached = this._actionCache[actionDef.id];
            if (cached) {
                this._applyViewDefs(cached.views || {});
            } else {
                try {
                    const data = await RPC.call('/api/orm/load_action', { action_id: actionDef.id });
                    this._actionCache[actionDef.id] = data;
                    this._applyViewDefs(data.views || {});
                } catch (e) {
                    console.error('Failed to load action:', e);
                    this._applyViewDefs({});
                }
            }

            this._updateHash({
                class: this._modelViewToClass(actionDef.res_model, this.state.actionView),
            });
        }

        _applyViewDefs(views) {
            this.state.searchViewDef = views.search || {};
            this.state.listViewDef = views.list || {};
            this.state.formViewDef = views.form || {};
            this.state.kanbanViewDef = views.kanban || {};
            this.state.calendarViewDef = views.calendar || {};
            this.state.graphViewDef = views.graph || {};
            this.state.pivotViewDef = views.pivot || {};
            this.state.spreadsheetViewDef = views.spreadsheet || {};
        }

        async _executeActionDict(actionDict) {
            if (actionDict.type !== 'ir.actions.act_window') return;

            // Resolve activeAppId & activeMenuId from model/action
            const match = this._findAppForModelOrAction(actionDict.res_model, actionDict.id);
            if (match) {
                this.state.activeAppId = match.app.id;
                if (!this.state.activeMenuId) this.state.activeMenuId = match.menu.id;
            }

            this.state.currentAction = actionDict;
            this.state.currentModel = actionDict.res_model;
            this.state.actionTitle = actionDict.name;
            try { this.state.actionDomain = actionDict.domain ? (typeof actionDict.domain === 'string' ? JSON.parse(actionDict.domain) : actionDict.domain) : []; } catch (e) { this.state.actionDomain = []; }
            try { this.state.actionContext = actionDict.context ? (typeof actionDict.context === 'string' ? JSON.parse(actionDict.context) : actionDict.context) : {}; } catch (e) { this.state.actionContext = {}; }
            if (actionDict.res_id) {
                this.state.formRecordId = actionDict.res_id;
            }

            const viewModes = actionDict.view_mode ? actionDict.view_mode.split(',').map(m => m.trim()) : ['list'];
            this.state.viewModes = viewModes;
            this.state.actionView = (actionDict.res_id ? 'form' : (viewModes[0].trim()));
            this.state.currentView = 'action';

            try {
                const res = await RPC.loadViews(actionDict.res_model);
                if (res && res.views) {
                    this._applyViewDefs(res.views);
                }
            } catch (e) {
                console.error('Failed to load dynamic views:', e);
            }

            const hashParams = { class: this._modelViewToClass(actionDict.res_model, this.state.actionView) };
            if (actionDict.res_id || this.state.actionView === 'form') {
                hashParams.method = 'onEdit';
                if (actionDict.res_id) hashParams.id = actionDict.res_id;
            }
            this._updateHash(hashParams);
        }

        _findFirstAction(items) {
            for (const item of items) {
                if (item.action_id && item.action) return item;
                if (item.security_view) return item;
                if (item.model) return item;
                if (item.children && item.children.length > 0) {
                    const found = this._findFirstAction(item.children);
                    if (found) return found;
                }
            }
            return null;
        }

        // ── Form View Navigation ─────────────────────────

        openProfile(uid) {
            let userId = null;
            if (typeof uid === 'number' || (typeof uid === 'string' && /^\d+$/.test(uid))) {
                userId = parseInt(uid);
            } else {
                userId = (window.AdvSoftUser && window.AdvSoftUser.uid) ? window.AdvSoftUser.uid : 1;
            }
            this.state.formRecordId = userId;
            this.state.currentModel = 'res.users';
            this.state.actionTitle = 'My Profile';
            this.state.actionView = 'form';
            this._executeActionDict({
                type: 'ir.actions.act_window',
                res_model: 'res.users',
                name: 'My Profile',
                view_mode: 'form',
                res_id: userId,
            });
        }

        openRecord(recordId, index, total) {
            this.state.formRecordId = recordId;
            this.state.formIndex = index;
            this.state.formTotal = total;
            this.state.actionView = 'form';
            this._updateHash({
                class: this._modelViewToClass(this.state.currentModel, 'form'),
                method: 'onEdit',
                id: recordId,
            });
        }

        backToList() {
            // Go back to the first non-form view
            const firstView = this.state.viewModes.find(m => m !== 'form') || 'list';
            this.state.actionView = firstView;
            this._updateHash({
                class: this._modelViewToClass(this.state.currentModel, firstView),
            });
        }
        recordSaved(rec) {
            if (rec && rec.id) {
                this.state.formRecordId = rec.id;
                this._updateHash({
                    class: this._modelViewToClass(this.state.currentModel, 'form'),
                    method: 'onEdit',
                    id: rec.id,
                });
            }
        }

        navigateRecord(direction) {
            const newIndex = this.state.formIndex + direction;
            if (newIndex < 1 || newIndex > this.state.formTotal) return;
            this.state.formIndex = newIndex;
            this._fetchRecordAtIndex(newIndex);
        }

        async _fetchRecordAtIndex(index) {
            const res = await RPC.searchRead(this.state.currentModel, [], {
                order: 'id desc', limit: 1, offset: index - 1,
            });
            if (res.records && res.records.length > 0) {
                this.state.formRecordId = res.records[0].id;
                this.state.actionView = '';
                await new Promise(r => setTimeout(r, 10));
                this.state.actionView = 'form';
            }
        }

        // ── Adianti Class <-> Model/View Mapper ────────────────

        _modelViewToClass(model, viewType = 'list') {
            if (!model) return 'HomeView';
            const modelPart = model
                .split('.')
                .map(part => part.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(''))
                .join('');
            const viewPart = (viewType || 'list').charAt(0).toUpperCase() + (viewType || 'list').slice(1);
            return modelPart + viewPart;
        }

        _classToModelView(className) {
            if (!className) return null;
            const viewSuffixes = ['Form', 'Kanban', 'Calendar', 'Graph', 'Pivot', 'Spreadsheet', 'List'];
            for (const suffix of viewSuffixes) {
                if (className.endsWith(suffix) && className.length > suffix.length) {
                    const base = className.slice(0, -suffix.length);
                    const viewType = suffix.toLowerCase();
                    const foundModel = this._findModelByPascalCase(base);
                    if (foundModel) {
                        return { model: foundModel, viewType };
                    }
                }
            }
            return null;
        }

        _findModelByPascalCase(pascalName) {
            const target = pascalName.toLowerCase();
            const aliasMap = {
                'projecttask': 'task',
                'task': 'task',
                'project': 'project.project',
                'projectproject': 'project.project',
                'projecttag': 'project.tag',
                'tag': 'project.tag',
                'stage': 'stage',
                'projectstage': 'stage',
                'tasktimesheet': 'task.timesheet',
            };
            if (aliasMap[target]) return aliasMap[target];

            const allModels = [
                'project.project', 'task', 'project.task', 'task.timesheet', 'stage', 'project.tag',
                'account.move', 'account.move.line', 'account.account', 'account.journal', 'account.tax', 'account.payment',
                'showcase.model', 'res.users', 'res.groups', 'res.groups.category', 'res.partner', 'res.company',
                'ir.model', 'ir.model.access', 'ir.rule', 'ir.action', 'ir.actions.report', 'ir.ui.menu', 'ir.ui.view',
                'ir.sequence', 'ir.module.module', 'ir.config_parameter', 'saved_filter', 'spreadsheet.document'
            ];
            for (const m of allModels) {
                const clean = m.replace(/[\._]/g, '').toLowerCase();
                if (clean === target) return m;
            }
            return target;
        }

        _customViewToClass(viewType) {
            const map = {
                'security_overview': 'SecurityOverview',
                'security_access': 'AccessRights',
                'security_rules': 'RecordRules',
                'security_groups': 'SecurityGroups',
                'security_users': 'SecurityUsers',
                'menu_editor': 'MenuEditor',
                'view_builder': 'ViewBuilder',
                'accounting_reports': 'AccountingReports',
                'my_custom_page': 'MyCustomPage',
                'adianti_page': this.state?.adiantiControllerClass || 'SampleController',
                'home': 'HomeView',
            };
            return map[viewType] || viewType;
        }

        _classToCustomView(className) {
            const map = {
                'SecurityOverview': 'security_overview',
                'AccessRights': 'security_access',
                'SecurityAccess': 'security_access',
                'RecordRules': 'security_rules',
                'SecurityRules': 'security_rules',
                'SecurityGroups': 'security_groups',
                'SecurityUsers': 'security_users',
                'MenuEditor': 'menu_editor',
                'ViewBuilder': 'view_builder',
                'AccountingReports': 'accounting_reports',
                'MyCustomPage': 'my_custom_page',
                'HomeView': 'home',
            };
            return map[className] || null;
        }

        // ── URL Hash (Adianti RouterService) ─────────────

        _parseHash() {
            const raw = window.location.hash.slice(1) || window.location.search.slice(1);
            if (!raw) return;
            const params = {};
            raw.split('&').forEach(p => {
                const [k, v] = p.split('=');
                if (k) params[k] = decodeURIComponent(v || '');
            });

            // 1. Adianti standard class routing (#class=ProjectProjectForm&method=onEdit&id=3, #class=AccessRights, etc.)
            if (params.class) {
                const customView = this._classToCustomView(params.class);
                if (customView) {
                    this.openCustomView(customView);
                    return;
                }

                const modelView = this._classToModelView(params.class);
                if (modelView) {
                    const isForm = modelView.viewType === 'form' || params.method === 'onEdit' || !!params.id;
                    const viewType = isForm ? 'form' : modelView.viewType;
                    const resId = params.id ? parseInt(params.id) : null;
                    if (isForm && resId) {
                        this.state.formRecordId = resId;
                    }
                    this._executeActionDict({
                        type: 'ir.actions.act_window',
                        res_model: modelView.model,
                        name: modelView.model,
                        view_mode: viewType + ',form',
                        res_id: resId,
                    });
                    return;
                }

                // Standard Adianti Controller Fallback (TPage / TWindow)
                if (window.AdvSoftPageRegistry && window.AdvSoftPageRegistry['adianti_page']) {
                    this.state.adiantiControllerClass = params.class;
                    this.state.adiantiControllerMethod = params.method || '';
                    this.state.adiantiControllerParams = params;
                    this.openCustomView('adianti_page', false);
                    return;
                }
            }

            // 2. Legacy custom view routing (#view=security_access)
            if (params.view && window.AdvSoftPageRegistry[params.view]) {
                this.openCustomView(params.view);
                return;
            }

            // 3. Legacy model routing (#action=1&model=project.project&id=3&view_type=form)
            if (params.model) {
                const isForm = params.view_type === 'form' || params.view === 'form' || !!params.id;
                const viewType = isForm ? 'form' : (params.view_type || 'list');
                const resId = params.id ? parseInt(params.id) : null;
                if (resId) {
                    this.state.formRecordId = resId;
                }
                this._executeActionDict({
                    type: 'ir.actions.act_window',
                    res_model: params.model,
                    name: params.model,
                    view_mode: viewType + ',form',
                    res_id: resId,
                });
                return;
            }

            // 4. Legacy action id routing (#action=1)
            if (params.action) {
                const actionId = parseInt(params.action);
                for (const app of this.state.apps) {
                    if (app.action_id === actionId) {
                        this.onAppClick(app);
                        return;
                    }
                    const menuItem = this._findMenuByActionId(app.children || [], actionId);
                    if (menuItem) {
                        this.state.activeAppId = app.id;
                        this.onMenuClick(menuItem);
                        return;
                    }
                }
            }
        }

        _findMenuByActionId(items, actionId) {
            for (const item of items) {
                if (item.action_id === actionId) return item;
                if (item.children) {
                    const found = this._findMenuByActionId(item.children, actionId);
                    if (found) return found;
                }
            }
            return null;
        }

        _updateHash(params = {}) {
            let hashStr = '';
            if (params.class) {
                const parts = [`class=${params.class}`];
                if (params.method) parts.push(`method=${params.method}`);
                if (params.id) parts.push(`id=${params.id}`);
                for (const [k, v] of Object.entries(params)) {
                    if (!['class', 'method', 'id'].includes(k) && v !== undefined && v !== null) {
                        parts.push(`${k}=${encodeURIComponent(v)}`);
                    }
                }
                hashStr = parts.join('&');
            } else if (params.view) {
                const cls = this._customViewToClass(params.view);
                hashStr = `class=${cls}`;
            } else if (params.model) {
                const cls = this._modelViewToClass(params.model, params.view_type || this.state.actionView || 'list');
                const parts = [`class=${cls}`];
                if (params.view_type === 'form' || params.id) {
                    parts.push('method=onEdit');
                    if (params.id) parts.push(`id=${params.id}`);
                }
                hashStr = parts.join('&');
            }
            history.replaceState(null, '', hashStr ? '#' + hashStr : window.location.pathname);
        }
    }

    // ── Inisialisasi & Mounting (Best Practice Owl 2) ──
    document.addEventListener('DOMContentLoaded', () => {
        // 1. Setup Global Environment (Env)
        // Env digunakan untuk menyimpan objek global yang bisa diakses oleh seluruh komponen 
        // melalui `this.env` (misal: router, translations, global event bus).
        const env = {
            _t: (str) => str, // Placeholder fungsi translasi (i18n)
            services: {
                rpc: window.AdvSoftRPC
            }
        };

        // 2. Konfigurasi Aplikasi (Performa & Mode)
        const config = {
            env: env,
            
            // PERFORMA: `dev: false` akan menonaktifkan validasi internal Owl (prop types, dll).
            // Ini membuat performa rendering DOM jauh lebih cepat di lingkungan Production.
            // Ubah ke `true` hanya saat proses debugging.
            dev: false, 
            
            // ERROR HANDLING: Mencegah error diam-diam ketika state secara tidak sengaja termutasi
            warnIfMutatingProps: true,

            // Template registry global
            templates: window.TEMPLATES
        };

        // 3. Inisialisasi & Mount
        try {
            const app = new owl.App(WebClient, config);
            app.mount(document.getElementById('app'));
        } catch (e) {
            console.error("[CRITICAL] Gagal me-mount AdvSoft WebClient:", e);
            document.getElementById('app').innerHTML = `
                <div style="padding: 20px; color: red; font-family: sans-serif;">
                    <h3>Critical System Error</h3>
                    <p>WebClient gagal dimuat. Periksa konsol browser untuk detail error.</p>
                </div>
            `;
        }

        // ── Expose Standard Adianti JavaScript API ──
        window.Adianti = window.Adianti || {};
        window.Adianti.loadPage = (className, method = '', params = {}) => {
            let hash = `#class=${className}`;
            if (method) hash += `&method=${method}`;
            if (params && typeof params === 'object') {
                const q = new URLSearchParams(params).toString();
                if (q) hash += `&${q}`;
            }
            window.location.hash = hash;
        };
        window.Adianti.openPage = window.Adianti.loadPage;
        window.Adianti.currentClass = () => {
            const raw = window.location.hash.slice(1) || window.location.search.slice(1);
            const p = new URLSearchParams(raw);
            return p.get('class') || '';
        };
    });
})();


